module.exports = { html: "<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<title>CivilCareer Admin — Protected</title>\r\n<meta name=\"robots\" content=\"noindex,nofollow\">\r\n<link rel=\"stylesheet\" href=\"/styles.css\">\r\n\r\n<style>\r\nbody{background:#0b1f3a;min-height:100vh;display:flex;flex-direction:column}\r\n.admin-header{background:#0a1828;border-bottom:1px solid rgba(255,255,255,.06);padding:12px 24px;display:flex;align-items:center;justify-content:space-between}\r\n.admin-header .logo{font-weight:800;font-size:1.2rem;color:#fff;text-decoration:none}\r\n.admin-header .logo span{color:#c9973c}\r\n.admin-header .badge{background:#c9973c;color:#0b1f3a;font-size:.7rem;font-weight:800;padding:3px 10px;border-radius:20px;text-transform:uppercase;letter-spacing:.06em}\r\n\r\n.admin-body{flex:1;padding:2rem 1.5rem;max-width:1200px;margin:0 auto;width:100%}\r\n\r\n.login-wrap{display:flex;align-items:center;justify-content:center;min-height:80vh}\r\n.login-card{background:#0f2847;border:1px solid rgba(255,255,255,.1);border-radius:20px;padding:2.5rem;width:100%;max-width:400px;text-align:center}\r\n.login-card .icon{font-size:3rem;margin-bottom:1rem}\r\n.login-card h1{font-size:1.5rem;font-weight:800;color:#fff;margin-bottom:6px}\r\n.login-card p{color:#6a8aaa;font-size:.85rem;margin-bottom:1.5rem}\r\n.login-card input{width:100%;padding:12px 16px;border-radius:10px;border:1.5px solid rgba(255,255,255,.15);background:rgba(255,255,255,.06);color:#fff;font-size:1rem;font-family:inherit;text-align:center;letter-spacing:.08em;margin-bottom:12px;outline:none}\r\n.login-card input:focus{border-color:#c9973c}\r\n.login-card button{width:100%;padding:12px;background:#c9973c;color:#0b1f3a;border:none;border-radius:10px;font-weight:800;font-size:.95rem;cursor:pointer;font-family:inherit}\r\n.login-card button:hover{background:#e8b04a}\r\n.login-error{color:#fca5a5;font-size:.82rem;margin-top:8px;display:none}\r\n\r\n#dashboard{display:none}\r\n.dash-topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.5rem;flex-wrap:wrap;gap:1rem}\r\n.dash-topbar h1{font-size:1.5rem;font-weight:800;color:#fff;margin:0}\r\n.dash-topbar .sign-out{background:rgba(255,255,255,.08);color:#94a3b8;border:1px solid rgba(255,255,255,.1);border-radius:8px;padding:8px 16px;cursor:pointer;font-size:.83rem;font-weight:600;font-family:inherit}\r\n.dash-topbar .sign-out:hover{background:rgba(255,255,255,.14);color:#fff}\r\n\r\n.metrics{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px;margin-bottom:1.5rem}\r\n.metric{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:14px 16px}\r\n.metric span{font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#6a8aaa;display:block;margin-bottom:6px}\r\n.metric b{font-size:1.5rem;font-weight:800;color:#fff}\r\n\r\n.tabs{display:flex;gap:4px;margin-bottom:1.5rem;flex-wrap:wrap;background:#0a1828;padding:4px;border-radius:12px;border:1px solid rgba(255,255,255,.06)}\r\n.tabs button{padding:8px 16px;border-radius:8px;border:none;background:transparent;color:#6a8aaa;font-size:.82rem;font-weight:700;cursor:pointer;font-family:inherit;transition:all .15s}\r\n.tabs button.active{background:#c9973c;color:#0b1f3a}\r\n.tabs button:hover:not(.active){color:#fff;background:rgba(255,255,255,.06)}\r\n\r\n.panel{display:none}\r\n.panel.active{display:block}\r\n\r\n.import-box{background:#0f2847;border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:1.5rem;margin-bottom:1.5rem}\r\n.import-box h3{color:#fff;font-size:1rem;font-weight:700;margin:0 0 6px}\r\n.import-box p{color:#6a8aaa;font-size:.83rem;line-height:1.6;margin-bottom:1rem}\r\n.import-box label{display:flex;flex-direction:column;gap:5px;font-size:.78rem;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:.04em;margin-bottom:12px}\r\n.import-box label span{font-weight:500;color:#6a8aaa;font-size:.73rem;text-transform:none;letter-spacing:0}\r\n.import-box input,.import-box textarea,.import-box select{padding:9px 12px;border-radius:8px;border:1.5px solid rgba(255,255,255,.1);background:rgba(255,255,255,.05);color:#fff;font-size:.85rem;font-family:inherit;width:100%;outline:none}\r\n.import-box input:focus,.import-box textarea:focus{border-color:#c9973c}\r\n.import-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}\r\n\r\n.btn-gold{background:#c9973c;color:#0b1f3a;border:none;border-radius:8px;padding:9px 18px;font-weight:700;font-size:.85rem;cursor:pointer;font-family:inherit}\r\n.btn-ghost{background:rgba(255,255,255,.06);color:#94a3b8;border:1px solid rgba(255,255,255,.1);border-radius:8px;padding:9px 18px;font-weight:700;font-size:.85rem;cursor:pointer;font-family:inherit}\r\n.btn-ghost:hover{background:rgba(255,255,255,.12);color:#fff}\r\n\r\n.import-status{font-size:.83rem;padding:10px 14px;border-radius:8px;margin-top:10px;display:none}\r\n.import-status.show{display:block}\r\n.import-status.success{background:rgba(5,150,105,.15);color:#6ee7b7;border:1px solid rgba(5,150,105,.3)}\r\n.import-status.error{background:rgba(220,38,38,.15);color:#fca5a5;border:1px solid rgba(220,38,38,.3)}\r\n\r\n.admin-actions{display:flex;gap:8px;align-items:center;margin-bottom:12px;flex-wrap:wrap}\r\n.admin-actions .check{display:flex;align-items:center;gap:6px;font-size:.82rem;color:#94a3b8;cursor:pointer}\r\n\r\n.list-item{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:12px 16px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}\r\n.list-item-info h4{font-size:.9rem;font-weight:700;color:#fff;margin-bottom:3px}\r\n.list-item-info p{font-size:.75rem;color:#6a8aaa}\r\n.status-badge{display:inline-block;font-size:.65rem;font-weight:700;padding:2px 8px;border-radius:20px;margin-left:8px;text-transform:uppercase}\r\n.status-badge.published{background:rgba(5,150,105,.2);color:#6ee7b7}\r\n.status-badge.unpublished{background:rgba(217,119,6,.2);color:#fbbf24}\r\n.status-badge.expired{background:rgba(220,38,38,.2);color:#fca5a5}\r\n\r\n.mini-actions{display:flex;gap:5px;flex-shrink:0;flex-wrap:wrap}\r\n.mini-actions button,.mini-actions a{padding:5px 10px;border-radius:6px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.05);font-size:.73rem;font-weight:700;color:#94a3b8;cursor:pointer;font-family:inherit;text-decoration:none;transition:all .15s}\r\n.mini-actions button:hover,.mini-actions a:hover{background:rgba(255,255,255,.12);color:#fff}\r\n.mini-actions .btn-publish{border-color:rgba(5,150,105,.4);color:#6ee7b7}\r\n.mini-actions .btn-delete{border-color:rgba(220,38,38,.4);color:#fca5a5}\r\n\r\ndialog{border:none;border-radius:16px;padding:0;max-width:780px;width:calc(100% - 2rem);max-height:90vh;overflow-y:auto;background:#0f2847;box-shadow:0 20px 60px rgba(0,0,0,.6)}\r\ndialog::backdrop{background:rgba(0,0,0,.7)}\r\n.dialog-head{display:flex;justify-content:space-between;align-items:center;padding:1.25rem 1.5rem;border-bottom:1px solid rgba(255,255,255,.08);position:sticky;top:0;background:#0f2847;z-index:10}\r\n.dialog-head h2{font-size:1.1rem;font-weight:700;color:#fff;margin:0}\r\n.dialog-head button{background:none;border:none;font-size:1.5rem;cursor:pointer;color:#6a8aaa;line-height:1}\r\n.dialog-body{padding:1.5rem}\r\n.field-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}\r\n.field-grid label{display:flex;flex-direction:column;gap:4px;font-size:.75rem;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:.04em}\r\n.field-grid label.wide{grid-column:1/-1}\r\n.field-grid input,.field-grid select,.field-grid textarea{padding:9px 12px;border-radius:8px;border:1.5px solid rgba(255,255,255,.1);background:rgba(255,255,255,.05);color:#fff;font-size:.85rem;font-family:inherit;outline:none;width:100%}\r\n.field-grid input:focus,.field-grid select:focus,.field-grid textarea:focus{border-color:#c9973c}\r\n.field-grid select option{background:#0f2847;color:#fff}\r\n.field-grid textarea{resize:vertical;min-height:90px}\r\n.field-grid .btn-save{grid-column:1/-1;padding:11px;background:#c9973c;color:#0b1f3a;border:none;border-radius:9px;font-weight:800;font-size:.95rem;cursor:pointer;font-family:inherit;margin-top:8px}\r\n.save-status{font-size:.83rem;padding:10px 14px;border-radius:8px;display:none;margin-top:8px;grid-column:1/-1}\r\n.gov-only-field{transition:opacity .15s}\r\n.gov-only-field.hint{position:relative}\r\n.save-status.show{display:block}\r\n.save-status.success{background:rgba(5,150,105,.15);color:#6ee7b7}\r\n.save-status.error{background:rgba(220,38,38,.15);color:#fca5a5}\r\n\r\n.analytics-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}\r\n.dash-card{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:1.25rem}\r\n.dash-card h3{font-size:.85rem;font-weight:700;color:#94a3b8;text-transform:uppercase;letter-spacing:.06em;margin-bottom:1rem}\r\n.bar-row{display:flex;align-items:center;gap:8px;margin-bottom:8px;font-size:.78rem}\r\n.bar-row span{width:80px;color:#6a8aaa;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex-shrink:0}\r\n.bar-row b{width:36px;text-align:right;font-weight:700;color:#fff;flex-shrink:0}\r\n.bar{flex:1;height:7px;background:rgba(255,255,255,.06);border-radius:4px;overflow:hidden}\r\n.bar i{display:block;height:100%;background:#c9973c;border-radius:4px}\r\n\r\n.email-detection{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:end;margin-top:12px}\r\n\r\n.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%) translateY(20px);background:#1e293b;color:#fff;padding:10px 22px;border-radius:10px;font-size:.88rem;font-weight:600;opacity:0;transition:all .25s;z-index:9999;pointer-events:none;white-space:nowrap;border:1px solid rgba(255,255,255,.1)}\r\n.toast.show{opacity:1;transform:translateX(-50%) translateY(0)}\r\n\r\n@media(max-width:600px){\r\n  .admin-body{padding:1rem}\r\n  .admin-header{padding:12px 16px}\r\n  .field-grid{grid-template-columns:1fr}\r\n  .field-grid label.wide{grid-column:auto}\r\n  .email-detection{grid-template-columns:1fr}\r\n}\r\n\r\n.discovery-controls{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:18px;margin-bottom:14px}\r\n.discovery-grid{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:10px;align-items:end}\r\n.discovery-grid label{display:flex;flex-direction:column;gap:6px;color:#94a3b8;font-size:.72rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em}\r\n.discovery-grid input,.discovery-grid select{width:100%;padding:10px 12px;border-radius:8px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.05);color:#fff;font:inherit;text-transform:none;letter-spacing:normal}\r\n.discovery-note{color:#6a8aaa;font-size:.76rem;line-height:1.5;margin-top:10px}\r\n.discovery-status{display:none;margin-top:10px;padding:9px 12px;border-radius:8px;font-size:.8rem}\r\n.discovery-status.show{display:block;background:rgba(5,150,105,.12);color:#6ee7b7;border:1px solid rgba(5,150,105,.25)}\r\n.discovery-status.error{background:rgba(220,38,38,.12);color:#fca5a5;border-color:rgba(220,38,38,.25)}\r\n.discovery-results{display:grid;gap:9px}\r\n.discovery-result{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:11px;padding:14px 16px;display:flex;justify-content:space-between;gap:14px;align-items:center}\r\n.discovery-result h4{font-size:.9rem;color:#fff;margin:0 0 5px;line-height:1.35}\r\n.discovery-result p{font-size:.74rem;color:#6a8aaa;margin:0 0 5px;line-height:1.45}\r\n.discovery-result a{font-size:.7rem;color:#c9973c;word-break:break-all}\r\n.discovery-actions{display:flex;gap:7px;flex-wrap:wrap;flex-shrink:0}\r\n.discovery-score{display:inline-block;font-size:.65rem;color:#6ee7b7;background:rgba(16,185,129,.1);border:1px solid rgba(16,185,129,.2);padding:3px 6px;border-radius:999px;margin-left:5px}\r\n@media(max-width:850px){.discovery-grid{grid-template-columns:1fr 1fr}.discovery-grid .wide{grid-column:1/-1}.discovery-result{align-items:flex-start;flex-direction:column}.discovery-actions{width:100%}}\r\n@media(max-width:560px){.discovery-grid{grid-template-columns:1fr}}\r\n\r\n/* Phase 7 — Source Health Panel */\r\n.source-health-panel{background:#0a1c35;border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:14px 16px;margin-bottom:14px;display:none}\r\n.source-health-panel.show{display:block}\r\n.source-health-title{color:#94a3b8;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.07em;margin:0 0 10px}\r\n.source-health-table{width:100%;border-collapse:collapse;font-size:.78rem}\r\n.source-health-table th{color:#4a6a8a;font-weight:600;text-align:left;padding:5px 8px;border-bottom:1px solid rgba(255,255,255,.06)}\r\n.source-health-table td{padding:6px 8px;border-bottom:1px solid rgba(255,255,255,.04);vertical-align:middle;color:#cbd5e1}\r\n.source-health-table tr:last-child td{border-bottom:none}\r\n.sh-ok{color:#6ee7b7}.sh-error{color:#fca5a5}.sh-warn{color:#fbbf24}.sh-nc{color:#4a6a8a}\r\n.discovery-summary{font-size:.78rem;color:#6a8aaa;padding:8px 12px;border-radius:8px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);margin-bottom:10px;display:none;line-height:1.7}\r\n.discovery-summary.show{display:block}\r\n.discovery-summary strong{color:#cbd5e1}\r\n\r\n/* Phase 7 — Upgraded result cards */\r\n.dr-meta{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:4px 0 6px}\r\n.dr-source-badge{font-size:.65rem;padding:2px 8px;border-radius:999px;background:rgba(201,151,60,.12);color:#c9973c;border:1px solid rgba(201,151,60,.25);font-weight:600;white-space:nowrap}\r\n.dr-date{font-size:.68rem;color:#6a8aaa}\r\n.dr-date.unknown{color:#4a6a8a;font-style:italic}\r\n.dr-company{font-size:.78rem;color:#94a3b8;font-weight:600}\r\n.btn-review{background:rgba(201,151,60,.15);color:#c9973c;border:1px solid rgba(201,151,60,.35);border-radius:7px;padding:6px 12px;font-size:.75rem;font-weight:700;cursor:pointer;white-space:nowrap}\r\n.btn-review:hover{background:rgba(201,151,60,.25)}\r\n.btn-reject{background:rgba(220,38,38,.1);color:#fca5a5;border:1px solid rgba(220,38,38,.25);border-radius:7px;padding:6px 12px;font-size:.75rem;font-weight:700;cursor:pointer;white-space:nowrap}\r\n.btn-reject:hover{background:rgba(220,38,38,.2)}\r\n.btn-open-src{background:transparent;color:#6a8aaa;border:1px solid rgba(255,255,255,.1);border-radius:7px;padding:6px 12px;font-size:.75rem;font-weight:600;cursor:pointer;text-decoration:none;display:inline-block;white-space:nowrap}\r\n.btn-open-src:hover{color:#cbd5e1;border-color:rgba(255,255,255,.2)}\r\n\r\n/* Phase 7 — Review Queue */\r\n.review-queue-section{margin-top:20px;display:none}\r\n.review-queue-section.show{display:block}\r\n.review-queue-title{color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.07em;margin:0 0 10px;display:flex;align-items:center;gap:8px}\r\n.review-queue-title .rq-count{background:rgba(201,151,60,.2);color:#c9973c;border-radius:999px;padding:1px 8px;font-size:.68rem}\r\n.rq-empty{font-size:.8rem;color:#4a6a8a;padding:10px 0}\r\n\r\n/* Phase 7 — Review detail modal */\r\n.review-modal-overlay{display:none;position:fixed;inset:0;background:rgba(5,15,30,.88);z-index:9000;overflow-y:auto;padding:24px 16px}\r\n.review-modal-overlay.show{display:flex;align-items:flex-start;justify-content:center}\r\n.review-modal{background:#0f2847;border:1px solid rgba(255,255,255,.12);border-radius:16px;max-width:680px;width:100%;padding:24px;position:relative}\r\n.review-modal h3{color:#fff;font-size:1.05rem;margin:0 0 4px}\r\n.review-modal .rm-company{color:#94a3b8;font-size:.85rem;margin:0 0 14px}\r\n.review-modal .rm-field{margin-bottom:10px}\r\n.review-modal .rm-label{color:#4a6a8a;font-size:.68rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;display:block;margin-bottom:2px}\r\n.review-modal .rm-value{color:#cbd5e1;font-size:.82rem;line-height:1.55}\r\n.review-modal .rm-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px;padding-top:14px;border-top:1px solid rgba(255,255,255,.08)}\r\n/* Agent Reach inbox */\r\n.ar-item{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-left:3px solid rgba(251,191,36,.5);border-radius:11px;padding:14px 16px;margin-bottom:10px;display:flex;justify-content:space-between;gap:14px}\r\n.ar-item.ar-job{border-left-color:rgba(96,165,250,.5)}\r\n.ar-item.ar-material{border-left-color:rgba(16,185,129,.5)}\r\n.ar-item.ar-rejected{border-left-color:rgba(220,38,38,.5);opacity:.65}\r\n.ar-item h4{font-size:.9rem;color:#fff;margin:0 0 5px;line-height:1.35}\r\n.ar-item p{font-size:.74rem;color:#6a8aaa;margin:0 0 5px;line-height:1.45}\r\n.ar-item a{font-size:.7rem;color:#c9973c;word-break:break-all}\r\n.ar-actions{display:flex;gap:7px;flex-wrap:wrap;flex-shrink:0;align-items:flex-start}\r\n.ar-badge{display:inline-block;font-size:.6rem;background:rgba(251,191,36,.12);color:#fbbf24;border:1px solid rgba(251,191,36,.25);border-radius:999px;padding:2px 7px;font-weight:600;margin-left:5px;vertical-align:middle}\r\n@media(max-width:850px){.ar-item{align-items:flex-start;flex-direction:column}.ar-actions{width:100%}}\r\n.rm-close{position:absolute;top:14px;right:16px;background:transparent;border:none;color:#6a8aaa;font-size:1.3rem;cursor:pointer;line-height:1;padding:0}\r\n.rm-close:hover{color:#fff}\r\n@media(max-width:560px){.review-modal{padding:16px}.review-modal .rm-actions{flex-direction:column}}\r\n\r\n</style>\r\n<script src=\"/theme.js\"></script>\r\n<style id=\"admin-jobs-bulk-style\">\r\n.admin-jobs-bulkbar{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:0 0 12px;padding:10px 14px;border:1px solid rgba(255,255,255,.14);border-radius:10px;background:#102a49;min-height:48px}\r\n.admin-jobs-bulkbar label{display:flex;align-items:center;gap:8px;color:#dbe7f5;font-size:.82rem;font-weight:700;cursor:pointer}\r\n.admin-jobs-bulkbar input{width:17px;height:17px;margin:0;accent-color:#c9973c}\r\n.admin-jobs-selected-count{font-size:.8rem;color:#8ea8c4;min-width:70px}\r\n.admin-jobs-bulkbar button{cursor:pointer}\r\n.admin-job-row{display:grid;grid-template-columns:30px minmax(0,1fr) auto;align-items:center;gap:14px}\r\n.admin-job-row .admin-job-select{width:18px;height:18px;margin:0;accent-color:#c9973c}\r\n.admin-job-row .list-item-info{min-width:0}\r\n.admin-job-row .list-item-info h4{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin:0 0 4px}\r\n.admin-job-row .list-item-info h4 .status-badge{margin-left:0}\r\n.admin-job-row .list-item-info p{margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\r\n.admin-job-row .mini-actions{justify-content:flex-end;align-items:center;flex-wrap:nowrap}\r\n@media (max-width:760px){\r\n  .admin-job-row{grid-template-columns:28px minmax(0,1fr);align-items:start}\r\n  .admin-job-row .mini-actions{grid-column:2;justify-content:flex-start;flex-wrap:wrap}\r\n  .admin-job-row .list-item-info p{white-space:normal}\r\n}\r\n</style>\r\n</head>\r\n\r\n<body>\r\n\r\n<div class=\"admin-header\">\r\n  <a href=\"/\" class=\"logo\">Civil<span>Career</span></a>\r\n  <span class=\"badge\">🔐 Admin</span>\r\n</div>\r\n\r\n<div class=\"admin-body\">\r\n\r\n<div class=\"login-wrap\" id=\"loginWrap\">\r\n  <div class=\"login-card\">\r\n    <div class=\"icon\">🔐</div>\r\n    <h1>Admin Dashboard</h1>\r\n    <p>Sign in with the administrator account. Access is allowlisted and verified server-side.</p>\r\n    <input type=\"email\" id=\"adminEmail\" placeholder=\"Administrator email\" autocomplete=\"username\">\r\n    <input type=\"password\" id=\"adminPassword\" placeholder=\"Password\" autocomplete=\"current-password\">\r\n    <button onclick=\"doLogin()\">Sign in →</button>\r\n    <div class=\"login-error\" id=\"loginError\">Administrator sign-in failed. Please check your credentials.</div>\r\n  </div>\r\n</div>\r\n\r\n<div id=\"dashboard\">\r\n\r\n<div class=\"dash-topbar\">\r\n  <div>\r\n    <p style=\"color:#6a8aaa;font-size:.72rem;text-transform:uppercase;font-weight:700;letter-spacing:.06em;margin-bottom:4px\">Founder / Product Owner</p>\r\n    <h1>CivilCareer Overview</h1>\r\n  </div>\r\n  <button class=\"sign-out\" onclick=\"signOut()\">Sign out</button>\r\n</div>    <h3 class=\"kpi-title\">Weekly KPI report</h3>\r\n    <div class=\"metrics\" id=\"kpiReport\" style=\"margin-top:.5rem\"><p>Loading KPIs…</p></div>\r\n    <div class=\"metrics\" id=\"metrics\">\r\n  <div class=\"metric\"><span>Loading</span><b>…</b></div>\r\n</div>\r\n\r\n<div class=\"tabs\" id=\"tabs\">\r\n  <button class=\"active\" data-tab=\"analytics\">Analytics</button>\r\n  <button data-tab=\"jobs\">Jobs</button>\r\n  <button data-tab=\"discovery\">Discovery</button>\r\n  <button data-tab=\"agent-reach\">Agent Reach</button>\r\n  <button data-tab=\"exams\">Exams</button>\r\n  <button data-tab=\"exam-tracker\">Exam Tracker</button>\r\n  <button data-tab=\"social\">Social Engine</button>\r\n  <button data-tab=\"salary\">Salary</button>\r\n  <button data-tab=\"walkins\">Walk-Ins</button>\r\n  <button data-tab=\"subscribers\">Subscribers</button>\r\n  <button data-tab=\"reviews\">Reviews</button>\r\n  <button data-tab=\"blog\">Blog</button>\r\n  <button data-tab=\"interview\">Interview Q&A</button>\r\n  <button data-tab=\"materials\">Materials</button>\r\n  <button data-tab=\"submissions\">Submissions</button>\r\n  <button data-tab=\"reports\">Reports</button>\r\n  <button data-tab=\"contact\">Contact</button>\r\n  <button data-tab=\"review-jobs\">⚡ Review Jobs</button>\r\n  <button data-tab=\"govt\">🏛 Government Jobs</button>\r\n  <button data-tab=\"collector\">📥 Job Collector</button>\r\n  <button data-tab=\"inbox\">📬 Job Inbox</button>\r\n</div>\r\n\r\n<div class=\"panel active\" id=\"panel-analytics\">\r\n  <div class=\"analytics-grid\" id=\"analyticsPanel\">\r\n    <div class=\"dash-card\"><p style=\"color:#6a8aaa;font-size:.85rem\">Loading analytics…</p></div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-jobs\">\r\n\r\n<div class=\"import-box\">\r\n\r\n<p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">\r\nAI-assisted job importer\r\n</p>\r\n\r\n<h3>Import from a link or pasted vacancy text</h3>\r\n\r\n<p>Paste the vacancy URL, job description, or both. AI extracts the fields. You review everything before saving.</p>\r\n\r\n<label>\r\nVacancy URL\r\n<span>LinkedIn, Naukri, company careers, government site</span>\r\n<input type=\"url\" id=\"importJobUrl\" placeholder=\"https://...\">\r\n</label>\r\n\r\n<label>\r\nVacancy text / description\r\n<span>Paste full job post, WhatsApp message, or vacancy description</span>\r\n<textarea id=\"importJobText\" rows=\"6\" placeholder=\"Site Engineer — XYZ Company, Bengaluru. BE Civil, 3 years experience...\"></textarea>\r\n</label>\r\n\r\n<div class=\"email-detection\">\r\n\r\n<label>\r\nDetected emails\r\n<select id=\"detectedEmailSelect\">\r\n<option value=\"\">No email detected yet</option>\r\n</select>\r\n</label>\r\n\r\n<button class=\"btn-ghost\" id=\"useDetectedEmail\" onclick=\"useDetectedEmailFn()\">Use selected</button>\r\n\r\n</div>\r\n\r\n<label style=\"margin-top:12px\">\r\nApplication email\r\n<span>Editable — manual value is never overwritten automatically</span>\r\n<input type=\"email\" id=\"importApplicationEmail\" placeholder=\"hr@company.com\">\r\n</label>\r\n\r\n<div class=\"import-actions\">\r\n<button class=\"btn-gold\" id=\"importJobBtn\" onclick=\"importJobLink()\">Extract & fill fields</button>\r\n<button class=\"btn-ghost\" onclick=\"clearJobImport()\">Clear</button>\r\n</div>\r\n\r\n<div class=\"import-status\" id=\"importJobStatus\"></div>\r\n\r\n<p style=\"font-size:.75rem;color:#4a6a8a;margin-top:10px\">\r\nAI never publishes automatically. Verify every field before saving.\r\n</p>\r\n\r\n</div>\r\n\r\n<div class=\"admin-actions\">\r\n<button class=\"btn-ghost\" onclick=\"jobEditor()\">+ Add manually</button>\r\n<label>\r\nStatus\r\n<select id=\"adminJobStatusFilter\" onchange=\"loadAll(1)\">\r\n<option value=\"all\">All jobs</option>\r\n<option value=\"published\">Published</option>\r\n<option value=\"deleted\">Deleted</option>\r\n<option value=\"needs_edit\">Needs to be edited</option>\r\n</select>\r\n</label>\r\n<label class=\"check\">\r\n<input type=\"checkbox\" id=\"showExpiredAdmin\" checked onchange=\"loadAdminJobs()\">\r\nShow expired\r\n</label>\r\n</div>\r\n\r\n<div id=\"admin-jobs-bulkbar\" class=\"admin-jobs-bulkbar\">\r\n  <label><input id=\"admin-jobs-select-all\" type=\"checkbox\"> Select all</label>\r\n  <span id=\"admin-jobs-selected-count\" class=\"admin-jobs-selected-count\">0 selected</span>\r\n  <button id=\"admin-jobs-delete-selected\" class=\"btn-ghost\" type=\"button\" disabled>Delete selected</button>\r\n</div>\r\n\r\n<div id=\"adminJobs\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading jobs…</p>\r\n</div>\r\n\r\n<div id=\"adminJobsPager\"></div>\r\n\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-discovery\">\r\n\r\n  <!-- Search Controls -->\r\n  <div class=\"discovery-controls\">\r\n    <p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">Automatic civil-job discovery</p>\r\n    <h3 style=\"color:#fff;font-size:1rem;margin:0 0 6px\">Civil vacancies for India, discovered every 4 hours</h3>\r\n    <p class=\"discovery-note\" style=\"margin-top:0\">Every 4 hours the free discovery pipeline checks public job feeds, vacancy news and the career pages of Indian construction, infrastructure and real-estate companies. Every lead is India-only and civil-only, so nothing irrelevant reaches the queue. New matches are saved as unpublished drafts for your review. Nothing is published automatically.</p>\r\n    <div class=\"discovery-grid\" style=\"margin-top:14px\">\r\n      <label class=\"wide\">Search query\r\n        <input id=\"discoveryQuery\" value=\"civil engineering jobs India\" placeholder=\"civil engineer jobs India\">\r\n      </label>\r\n      <label>Location\r\n        <input id=\"discoveryLocation\" placeholder=\"Bengaluru / Mumbai / India\">\r\n      </label>\r\n      <label>Type\r\n        <select id=\"discoveryType\">\r\n          <option value=\"all\">All jobs</option>\r\n          <option value=\"private\">Private</option>\r\n          <option value=\"government\">Government</option>\r\n          <option value=\"mnc\">MNC / large employers</option>\r\n        </select>\r\n      </label>\r\n      <button class=\"btn-gold\" id=\"discoverySearchBtn\" type=\"button\">Search Now</button>\r\n    </div>\r\n    <div class=\"discovery-status\" id=\"discoveryStatus\"></div>\r\n  </div>\r\n\r\n  <!-- Setup guide: free-first discovery -- no paid key required -->\r\n  <div class=\"source-health-panel show\" id=\"setupGuidePanel\" style=\"border-color:rgba(201,151,60,.25)\">\r\n    <p class=\"source-health-title\" style=\"color:#c9973c\">✓ Free-first discovery is enabled</p>\r\n    <p style=\"color:#94a3b8;font-size:.78rem;margin:0 0 10px;line-height:1.6\">\r\n      Search Now uses public feeds and company career pages that do not require a paid API. Every result still passes CivilCareer's India-only, civil-only, freshness and duplicate checks, and every match enters the review queue as an unpublished draft.\r\n    </p>\r\n    <div style=\"display:flex;gap:8px;flex-wrap:wrap;font-size:.72rem\">\r\n      <span class=\"ar-badge\">No paid API required</span>\r\n      <span class=\"ar-badge\">India-only filtering</span>\r\n      <span class=\"ar-badge\">Civil-only filtering</span>\r\n      <span class=\"ar-badge\">Manual publish</span>\r\n    </div>\r\n    <p style=\"font-size:.7rem;color:#6a8aaa;margin:10px 0 0\">Optional free-provider credentials can increase coverage later, but they are not required for the built-in scan.</p>\r\n  </div>\r\n\r\n  <!-- Source Health Panel (populated after search) -->\r\n  <div class=\"source-health-panel\" id=\"sourceHealthPanel\">\r\n    <p class=\"source-health-title\">Source Status</p>\r\n    <table class=\"source-health-table\" id=\"sourceHealthTable\">\r\n      <thead><tr><th>Source</th><th>Status</th><th>Jobs found</th><th>Note</th></tr></thead>\r\n      <tbody id=\"sourceHealthBody\"></tbody>\r\n    </table>\r\n  </div>\r\n\r\n  <!-- Diagnostics summary (populated after search) -->\r\n  <div class=\"discovery-summary\" id=\"discoverySummary\"></div>\r\n\r\n  <!-- Result cards -->\r\n  <div id=\"discoveryResults\" class=\"discovery-results\">\r\n    <div class=\"dash-card\"><p style=\"color:#6a8aaa;font-size:.82rem\">Press <strong style=\"color:#c9973c\">Search Now</strong> to discover fresh civil engineering jobs from multiple sources.</p></div>\r\n  </div>\r\n\r\n  <!-- Review Queue (drafts from latest search run) -->\r\n  <div class=\"review-queue-section\" id=\"reviewQueueSection\">\r\n    <p class=\"review-queue-title\">\r\n      Review Queue — Pending Drafts\r\n      <span class=\"rq-count\" id=\"reviewQueueCount\">0</span>\r\n    </p>\r\n    <div id=\"reviewQueueList\">\r\n      <p class=\"rq-empty\">No pending drafts.</p>\r\n    </div>\r\n  </div>\r\n\r\n</div>\r\n\r\n<!-- Review Detail Modal -->\r\n<div class=\"review-modal-overlay\" id=\"reviewModalOverlay\">\r\n  <div class=\"review-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"rmTitle\">\r\n    <button class=\"rm-close\" id=\"rmClose\" aria-label=\"Close review\">&times;</button>\r\n    <h3 id=\"rmTitle\">—</h3>\r\n    <p class=\"rm-company\" id=\"rmCompany\">—</p>\r\n\r\n    <div class=\"rm-field\">\r\n      <span class=\"rm-label\">Location</span>\r\n      <span class=\"rm-value\" id=\"rmLocation\">—</span>\r\n    </div>\r\n    <div class=\"rm-field\">\r\n      <span class=\"rm-label\">Source</span>\r\n      <span class=\"rm-value\" id=\"rmSource\">—</span>\r\n    </div>\r\n    <div class=\"rm-field\">\r\n      <span class=\"rm-label\">Posted</span>\r\n      <span class=\"rm-value\" id=\"rmPosted\">—</span>\r\n    </div>\r\n    <div class=\"rm-field\">\r\n      <span class=\"rm-label\">Application / Original URL</span>\r\n      <span class=\"rm-value\"><a id=\"rmUrl\" href=\"#\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#c9973c;word-break:break-all\">—</a></span>\r\n    </div>\r\n    <div class=\"rm-field\">\r\n      <span class=\"rm-label\">Description</span>\r\n      <span class=\"rm-value\" id=\"rmDescription\" style=\"white-space:pre-wrap\">—</span>\r\n    </div>\r\n\r\n    <div class=\"rm-actions\">\r\n      <button class=\"btn-gold\" id=\"rmPublish\">Publish</button>\r\n      <button class=\"btn-review\" id=\"rmEdit\">Open in Editor</button>\r\n      <button class=\"btn-reject\" id=\"rmReject\">Reject &amp; Delete</button>\r\n      <button class=\"btn-open-src\" id=\"rmOpenSrc\" target=\"_blank\" rel=\"noopener noreferrer\">Open Original ↗</button>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<!-- Government Jobs review / edit modal -->\r\n<div class=\"review-modal-overlay\" id=\"govtModalOverlay\">\r\n  <div class=\"review-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"govtModalTitle\">\r\n    <button class=\"rm-close\" id=\"govtModalClose\" aria-label=\"Close\">&times;</button>\r\n    <h3 id=\"govtModalTitle\">—</h3>\r\n    <p class=\"rm-company\" id=\"govtModalSub\">—</p>\r\n    <div id=\"govtModalFields\"></div>\r\n    <div class=\"rm-actions\" id=\"govtModalActions\"></div>\r\n  </div>\r\n</div>\r\n\r\n<!-- Agent Reach Review Detail Modal -->\r\n<div class=\"review-modal-overlay\" id=\"agentReachModalOverlay\">\r\n  <div class=\"review-modal\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"arTitle\">\r\n    <button class=\"rm-close\" id=\"arClose\" aria-label=\"Close review\">&times;</button>\r\n    <h3 id=\"arTitle\">—</h3>\r\n    <p class=\"rm-company\" id=\"arCompany\">—</p>\r\n    <div id=\"arFields\"></div>\r\n    <div class=\"rm-actions\">\r\n      <button class=\"btn-gold\" id=\"arPublish\">Publish</button>\r\n      <button class=\"btn-review\" id=\"arEdit\">Open in Editor</button>\r\n      <button class=\"btn-reject\" id=\"arReject\">Reject</button>\r\n      <a class=\"btn-open-src\" id=\"arOpenSrc\" href=\"#\" target=\"_blank\" rel=\"noopener noreferrer\">Open Original ↗</a>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-agent-reach\">\r\n  <p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin:0 0 6px\">Agent Reach inbox — pending review</p>\r\n  <p style=\"color:#6a8aaa;font-size:.78rem;line-height:1.6;margin:0 0 14px\">\r\n    Jobs, notes and videos collected by Agent Reach (which runs on your own machine) and delivered to\r\n    <code>/api/agent-reach-ingest</code>. Everything arrives as <strong style=\"color:#fbbf24\">Pending Review</strong> —\r\n    Agent Reach never publishes directly. Verify the original source, edit if needed, then publish explicitly.\r\n  </p>\r\n\r\n  <!-- BLOCK A — Built-in free civil job scan -->\r\n  <div class=\"dash-card\" style=\"margin-bottom:14px;border-color:rgba(201,151,60,.2)\">\r\n    <h3 style=\"color:#c9973c\">🔎 Free Civil Job Scan</h3>\r\n    <p style=\"color:#94a3b8;font-size:.82rem;margin-bottom:4px\">Run the same zero-cost public/company-source discovery pipeline without leaving Agent Reach.</p>\r\n    <p style=\"color:#6a8aaa;font-size:.76rem;margin-bottom:12px\">Results are saved as <strong style=\"color:#fbbf24\">Pending Review</strong>. Nothing is published automatically.</p>\r\n    <div class=\"admin-actions\" style=\"margin-bottom:0\">\r\n      <button id=\"arJobScanBtn\" class=\"btn-gold\" onclick=\"arRunJobScan()\">▶ Scan Civil Jobs</button>\r\n      <button class=\"btn-ghost\" type=\"button\" onclick=\"document.querySelector('[data-tab=\\\"discovery\\\"]').click()\">Open Discovery</button>\r\n    </div>\r\n    <div id=\"arJobScanStatus\" style=\"display:none;margin-top:10px;color:#94a3b8;font-size:.82rem\"></div>\r\n  </div>\r\n\r\n  <!-- BLOCK B — Exam Alerts Scanner -->\r\n\r\n  <div class=\"dash-card\" style=\"margin-bottom:14px;border-color:rgba(201,151,60,.2)\">\r\n    <h3 style=\"color:#c9973c\">🔔 Exam Alerts Scanner</h3>\r\n    <p style=\"color:#94a3b8;font-size:.82rem;margin-bottom:4px\">Scrapes UPSC, SSC, RRB and Employment News for new civil exam notifications</p>\r\n    <p style=\"color:#6a8aaa;font-size:.76rem;margin-bottom:12px\">Runs automatically every Monday · results go to Exams tab for review</p>\r\n    <div class=\"admin-actions\" style=\"margin-bottom:0\">\r\n      <button id=\"arExamScanBtn\" class=\"btn-gold\" onclick=\"arRunExamScan()\">▶ Scan Now</button>\r\n    </div>\r\n    <div id=\"arExamScanStatus\" style=\"display:none;margin-top:10px;color:#94a3b8;font-size:.82rem\"></div>\r\n    <div id=\"arExamScanResults\" style=\"display:none;margin-top:10px\"></div>\r\n  </div>\r\n\r\n  <!-- BLOCK C — YouTube Transcriber -->\r\n  <div class=\"dash-card\" style=\"margin-bottom:14px;border-color:rgba(201,151,60,.2)\">\r\n    <h3 style=\"color:#c9973c\">🎬 YouTube Study Materials</h3>\r\n    <p style=\"color:#94a3b8;font-size:.82rem;margin-bottom:12px\">Paste a YouTube URL — transcript is extracted and saved as a draft</p>\r\n    <div style=\"display:flex;flex-direction:column;gap:8px;margin-bottom:12px\">\r\n      <input id=\"arYtUrl\" type=\"url\" placeholder=\"https://youtube.com/watch?v=…\"\r\n        style=\"background:#071828;border:1px solid rgba(255,255,255,.12);border-radius:8px;color:#e2e8f0;padding:8px 12px;font-size:.85rem;width:100%;box-sizing:border-box\">\r\n      <input id=\"arYtTitle\" type=\"text\" placeholder=\"Custom title (optional)\"\r\n        style=\"background:#071828;border:1px solid rgba(255,255,255,.12);border-radius:8px;color:#e2e8f0;padding:8px 12px;font-size:.85rem;width:100%;box-sizing:border-box\">\r\n      <select id=\"arYtCategory\"\r\n        style=\"background:#071828;border:1px solid rgba(255,255,255,.12);border-radius:8px;color:#e2e8f0;padding:8px 12px;font-size:.85rem;width:100%;box-sizing:border-box\">\r\n        <option value=\"\">Auto-detect category</option>\r\n        <option value=\"GATE / ESE Prep\">GATE / ESE Prep</option>\r\n        <option value=\"SSC JE / RRB JE\">SSC JE / RRB JE</option>\r\n        <option value=\"Structural Engineering\">Structural Engineering</option>\r\n        <option value=\"Transportation\">Transportation</option>\r\n        <option value=\"Geotechnical\">Geotechnical</option>\r\n        <option value=\"Fluid Mechanics\">Fluid Mechanics</option>\r\n        <option value=\"Surveying\">Surveying</option>\r\n        <option value=\"Quantity Surveying\">Quantity Surveying</option>\r\n        <option value=\"Civil Engineering\">Civil Engineering</option>\r\n      </select>\r\n    </div>\r\n    <div class=\"admin-actions\" style=\"margin-bottom:0\">\r\n      <button id=\"arYtBtn\" class=\"btn-gold\" onclick=\"arRunYtTranscribe()\">▶ Transcribe</button>\r\n    </div>\r\n    <div id=\"arYtStatus\" style=\"display:none;margin-top:10px;color:#94a3b8;font-size:.82rem\"></div>\r\n    <div id=\"arYtPreview\" style=\"display:none;margin-top:10px;background:#071828;border:1px solid rgba(255,255,255,.08);border-radius:8px;padding:12px;font-size:.82rem;color:#94a3b8\"></div>\r\n  </div>\r\n\r\n  <div class=\"admin-actions\">\r\n    <button class=\"btn-ghost\" onclick=\"loadAgentReach()\">Refresh</button>\r\n    <label class=\"check\">\r\n      <input type=\"checkbox\" id=\"arShowRejected\" onchange=\"renderAgentReachInbox()\">\r\n      Show rejected\r\n    </label>\r\n  </div>\r\n  <div id=\"agentReachInbox\">\r\n    <p style=\"color:#6a8aaa;font-size:.85rem\">Loading inbox…</p>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-exams\">\r\n\r\n<div class=\"import-box\">\r\n<p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">\r\nNotification reader\r\n</p>\r\n\r\n<h3>Import an official exam PDF</h3>\r\n<p>Select a text-based government notification PDF.</p>\r\n\r\n<div class=\"import-actions\">\r\n<input type=\"file\" id=\"importExamPdf\" accept=\"application/pdf,.pdf\">\r\n<button class=\"btn-gold\" id=\"importExamBtn\" onclick=\"importExamPdf()\">Read PDF</button>\r\n</div>\r\n\r\n<div class=\"import-status\" id=\"importExamStatus\"></div>\r\n</div>\r\n\r\n<div class=\"admin-actions\">\r\n<button class=\"btn-ghost\" onclick=\"examEditor()\">+ Add manually</button>\r\n</div>\r\n\r\n<div id=\"adminExams\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading exams…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-exam-tracker\">\r\n\r\n<div class=\"import-box\">\r\n<p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">\r\nExam tracker — public page /exam-tracker\r\n</p>\r\n\r\n<h3>Civil engineering exam tracker</h3>\r\n<p>Every row below appears on the public <a href=\"/exam-tracker\" target=\"_blank\" rel=\"noopener\" style=\"color:#c9973c\">Exam Tracker page</a>. Setting a status to <b style=\"color:#6ee7b7\">Applications Open</b> routes an announcement through the <b>Social Engine</b> — once per change. With <i>Require approval</i> ON it waits in the Social tab for review; with it OFF it publishes straight to the channel (Truth Lock and daily caps still enforced). Dates use the date picker; the exam date also accepts text such as “Feb 1-16, 2026”.</p>\r\n\r\n<div class=\"import-actions\">\r\n<button class=\"btn-gold\" onclick=\"loadExamTracker()\">⟳ Refresh</button>\r\n<button class=\"btn-ghost\" onclick=\"examTrackerEditor()\">+ Add new exam</button>\r\n</div>\r\n\r\n<div class=\"import-status\" id=\"examTrackerStatus\"></div>\r\n</div>\r\n\r\n<div id=\"adminExamTracker\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading exam tracker…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-social\">\r\n\r\n<div class=\"import-box\">\r\n<p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">\r\nSocial Content Engine — v27\r\n</p>\r\n\r\n<h3>Social queue, connections &amp; settings</h3>\r\n<p>Every Telegram, LinkedIn and Instagram post starts here as a <b>suggestion</b> built from a verified exam, job or government-vacancy record. Approve it, then publish: the engine enforces the <b>Truth Lock</b> (source record changed after generation → blocked), the <b>content lock</b> (edited after approval → blocked), <b>one real send per platform</b>, and <b>per-platform daily caps</b>. A send that ends <b style=\"color:#fbbf24\">uncertain</b> may or may not have landed — it is never auto-retried; resolve it by hand.</p>\r\n\r\n<div class=\"import-actions\">\r\n<button class=\"btn-gold\" onclick=\"loadSocial()\">⟳ Refresh</button>\r\n</div>\r\n\r\n<div class=\"import-status\" id=\"socialStatus\"></div>\r\n</div>\r\n\r\n<h3 style=\"color:#fff;font-size:1rem;font-weight:700;margin:18px 0 10px\">Engine settings</h3>\r\n<div id=\"socialSettings\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading settings…</p>\r\n</div>\r\n\r\n<h3 style=\"color:#fff;font-size:1rem;font-weight:700;margin:22px 0 10px\">Connections</h3>\r\n<p style=\"color:#6a8aaa;font-size:.76rem;margin:0 0 10px\">Non-secret metadata only — platform tokens live in the deployment environment (see <code>.env.example</code>), never in the database.</p>\r\n<div id=\"socialConnections\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading connections…</p>\r\n</div>\r\n\r\n<h3 style=\"color:#fff;font-size:1rem;font-weight:700;margin:22px 0 10px\">Content queue</h3>\r\n<div class=\"import-actions\" style=\"margin-bottom:10px\">\r\n<button class=\"btn-ghost\" onclick=\"socialSetFilter('')\">All</button>\r\n<button class=\"btn-ghost\" onclick=\"socialSetFilter('pending')\">⏳ Pending</button>\r\n<button class=\"btn-ghost\" onclick=\"socialSetFilter('approved')\">✅ Approved</button>\r\n<button class=\"btn-ghost\" onclick=\"socialSetFilter('publishing')\">📤 Publishing</button>\r\n<button class=\"btn-ghost\" onclick=\"socialSetFilter('published')\">📣 Published</button>\r\n<button class=\"btn-ghost\" onclick=\"socialSetFilter('partial')\">🧩 Partial</button>\r\n<button class=\"btn-ghost\" onclick=\"socialSetFilter('rejected')\">🚫 Rejected</button>\r\n</div>\r\n<div id=\"socialQueue\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading queue…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-salary\">\r\n\r\n<div class=\"import-box\">\r\n<p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">\r\nSalary transparency — public page /salary\r\n</p>\r\n\r\n<h3>Salary data review</h3>\r\n<p>Anonymous submissions land here <b>unverified</b>. They still count toward public ranges until reviewed — mark them verified when the numbers look plausible for the role/city, or delete obvious mistakes (e.g. ₹50,000/year or ₹2 crore fresher salaries).</p>\r\n\r\n<div class=\"import-actions\">\r\n<button class=\"btn-gold\" onclick=\"loadSalaryAdmin()\">⟳ Refresh</button>\r\n</div>\r\n\r\n<div class=\"import-status\" id=\"salaryAdminStatus\"></div>\r\n</div>\r\n\r\n<h3 style=\"color:#fff;font-size:1rem;font-weight:700;margin:18px 0 10px\">Aggregated view — role × city</h3>\r\n<p style=\"color:#6a8aaa;font-size:.76rem;margin:0 0 10px\">What the public explorer shows: median, range and data points per role + city.</p>\r\n<div id=\"salaryAggregate\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading aggregate…</p>\r\n</div>\r\n\r\n<h3 style=\"color:#fff;font-size:1rem;font-weight:700;margin:22px 0 10px\">Unverified submissions</h3>\r\n<div id=\"adminSalary\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading submissions…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-walkins\">\r\n\r\n<div class=\"import-box\">\r\n<p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">\r\nWalk-in interview board — public page /walk-in\r\n</p>\r\n\r\n<h3>Add a walk-in drive</h3>\r\n<p>Everything you save here can be published to the public <a href=\"/walk-in\" target=\"_blank\" rel=\"noopener\" style=\"color:#c9973c\">Walk-In board</a> with one click. Required: company, roles, date, venue. Times use 24-hour format (e.g. 09:00, 16:00) — the public page shows them as 12-hour.</p>\r\n\r\n<div class=\"field-grid\" style=\"margin-top:12px\">\r\n<label>Company *<input id=\"wiCompany\" placeholder=\"e.g. L&T Construction\"></label>\r\n<label>Roles *<input id=\"wiRoles\" placeholder=\"Site Engineer, QS\"></label>\r\n<label>Date *<input type=\"date\" id=\"wiDate\"></label>\r\n<label>Start time<input type=\"time\" id=\"wiStart\"></label>\r\n<label>End time<input type=\"time\" id=\"wiEnd\"></label>\r\n<label>Venue *<input id=\"wiVenue\" placeholder=\"Full venue address\"></label>\r\n<label>City<input id=\"wiCity\" placeholder=\"Bengaluru\"></label>\r\n<label>State<input id=\"wiState\" placeholder=\"Karnataka\"></label>\r\n<label>Experience<input id=\"wiExp\" placeholder=\"e.g. 2-8 years\"></label>\r\n<label>Qualification<input id=\"wiQual\" placeholder=\"BE/BTech/Diploma Civil\"></label>\r\n<label>Salary offered<input id=\"wiSalary\" placeholder=\"optional\"></label>\r\n<label>Expires on<input type=\"date\" id=\"wiExpires\"></label>\r\n<label class=\"wide\">Documents to bring<input id=\"wiDocs\" placeholder=\"Resume, marksheets, photos, experience letters\"></label>\r\n<label>Contact<input id=\"wiContact\" placeholder=\"phone or email\"></label>\r\n<label>Source URL<input type=\"url\" id=\"wiSource\" placeholder=\"https://...\"></label>\r\n</div>\r\n\r\n<div class=\"import-actions\">\r\n<button class=\"btn-gold\" onclick=\"createWalkin()\">+ Add Walk-In</button>\r\n<button class=\"btn-ghost\" onclick=\"clearWalkinForm()\">Clear form</button>\r\n<button class=\"btn-ghost\" onclick=\"loadWalkinAdmin()\">⟳ Refresh</button>\r\n</div>\r\n\r\n<div class=\"import-status\" id=\"walkinAdminStatus\"></div>\r\n</div>\r\n\r\n<h3 style=\"color:#fff;font-size:1rem;font-weight:700;margin:18px 0 10px\">All walk-ins</h3>\r\n<p style=\"color:#6a8aaa;font-size:.76rem;margin:0 0 10px\"><span style=\"color:#6ee7b7\">■</span> Published (live on the public board) &nbsp;·&nbsp; <span style=\"color:#fbbf24\">■</span> Pending (not yet visible)</p>\r\n<div id=\"adminWalkins\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading walk-ins…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-subscribers\">\r\n\r\n<div class=\"metrics\" style=\"margin-bottom:16px\">\r\n  <div class=\"metric\"><span>WhatsApp subscribers</span><b id=\"waSubCount\">…</b></div>\r\n  <div class=\"metric\"><span>Active</span><b id=\"waSubActive\">…</b></div>\r\n  <div class=\"metric\"><span>Cities covered</span><b id=\"waSubCities\">…</b></div>\r\n  <div class=\"metric\"><span>Hindi-language</span><b id=\"waSubHindi\">…</b></div>\r\n</div>\r\n\r\n<div class=\"import-actions\" style=\"margin-bottom:14px\">\r\n<button class=\"btn-gold\" onclick=\"copyWaNumbers()\">📋 Copy All Numbers</button>\r\n<button class=\"btn-gold\" onclick=\"exportWaCSV()\">⬇ Export CSV</button>\r\n<button class=\"btn-ghost\" onclick=\"loadWaSubs()\">⟳ Refresh</button>\r\n</div>\r\n\r\n<div class=\"discovery-grid\" style=\"margin-bottom:14px;grid-template-columns:1fr 1fr 1fr\">\r\n<label>Filter by city\r\n  <select id=\"waFilterCity\" onchange=\"renderWaSubs()\"><option value=\"\">All cities</option></select>\r\n</label>\r\n<label>Filter by role\r\n  <select id=\"waFilterRole\" onchange=\"renderWaSubs()\"><option value=\"\">All roles</option></select>\r\n</label>\r\n<label>Filter by sector\r\n  <select id=\"waFilterSector\" onchange=\"renderWaSubs()\"><option value=\"\">All sectors</option><option>Government</option><option>Private</option><option>PSU</option><option>MNC</option></select>\r\n</label>\r\n</div>\r\n\r\n<p style=\"color:#6a8aaa;font-size:.76rem;margin:0 0 10px\">Phone numbers are personal data — use the export only for sending CivilCareer alerts, never share or sell the list.</p>\r\n\r\n<div id=\"adminWaSubs\" style=\"overflow-x:auto\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading subscribers…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-reviews\">\r\n\r\n<div class=\"import-actions\" style=\"margin-bottom:14px\">\r\n<button class=\"btn-ghost\" onclick=\"loadCompanyReviews()\">⟳ Refresh reviews</button>\r\n</div>\r\n\r\n<p style=\"color:#6a8aaa;font-size:.76rem;margin:0 0 10px\">Reviews land here unapproved. Approve only after a sanity read — ratings for a company appear publicly once at least one review is approved. Reject removes the review permanently.</p>\r\n\r\n<div id=\"adminCompanyReviews\" style=\"overflow-x:auto\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading reviews…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-blog\">\r\n\r\n<div class=\"import-box\">\r\n<p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">\r\nBlog — public page /blog\r\n</p>\r\n\r\n<h3>Blog posts</h3>\r\n<p>Articles appear on the public <a href=\"/blog\" target=\"_blank\" rel=\"noopener\" style=\"color:#c9973c\">Blog page</a> only when published. Content supports plain text with **bold** and ### headings, separated by blank lines.</p>\r\n\r\n<div class=\"import-actions\">\r\n<button class=\"btn-gold\" onclick=\"loadBlogAdmin()\">⟳ Refresh</button>\r\n<button class=\"btn-ghost\" onclick=\"blogEditor()\">+ New post</button>\r\n</div>\r\n\r\n<div class=\"import-status\" id=\"blogAdminStatus\"></div>\r\n</div>\r\n\r\n<div class=\"import-box\" id=\"blogEditor\" style=\"display:none;margin-top:14px\">\r\n<h3 id=\"blogEditorTitle\">New post</h3>\r\n<label>Title *<input id=\"blogTitle\" placeholder=\"e.g. How to crack SSC JE in first attempt\"></label>\r\n<label>Slug<span>Leave blank to auto-generate from the title</span><input id=\"blogSlug\" placeholder=\"ssc-je-first-attempt\"></label>\r\n<div class=\"field-grid\">\r\n<label>Category<select id=\"blogCategory\"><option>Career</option><option>Exams</option><option>Interviews</option><option>Salary</option><option>Technology</option><option>News</option></select></label>\r\n<label>Author<input id=\"blogAuthor\" placeholder=\"CivilCareer Team\"></label>\r\n<label>Tags (comma separated)<input id=\"blogTags\" placeholder=\"ssc je, government, preparation\"></label>\r\n</div>\r\n<label>Excerpt<span>Shown on cards and in search results</span><textarea id=\"blogExcerpt\" rows=\"2\"></textarea></label>\r\n<label>Content<textarea id=\"blogContent\" rows=\"12\" placeholder=\"Write the article here. Blank line = new paragraph. **bold** and ### heading work.\"></textarea></label>\r\n<div class=\"import-actions\">\r\n<button class=\"btn-gold\" onclick=\"saveBlogPost(true)\">Publish</button>\r\n<button class=\"btn-ghost\" onclick=\"saveBlogPost(false)\">Save draft</button>\r\n<button class=\"btn-ghost\" onclick=\"hideBlogEditor()\">Cancel</button>\r\n</div>\r\n<div class=\"import-status\" id=\"blogEditorStatus\"></div>\r\n</div>\r\n\r\n<div id=\"adminBlog\" style=\"overflow-x:auto\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading posts…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-interview\">\r\n\r\n<div class=\"import-box\">\r\n<p style=\"color:#c9973c;font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;margin-bottom:6px\">\r\nInterview Q&A — public page /interview\r\n</p>\r\n\r\n<h3>Community question approvals</h3>\r\n<p>Visitor-submitted interview questions land here <b>unapproved</b>. Approve after a sanity read — they appear on the public <a href=\"/interview\" target=\"_blank\" rel=\"noopener\" style=\"color:#c9973c\">Interview Questions page</a>. Reject removes the question permanently.</p>\r\n\r\n<div class=\"import-actions\">\r\n<button class=\"btn-gold\" onclick=\"loadInterviewAdmin()\">⟳ Refresh</button>\r\n</div>\r\n\r\n<div class=\"import-status\" id=\"interviewAdminStatus\"></div>\r\n</div>\r\n\r\n<div id=\"adminInterview\" style=\"overflow-x:auto\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading submissions…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-materials\">\r\n\r\n<div class=\"admin-actions\">\r\n<button class=\"btn-gold\" onclick=\"materialEditor()\">+ Add material</button>\r\n</div>\r\n\r\n<div id=\"adminMaterials\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading materials…</p>\r\n</div>\r\n\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-submissions\">\r\n<div id=\"adminSubmissions\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading submissions…</p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-reports\">\r\n<div id=\"adminReports\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading reports…</p>\r\n</div>\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-contact\">\r\n<div id=\"adminContact\">\r\n<p style=\"color:#6a8aaa;font-size:.85rem\">Loading messages…</p>\r\n</div>\r\n</div>\r\n\r\n<!-- ⚡ REVIEW JOBS PANEL -->\r\n<div class=\"panel\" id=\"panel-review-jobs\">\r\n<style>\r\n.rj-scraper-bar{display:flex;gap:8px;flex-wrap:wrap;padding:12px 16px;background:#071828;border:1px solid rgba(201,151,60,.2);border-radius:10px;margin-bottom:14px;align-items:center}\r\n.rj-scraper-bar span{font-size:.78rem;color:#6a8aaa;flex:1}\r\n.rj-tabs{display:flex;gap:4px;margin-bottom:14px;background:#071828;padding:4px;border-radius:10px;border:1px solid rgba(255,255,255,.06)}\r\n.rj-tabs button{padding:7px 14px;border-radius:7px;border:none;background:transparent;color:#6a8aaa;font-size:.8rem;font-weight:700;cursor:pointer;font-family:inherit;transition:all .15s}\r\n.rj-tabs button.active{background:#c9973c;color:#0b1f3a}\r\n.rj-tabs button:hover:not(.active){color:#fff;background:rgba(255,255,255,.06)}\r\n.rj-bulk-bar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px 14px;background:#071828;border:1px solid rgba(255,255,255,.08);border-radius:10px;margin-bottom:10px}\r\n.rj-bulk-bar label{font-size:.8rem;color:#94a3b8;display:flex;align-items:center;gap:6px;cursor:pointer}\r\n.rj-count{font-size:.78rem;color:#6a8aaa}\r\n.btn-pub-bulk{background:rgba(5,150,105,.15);color:#6ee7b7;border:1px solid rgba(5,150,105,.35);border-radius:7px;padding:6px 14px;font-size:.78rem;font-weight:700;cursor:pointer}\r\n.btn-pub-bulk:hover{background:rgba(5,150,105,.3)}\r\n.btn-rej-bulk{background:rgba(220,38,38,.1);color:#fca5a5;border:1px solid rgba(220,38,38,.25);border-radius:7px;padding:6px 14px;font-size:.78rem;font-weight:700;cursor:pointer}\r\n.btn-del-bulk{background:rgba(100,50,50,.2);color:#fca5a5;border:1px solid rgba(220,38,38,.2);border-radius:7px;padding:6px 14px;font-size:.78rem;font-weight:700;cursor:pointer}\r\n.rj-search{width:100%;padding:9px 14px;border-radius:8px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.05);color:#fff;font-size:.85rem;font-family:inherit;outline:none;margin-bottom:12px;box-sizing:border-box}\r\n.rj-search:focus{border-color:#c9973c}\r\n.rj-item{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:12px 16px;margin-bottom:8px;display:flex;gap:12px;align-items:flex-start}\r\n.rj-item input[type=checkbox]{margin-top:3px;flex-shrink:0;width:16px;height:16px;cursor:pointer;accent-color:#c9973c}\r\n.rj-item-body{flex:1;min-width:0}\r\n.rj-item-body h4{font-size:.9rem;font-weight:700;color:#fff;margin:0 0 3px;line-height:1.35}\r\n.rj-item-body p{font-size:.75rem;color:#6a8aaa;margin:0 0 6px}\r\n.rj-item-actions{display:flex;gap:6px;flex-wrap:wrap}\r\n.rj-tg-badge{font-size:.65rem;padding:2px 7px;border-radius:999px;background:rgba(16,185,129,.12);color:#6ee7b7;border:1px solid rgba(16,185,129,.2);font-weight:600;margin-left:6px}\r\n.rj-tg-no{background:rgba(100,100,100,.1);color:#4a6a8a;border-color:rgba(255,255,255,.08)}\r\n.rj-pager{display:flex;gap:8px;align-items:center;margin-top:12px;flex-wrap:wrap}\r\n</style>\r\n\r\n<div class=\"rj-scraper-bar\">\r\n  <span>Scrape 9 portals for civil engineering jobs → saved as pending review</span>\r\n  <button class=\"btn-gold\" onclick=\"rjRunScraper()\" id=\"rjScraperBtn\">🔍 Run Scraper Now</button>\r\n  <button class=\"btn-ghost\" onclick=\"rjLoadTab(rjActiveTab)\">⟳ Refresh</button>\r\n</div>\r\n\r\n<div class=\"rj-tabs\">\r\n  <button class=\"active\" data-rjtab=\"review\" onclick=\"rjLoadTab('review')\">📋 Pending Review <span id=\"rjReviewCount\"></span></button>\r\n  <button data-rjtab=\"published\" onclick=\"rjLoadTab('published')\">✅ Published <span id=\"rjPubCount\"></span></button>\r\n  <button data-rjtab=\"deleted\" onclick=\"rjLoadTab('deleted')\">🗑️ Deleted <span id=\"rjDelCount\"></span></button>\r\n</div>\r\n\r\n<input class=\"rj-search\" id=\"rjSearch\" placeholder=\"Search by job title…\" oninput=\"rjFilterList()\">\r\n\r\n<div class=\"rj-bulk-bar\">\r\n  <label><input type=\"checkbox\" id=\"rjSelAll\" onchange=\"rjToggleAll(this.checked)\"> Select all</label>\r\n  <span class=\"rj-count\" id=\"rjSelCount\">0 selected</span>\r\n  <button class=\"btn-pub-bulk\" onclick=\"rjBulk('publish')\">✅ Publish</button>\r\n  <button class=\"btn-rej-bulk\" onclick=\"rjBulk('reject')\">✕ Reject</button>\r\n  <button class=\"btn-del-bulk\" onclick=\"rjBulk('delete')\">🗑 Delete</button>\r\n  <button class=\"btn-ghost\" onclick=\"rjBulk('restore')\" style=\"font-size:.75rem\">↩ Restore</button>\r\n</div>\r\n\r\n<div id=\"rjList\"><p style=\"color:#6a8aaa;font-size:.85rem;padding:1rem 0\">Click a tab above to load jobs.</p></div>\r\n<div class=\"rj-pager\" id=\"rjPager\"></div>\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-govt\">\r\n<style>\r\n.govt-tabs{display:flex;gap:4px;flex-wrap:wrap;margin-bottom:14px;background:#071828;padding:4px;border-radius:10px;border:1px solid rgba(255,255,255,.06)}\r\n.govt-tabs button{padding:7px 12px;border-radius:7px;border:none;background:transparent;color:#6a8aaa;font-size:.78rem;font-weight:700;cursor:pointer;font-family:inherit;transition:all .15s}\r\n.govt-tabs button.active{background:#c9973c;color:#0b1f3a}\r\n.govt-tabs button:hover:not(.active){color:#fff;background:rgba(255,255,255,.06)}\r\n.govt-tabs .govt-count{opacity:.75;font-weight:600}\r\n.govt-list{display:flex;flex-direction:column;gap:8px}\r\n.govt-item{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:12px 16px}\r\n.govt-item h4{font-size:.9rem;font-weight:700;color:#fff;margin:0 0 4px;line-height:1.35;display:flex;gap:8px;align-items:center;flex-wrap:wrap}\r\n.govt-item p{font-size:.75rem;color:#6a8aaa;margin:0 0 8px}\r\n.govt-item .govt-actions{display:flex;gap:6px;flex-wrap:wrap;align-items:center}\r\n.govt-badge{font-size:.65rem;padding:2px 8px;border-radius:999px;font-weight:700;border:1px solid rgba(255,255,255,.12);color:#8ea8c4;background:rgba(255,255,255,.05)}\r\n.govt-badge.kind-new{background:rgba(16,185,129,.12);color:#6ee7b7;border-color:rgba(16,185,129,.25)}\r\n.govt-badge.kind-updated,.govt-badge.kind-closing_date_changed{background:rgba(245,158,11,.12);color:#fcd34d;border-color:rgba(245,158,11,.25)}\r\n.govt-badge.kind-result,.govt-badge.kind-admit_card{background:rgba(59,130,246,.15);color:#93c5fd;border-color:rgba(59,130,246,.3)}\r\n.govt-badge.st-official{background:rgba(5,150,105,.15);color:#6ee7b7;border-color:rgba(5,150,105,.35)}\r\n.govt-badge.st-unverified{background:rgba(220,38,38,.1);color:#fca5a5;border-color:rgba(220,38,38,.25)}\r\n.govt-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}\r\n.govt-toolbar input[type=search]{flex:1;min-width:220px;padding:9px 14px;border-radius:8px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.05);color:#fff;font-size:.85rem;font-family:inherit;outline:none;box-sizing:border-box}\r\n.govt-toolbar input[type=search]:focus{border-color:#c9973c}\r\n.govt-sub{display:none}\r\n.govt-sub.active{display:block}\r\n.govt-empty{color:#6a8aaa;font-size:.85rem;padding:1rem 0}\r\n/* The six aggregator feeds all publish the same handful of columns — Organization,\r\n   Post, Qualification, Advt no, Last date — so a queued lead is shown as those same\r\n   columns instead of a sentence: the reviewer can hold a row up against the feed it\r\n   actually came from. */\r\n.govt-feed-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:6px 16px;margin:0 0 8px}\r\n.govt-feed-grid .rm-label{color:#4a6a8a;font-size:.62rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;display:block;margin-bottom:1px}\r\n.govt-feed-grid .rm-value{color:#cbd5e1;font-size:.78rem;line-height:1.5;word-break:break-word}\r\n.govt-notice-paste{display:flex;gap:6px;align-items:center;flex-wrap:wrap;flex:1 1 340px}\r\n.govt-notice-paste input{flex:1 1 240px;min-width:180px;background:#0b1f38;border:1px solid rgba(255,255,255,.16);border-radius:8px;color:#e6eefb;font-size:.75rem;padding:7px 10px}\r\n.govt-notice-missing{font-size:.72rem;color:#fca5a5}\r\n.govt-detail{background:#0a1c35;border:1px solid rgba(255,255,255,.1);border-radius:10px;padding:14px 16px;margin-top:10px}\r\n.govt-detail dl{display:grid;grid-template-columns:170px 1fr;gap:4px 12px;font-size:.8rem;margin:0}\r\n.govt-detail dt{color:#8ea8c4;font-weight:600}\r\n.govt-detail dd{margin:0;color:#dbe7f5;word-break:break-word}\r\n.govt-prov{margin-top:10px;font-size:.72rem;color:#8ea8c4}\r\n.govt-prov li{margin-bottom:2px}\r\n</style>\r\n\r\n<div class=\"govt-toolbar\">\r\n  <input type=\"search\" id=\"govtSearch\" placeholder=\"Search inbox, drafts and published…\" oninput=\"govtFilter()\">\r\n  <button class=\"btn-gold\" onclick=\"govtRefreshAll()\" id=\"govtRefreshBtn\">⟳ Refresh</button>\r\n  <button class=\"btn-ghost\" onclick=\"govtShowCreate()\">+ New Draft</button>\r\n</div>\r\n\r\n<div class=\"govt-tabs\" id=\"govtTabs\">\r\n  <button class=\"active\" data-gtab=\"inbox\" onclick=\"govtLoad('inbox')\">🤖 AI Inbox <span class=\"govt-count\" id=\"govtCountInbox\"></span></button>\r\n  <button data-gtab=\"drafts\" onclick=\"govtLoad('drafts')\">📝 Drafts <span class=\"govt-count\" id=\"govtCountDrafts\"></span></button>\r\n  <button data-gtab=\"published\" onclick=\"govtLoad('published')\">✅ Published <span class=\"govt-count\" id=\"govtCountPublished\"></span></button>\r\n  <button data-gtab=\"archived\" onclick=\"govtLoad('archived')\">🗄 Archived <span class=\"govt-count\" id=\"govtCountArchived\"></span></button>\r\n  <button data-gtab=\"organizations\" onclick=\"govtLoad('organizations')\">🏢 Organizations</button>\r\n  <button data-gtab=\"categories\" onclick=\"govtLoad('categories')\">🏷 Categories</button>\r\n  <button data-gtab=\"sources\" onclick=\"govtLoad('sources')\">📡 Sources</button>\r\n  <button data-gtab=\"review\" onclick=\"govtLoad('review')\">🔍 Review Queue <span class=\"govt-count\" id=\"govtCountReview\"></span></button>\r\n  <button data-gtab=\"conflicts\" onclick=\"govtLoad('conflicts')\">⚔ Conflicts <span class=\"govt-count\" id=\"govtCountConflicts\"></span></button>\r\n  <button data-gtab=\"providers\" onclick=\"govtLoad('providers')\">🧠 AI Providers</button>\r\n</div>\r\n\r\n<div class=\"govt-sub active\" data-gsub=\"inbox\">\r\n  <div class=\"govt-toolbar\">\r\n    <select id=\"govtInboxKind\" onchange=\"govtLoad('inbox')\" style=\"padding:8px 10px;border-radius:8px;border:1px solid rgba(255,255,255,.1);background:#0f2847;color:#fff;font-family:inherit\">\r\n      <option value=\"\">All updates</option>\r\n      <option value=\"new\">New Jobs</option>\r\n      <option value=\"updated\">Updated Jobs</option>\r\n      <option value=\"closing_date_changed\">Closing-Date Changes</option>\r\n      <option value=\"result\">Results</option>\r\n      <option value=\"admit_card\">Admit Cards</option>\r\n      <option value=\"other_update\">Other Updates</option>\r\n    </select>\r\n    <span style=\"font-size:.72rem;color:#6a8aaa\">AI-found updates. Nothing publishes without your approval.</span>\r\n  </div>\r\n  <div class=\"govt-list\" id=\"govtListInbox\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n\r\n<div class=\"govt-sub\" data-gsub=\"drafts\">\r\n  <div class=\"govt-list\" id=\"govtListDrafts\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n\r\n<div class=\"govt-sub\" data-gsub=\"published\">\r\n  <div class=\"govt-list\" id=\"govtListPublished\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n\r\n<div class=\"govt-sub\" data-gsub=\"archived\">\r\n  <div class=\"govt-list\" id=\"govtListArchived\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n\r\n<div class=\"govt-sub\" data-gsub=\"organizations\">\r\n  <div class=\"govt-toolbar\">\r\n    <input type=\"search\" id=\"govtOrgSearch\" placeholder=\"Filter organizations…\" oninput=\"govtRenderOrgs(govtCacheOrgs)\" style=\"max-width:280px\">\r\n    <button class=\"btn-ghost\" onclick=\"govtShowOrgForm()\">+ Add Organization</button>\r\n  </div>\r\n  <div class=\"govt-list\" id=\"govtListOrgs\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n\r\n<div class=\"govt-sub\" data-gsub=\"categories\">\r\n  <div class=\"govt-list\" id=\"govtListCats\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n\r\n<div class=\"govt-sub\" data-gsub=\"sources\">\r\n  <div class=\"govt-list\" id=\"govtListSources\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n\r\n<div class=\"govt-sub\" data-gsub=\"review\">\r\n  <div class=\"govt-toolbar\">\r\n    <select id=\"govtReviewStatus\" onchange=\"govtLoad('review')\" style=\"padding:8px 10px;border-radius:8px;border:1px solid rgba(255,255,255,.1);background:#0f2847;color:#fff;font-family:inherit\">\r\n      <option value=\"pending\">Pending</option>\r\n      <option value=\"needs_info\">Needs Info</option>\r\n      <option value=\"duplicate\">Duplicates</option>\r\n      <option value=\"rejected\">Rejected</option>\r\n      <option value=\"approved\">Approved</option>\r\n    </select>\r\n    <span style=\"font-size:.72rem;color:#6a8aaa\">Discovery items awaiting classification review.</span>\r\n  </div>\r\n  <div class=\"govt-list\" id=\"govtListReview\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n\r\n<div class=\"govt-sub\" data-gsub=\"conflicts\">\r\n  <div class=\"govt-list\" id=\"govtListConflicts\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n\r\n<div class=\"govt-sub\" data-gsub=\"providers\">\r\n  <div class=\"govt-list\" id=\"govtListProviders\"><p class=\"govt-empty\">Loading…</p></div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-collector\">\r\n<style>\r\n.jc-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;align-items:start}\r\n@media(max-width:960px){.jc-grid{grid-template-columns:1fr}}\r\n.jc-card{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:14px 16px;margin-bottom:14px}\r\n.jc-card h3{font-size:.95rem;color:#fff;margin:0 0 8px;font-weight:800}\r\n.jc-card label{display:block;font-size:.72rem;font-weight:700;color:#8ea8c4;text-transform:uppercase;letter-spacing:.06em;margin:10px 0 4px}\r\n.jc-card input[type=text],.jc-card input[type=url],.jc-card textarea{width:100%;padding:9px 12px;border-radius:8px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.05);color:#fff;font-size:.82rem;font-family:inherit;outline:none;box-sizing:border-box}\r\n.jc-card textarea{min-height:104px;resize:vertical}\r\n.jc-card input:focus,.jc-card textarea:focus{border-color:#c9973c}\r\n.jc-help{margin:0;padding-left:18px;font-size:.78rem;color:#94a3b8;line-height:1.6}\r\n.jc-help li{margin-bottom:7px}\r\n.jc-note{margin-top:10px;padding:10px 12px;border-radius:9px;background:rgba(201,151,60,.08);border:1px solid rgba(201,151,60,.25);font-size:.72rem;color:#e2c07a;line-height:1.55}\r\n.jc-status{font-size:.78rem;color:#8ea8c4;margin-top:8px;min-height:18px}\r\n.jc-batch{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:10px 14px;margin-bottom:8px}\r\n.jc-batch h4{font-size:.85rem;color:#fff;margin:0 0 3px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}\r\n.jc-batch p{font-size:.72rem;color:#6a8aaa;margin:0 0 7px}\r\n.jc-badge{font-size:.63rem;padding:2px 8px;border-radius:999px;font-weight:700;border:1px solid rgba(255,255,255,.14);color:#8ea8c4;background:rgba(255,255,255,.05);text-transform:uppercase;letter-spacing:.04em}\r\n.jc-badge.jc-st-done{background:rgba(16,185,129,.12);color:#6ee7b7;border-color:rgba(16,185,129,.3)}\r\n.jc-badge.jc-st-processing{background:rgba(59,130,246,.15);color:#93c5fd;border-color:rgba(59,130,246,.3)}\r\n.jc-badge.jc-st-partial{background:rgba(245,158,11,.12);color:#fcd34d;border-color:rgba(245,158,11,.3)}\r\n.jc-badge.jc-st-open{background:rgba(148,163,184,.12);color:#cbd5e1}\r\n.jc-itemline{font-size:.74rem;color:#a9bdd4;margin:3px 0;line-height:1.6}\r\n.jc-itemline .st{color:#6a8aaa}\r\n</style>\r\n<div class=\"jc-grid\">\r\n  <div class=\"jc-card\">\r\n    <h3>📥 How to collect jobs</h3>\r\n    <ol class=\"jc-help\">\r\n      <li><b>Paste the ad text</b> you already have — a WhatsApp message, an email forward, a printed notice.</li>\r\n      <li><b>Upload a screenshot or PDF</b> (job posters, recruitment notices). OCR reads it when a vision key is configured; otherwise the item waits for you to paste its text.</li>\r\n      <li><b>Add the link</b> of a public job page you want to keep. The server fetches the public page once, reads it, and stores nothing behind a login.</li>\r\n      <li>One batch can contain many posters — each role is split into its own job card automatically.</li>\r\n      <li>Every card is scored for <b>civil relevance</b> and <b>confidence</b>, checked against jobs already on the site, then parked in the <b>Job Inbox</b>.</li>\r\n      <li>You edit anything the machine got wrong and press <b>Approve &amp; publish</b>. Only that button writes to the live jobs list.</li>\r\n    </ol>\r\n    <div class=\"jc-note\"><b>Compliance:</b> submit only material you received or own — posters and forwards you were given, public pages, your own scans. This tool does not log into WhatsApp, LinkedIn or any portal, and does not scrape other people's accounts or private groups. AI output is a draft; you verify every field before publishing.</div>\r\n  </div>\r\n  <div class=\"jc-card\">\r\n    <h3>➕ Submit job material</h3>\r\n    <label for=\"jcLabel\">Batch label (optional)</label>\r\n    <input type=\"text\" id=\"jcLabel\" placeholder=\"e.g. WhatsApp posters — 4 Oct\">\r\n    <label for=\"jcText\">Paste text (one or many jobs)</label>\r\n    <textarea id=\"jcText\" placeholder=\"Site Engineer - 4-6 LPA&#10;Experience: 3-5 years&#10;Location: Pune&#10;Contact: hr@example.com\"></textarea>\r\n    <label for=\"jcUrls\">Job links (one per line)</label>\r\n    <textarea id=\"jcUrls\" style=\"min-height:64px\" placeholder=\"https://example.com/careers/site-engineer\"></textarea>\r\n    <label for=\"jcFiles\">Screenshots / posters / PDFs</label>\r\n    <input type=\"file\" id=\"jcFiles\" multiple accept=\"image/*,application/pdf\" style=\"font-size:.78rem;color:#94a3b8\">\r\n    <div style=\"margin-top:12px;display:flex;gap:8px;align-items:center;flex-wrap:wrap\">\r\n      <button class=\"btn-gold\" id=\"jcSubmitBtn\" onclick=\"jcSubmit()\">🚀 Add to batch &amp; extract</button>\r\n      <button class=\"btn-ghost\" onclick=\"jcLoadBatches()\">⟳ Refresh batches</button>\r\n      <button class=\"btn-ghost\" onclick=\"jcCheckSetup()\">🔎 Check setup</button>\r\n    </div>\r\n    <div class=\"jc-status\" id=\"jcStatus\"></div>\r\n    <div id=\"jcSetup\" style=\"margin-top:6px\"></div>\r\n    <div class=\"metrics\" id=\"jcMetrics\" style=\"margin-top:12px\"></div>\r\n  </div>\r\n</div>\r\n<div class=\"jc-card\">\r\n  <h3>🗂 Recent batches</h3>\r\n  <div id=\"jcBatches\"><p style=\"color:#6a8aaa;font-size:.8rem\">No batches yet — submit your first text, screenshot, PDF or link above.</p></div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"panel\" id=\"panel-inbox\">\r\n<style>\r\n.ji-item{background:#0f2847;border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:12px 16px;margin-bottom:8px}\r\n.ji-item-body h4{font-size:.9rem;font-weight:700;color:#fff;margin:0 0 4px;line-height:1.35;display:flex;gap:8px;align-items:center;flex-wrap:wrap}\r\n.ji-item-body p{font-size:.75rem;color:#6a8aaa;margin:0 0 7px;line-height:1.5}\r\n.ji-actions{display:flex;gap:6px;flex-wrap:wrap;align-items:center}\r\n.ji-badge{font-size:.65rem;padding:2px 8px;border-radius:999px;font-weight:700;border:1px solid rgba(255,255,255,.12);color:#8ea8c4;background:rgba(255,255,255,.05)}\r\n.ji-badge.ji-dup{background:rgba(245,158,11,.12);color:#fcd34d;border-color:rgba(245,158,11,.3)}\r\n.ji-badge.ji-st-pending{background:rgba(59,130,246,.15);color:#93c5fd;border-color:rgba(59,130,246,.3)}\r\n.ji-badge.ji-st-needs_attention{background:rgba(245,158,11,.12);color:#fcd34d;border-color:rgba(245,158,11,.3)}\r\n.ji-badge.ji-st-approved{background:rgba(16,185,129,.12);color:#6ee7b7;border-color:rgba(16,185,129,.25)}\r\n.ji-badge.ji-st-rejected{background:rgba(220,38,38,.1);color:#fca5a5;border-color:rgba(220,38,38,.25)}\r\n.ji-badge.ji-rel-non_relevant{background:rgba(220,38,38,.1);color:#fca5a5;border-color:rgba(220,38,38,.25)}\r\n.ji-badge.ji-rel-uncertain{background:rgba(245,158,11,.12);color:#fcd34d;border-color:rgba(245,158,11,.3)}\r\n.ji-detail{background:#0a1c35;border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:14px 16px;margin-bottom:14px}\r\n.ji-detail h3{font-size:1rem;color:#fff;margin:0;display:flex;gap:8px;align-items:center;flex-wrap:wrap}\r\n.ji-form{display:grid;grid-template-columns:repeat(3,1fr);gap:8px 12px;margin-top:12px}\r\n@media(max-width:900px){.ji-form{grid-template-columns:1fr 1fr}}\r\n@media(max-width:620px){.ji-form{grid-template-columns:1fr}}\r\n.ji-field{display:flex;flex-direction:column;gap:3px}\r\n.ji-field.wide{grid-column:span 2}\r\n.ji-field label{font-size:.68rem;font-weight:700;color:#8ea8c4;text-transform:uppercase;letter-spacing:.05em}\r\n.ji-field input,.ji-field select,.ji-field textarea{width:100%;padding:7px 10px;border-radius:7px;border:1px solid rgba(255,255,255,.1);background:rgba(255,255,255,.05);color:#fff;font-size:.8rem;font-family:inherit;outline:none;box-sizing:border-box}\r\n.ji-field input:focus,.ji-field select:focus,.ji-field textarea:focus{border-color:#c9973c}\r\n.ji-source{margin-top:12px;border-top:1px solid rgba(255,255,255,.08);padding-top:10px}\r\n.ji-original{max-width:280px;max-height:220px;border-radius:9px;border:1px solid rgba(255,255,255,.12);margin-top:8px;display:block}\r\n.ji-raw{background:#071828;border:1px solid rgba(255,255,255,.08);border-radius:8px;padding:10px;font-size:.72rem;color:#a9bdd4;max-height:220px;overflow:auto;white-space:pre-wrap}\r\n.ji-events{font-size:.72rem;color:#8ea8c4;margin:8px 0 0;padding-left:18px}\r\n.ji-events li{margin-bottom:3px}\r\n</style>\r\n<div class=\"metrics\" id=\"jiMetrics\"></div>\r\n<div class=\"govt-tabs\" id=\"jiTabs\">\r\n  <button class=\"active\" data-jitab=\"all\" onclick=\"jiLoad('all')\">All</button>\r\n  <button data-jitab=\"pending\" onclick=\"jiLoad('pending')\">⏳ Pending</button>\r\n  <button data-jitab=\"needs_attention\" onclick=\"jiLoad('needs_attention')\">⚠ Needs attention</button>\r\n  <button data-jitab=\"duplicates\" onclick=\"jiLoad('duplicates')\">👥 Possible duplicates</button>\r\n  <button data-jitab=\"approved\" onclick=\"jiLoad('approved')\">✅ Approved</button>\r\n  <button data-jitab=\"rejected\" onclick=\"jiLoad('rejected')\">✕ Rejected</button>\r\n  <button data-jitab=\"processing\" onclick=\"jiLoad('processing')\">⚙ Processing / failed</button>\r\n</div>\r\n<div class=\"govt-toolbar\">\r\n  <input type=\"search\" id=\"jiSearch\" placeholder=\"Filter by title, company, city or contact…\" oninput=\"jiFilter()\">\r\n  <button class=\"btn-gold\" onclick=\"jiLoad(jiActive)\">⟳ Refresh</button>\r\n  <button class=\"btn-ghost\" onclick=\"jiGoCollector()\">📥 Submit more</button>\r\n</div>\r\n<div id=\"jiDetail\" style=\"display:none\"></div>\r\n<div id=\"jiList\"><p style=\"color:#6a8aaa;font-size:.85rem\">Open the Job Inbox tab to load candidates.</p></div>\r\n</div>\r\n\r\n\r\n</div>\r\n</div>\r\n\r\n<div class=\"toast\" id=\"toast\"></div>\r\n\r\n<dialog id=\"editorDialog\">\r\n<div class=\"dialog-head\">\r\n<h2 id=\"editorTitle\">Editor</h2>\r\n<button onclick=\"document.getElementById('editorDialog').close()\">×</button>\r\n</div>\r\n<div class=\"dialog-body\" id=\"editorBody\"></div>\r\n</dialog>\r\n\r\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js\"></script>\r\n\r\n<script>\r\nlet adminKey='',adminRefresh='',jobs=[],exams=[],materials=[],employerProfiles=[],ccJobsPage=1,ccJobsMeta={page:1,total:0,pages:1,has_next:false};\r\n\r\nconst $=id=>document.getElementById(id);\r\n\r\nconst esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({\r\n  '&':'&amp;',\r\n  '<':'&lt;',\r\n  '>':'&gt;',\r\n  '\"':'&quot;',\r\n  \"'\":'&#39;'\r\n}[c]));\r\n\r\nconst val=v=>esc(v||'');\r\n\r\nfunction toast(msg){\r\n  const t=$('toast');\r\n  t.textContent=msg;\r\n  t.classList.add('show');\r\n  clearTimeout(toast._t);\r\n  toast._t=setTimeout(()=>t.classList.remove('show'),2800);\r\n}\r\n\r\nasync function api(url,opt={}){\r\n  const headers={\r\n    'content-type':'application/json',\r\n    ...(adminKey?{Authorization:`Bearer ${adminKey}`}:{}),\r\n    ...(opt.headers||{})\r\n  };\r\n\r\n  const r=await fetch(url,{...opt,headers});\r\n\r\n  const text=await r.text();\r\n\r\n  let data={};\r\n\r\n  try{\r\n    data=text?JSON.parse(text):{};\r\n  }catch{}\r\n\r\n  if(!r.ok){\r\n    const err=Error(\r\n      data.error ||\r\n      data.details ||\r\n      `Request failed (${r.status})`\r\n    );\r\n    err.status=r.status;\r\n    throw err;\r\n  }\r\n\r\n  return data;\r\n}\r\n\r\n/* Session refresh: Supabase access tokens expire after ~1 hour. On a 401 the\r\n   session is rotated once via /api/admin-auth (the server re-checks the owner\r\n   allowlist before returning a token) and the request is retried. */\r\nasync function refreshSession(){\r\n  if(!adminRefresh)return false;\r\n  try{\r\n    const r=await fetch('/api/admin-auth',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({op:'refresh_token',refresh_token:adminRefresh})});\r\n    const x=await r.json().catch(()=>({}));\r\n    if(!r.ok||!x.access_token)return false;\r\n    adminKey=x.access_token;\r\n    adminRefresh=x.refresh_token||adminRefresh;\r\n    sessionStorage.setItem('cc_admin_token',adminKey);\r\n    sessionStorage.setItem('cc_admin_refresh',adminRefresh);\r\n    setAdminSessionCookie(adminKey,x.expires_in||3600);\r\n    return true;\r\n  }catch{return false}\r\n}\r\n\r\nasync function authedApi(url,opt={}){\r\n  try{\r\n    return await api(url,opt);\r\n  }catch(e){\r\n    if(e.status===401&&await refreshSession())return await api(url,opt);\r\n    throw e;\r\n  }\r\n}\r\n\r\nfunction loadFail(id,label){\r\n  const el=$(id);\r\n  if(el)el.innerHTML=`<p style=\"color:#fca5a5;padding:1rem\">${esc(label)} failed to load — <button class=\"btn-ghost\" onclick=\"loadAll()\">Retry</button></p>`;\r\n}\r\n\r\n/* Each source resolves independently so one failed endpoint (rate limit,\r\n   expired session, partial outage) never blanks the whole dashboard. */\r\nasync function settle(step){\r\n  try{ await step(); }catch(e){\r\n    if(e.status===401||e.status===403){toast(e.message||'Administrator session problem — sign in again.');}\r\n    console.warn('admin load:',e.message||e);\r\n  }\r\n}\r\n\r\nfunction formObject(form){\r\n  return Object.fromEntries(\r\n    new FormData(form).entries()\r\n  );\r\n}\r\n\r\n/* A3 gate: /admin is served by /api/admin-page only after the\r\n   caller's session passes the admin allowlist. The cookie carries\r\n   the same short-lived ACCESS token that is already in\r\n   sessionStorage (never the refresh token) so the gate recognises\r\n   this browser on the next /admin visit. */\r\nfunction setAdminSessionCookie(token,maxAge){document.cookie='cc_admin_session='+encodeURIComponent(token)+'; path=/; same-site=lax; max-age='+(parseInt(maxAge,10)||3600);}\r\nfunction clearAdminSessionCookie(){document.cookie='cc_admin_session=; path=/; same-site=lax; max-age=0';}\r\n\r\n/* AUTH — Supabase password login. Server enforces ADMIN_EMAIL / ADMIN_USER_ID. */\r\nasync function getAuthConfig(){\r\n  const r=await fetch('/api/auth-config',{cache:'no-store'});\r\n  const x=await r.json().catch(()=>({}));\r\n  if(!r.ok||!x.url||!x.anonKey)throw Error(x.error||'Authentication is not configured.');\r\n  return x;\r\n}\r\nasync function doLogin(){\r\n  const email=$('adminEmail').value.trim().toLowerCase();\r\n  const password=$('adminPassword').value;\r\n  if(!email||!password)return;\r\n  try{\r\n    const cfg=await getAuthConfig();\r\n    const r=await fetch(`${cfg.url.replace(/\\/$/,'')}/auth/v1/token?grant_type=password`,{method:'POST',headers:{apikey:cfg.anonKey,'Content-Type':'application/json'},body:JSON.stringify({email,password})});\r\n    const x=await r.json().catch(()=>({}));\r\n    if(!r.ok||!x.access_token)throw Object.assign(Error(x.error_description||x.msg||'Administrator sign-in failed.'),{status:r.status});\r\n    adminKey=x.access_token;\r\n    adminRefresh=x.refresh_token||'';\r\n    sessionStorage.setItem('cc_admin_token',adminKey);\r\n    if(adminRefresh)sessionStorage.setItem('cc_admin_refresh',adminRefresh);\r\n    setAdminSessionCookie(adminKey,x.expires_in||3600);\r\n    $('loginError').style.display='none';\r\n    await showDashboard();\r\n  }catch(e){\r\n    $('loginError').style.display='block';\r\n    $('loginError').textContent=e.message||'Administrator sign-in failed.';\r\n  }\r\n}\r\nfunction signOut(){adminKey='';adminRefresh='';sessionStorage.removeItem('cc_admin_token');sessionStorage.removeItem('cc_admin_refresh');clearAdminSessionCookie();$('loginWrap').style.display='flex';$('dashboard').style.display='none';}\r\nasync function showDashboard(){ $('loginWrap').style.display='none'; $('dashboard').style.display='block'; await loadAll(); jcLoadInitial(); }\r\n(function restoreAdminSession(){\r\n  adminKey=sessionStorage.getItem('cc_admin_token')||'';\r\n  adminRefresh=sessionStorage.getItem('cc_admin_refresh')||'';\r\n  if(adminKey)showDashboard().catch(()=>signOut());\r\n})();\r\n\r\n/* LOAD ALL */\r\n\r\nasync function loadAll(page=ccJobsPage){\r\n\r\n  /* Independent settles: a failed endpoint shows its own retry note and the\r\n     rest of the dashboard still loads. FIX 30 Sep: one failed call used to\r\n     leave every tab stuck on \"Loading\" (single Promise.all + throw). */\r\n\r\n  await Promise.allSettled([\r\n\r\n    /* auth=1 → the dispatcher stamps owner context, so jobs (incl. drafts,\r\n       Pending Review and agent-reach items) are visible to the allowlisted\r\n       admin. Server-side enforced; the browser never holds any secret. */\r\n    settle(async()=>{\r\n      try {\r\n        const lifecycle=encodeURIComponent($('adminJobStatusFilter')?.value || 'all');\r\n        const j=await authedApi(`/api/jobs?page=${page}&limit=50&auth=1&lifecycle=${lifecycle}`,{});\r\n        if (!Array.isArray(j.jobs)) throw new Error(j.error || 'Jobs API returned no job list.');\r\n        jobs=j.jobs;\r\n        ccJobsMeta=j.meta||{page,total:jobs.length,pages:1,has_next:false};\r\n        ccJobsPage=ccJobsMeta.page||page;\r\n        loadAdminJobs();\r\n      } catch (e) {\r\n        jobs=[];\r\n        const root=$('adminJobs');\r\n        if(root) root.innerHTML=`<p style=\"color:#f3a6a6;padding:1rem\">Unable to load jobs: ${esc(e.message||'Unknown error')}. <button class=\"btn-ghost\" onclick=\"loadAll(${page})\">Retry</button></p>`;\r\n        throw e;\r\n      }\r\n    }),\r\n\r\n    settle(async()=>{\r\n      const a=await authedApi('/api/analytics',{});\r\n      const an=a.analytics||{};\r\n      renderMetrics(an,[]);\r\n      const k=a.kpi||{};\r\n      const kpiEl=document.getElementById('kpiReport');\r\n      if(kpiEl){\r\n        kpiEl.innerHTML=(k.error?`<p class=\"kpi-error\">KPI error: ${k.error}</p>`:`\r\n          <div class=\"metric\"><span>Weekly active users</span><b>${(k.weekly_active_users||0).toLocaleString('en-IN')}</b></div>\r\n          <div class=\"metric\"><span>Alert subscribers (new, 7d)</span><b>${(k.alert_subscribers_new||0).toLocaleString('en-IN')}</b></div>\r\n          <div class=\"metric\"><span>Applications tracked (7d)</span><b>${(k.applications_tracked_this_week||0).toLocaleString('en-IN')}</b></div>\r\n          <div class=\"metric\"><span>Apply rate / 1k views</span><b>${k.apply_rate_per_1k_views==null?'—':k.apply_rate_per_1k_views}</b></div>\r\n          <div class=\"metric\"><span>Listings verified last 7d</span><b>${(k.listings_verified_last_7d||0).toLocaleString('en-IN')}</b></div>\r\n          <div class=\"metric\"><span>Scam reports / 1k views</span><b>${k.scam_reports_per_1k_views==null?'—':k.scam_reports_per_1k_views}</b></div>`)+\r\n          `<p class=\"kpi-generated\">Generated ${new Date(k.generated_at||Date.now()).toLocaleString('en-IN')}</p>`;\r\n      }\r\n      renderAnalytics(an);\r\n    }),\r\n\r\n    settle(async()=>{\r\n      const es=await authedApi('/api/employer-submissions',{});\r\n      const rs=await authedApi('/api/resource-submissions',{});\r\n      renderSubmissions(es.submissions||[],rs.submissions||[]);\r\n    }),\r\n\r\n    settle(async()=>{\r\n      const re=await authedApi('/api/reports',{});\r\n      renderReports(re.reports||[]);\r\n      const el=$('metrics');\r\n      /* Metric cards re-render with the real open-report count once known. */\r\n    }),\r\n\r\n    settle(async()=>{\r\n      const cm=await authedApi('/api/contact',{});\r\n      renderContactMessages(cm.messages||[]);\r\n    }),\r\n\r\n    settle(async()=>{\r\n      const x=await authedApi('/api/exams?auth=1',{});\r\n      exams=x.exams||[];\r\n      loadAdminExams();\r\n    }),\r\n\r\n    settle(async()=>{\r\n      const m=await authedApi('/api/materials?auth=1',{});\r\n      materials=m.materials||[];\r\n      loadAdminMaterials();\r\n    }),\r\n\r\n  ]);\r\n\r\n  loadAgentReach();\r\n\r\n  loadExamTracker().catch(() => {});\r\n\r\n  loadSocial().catch(() => {});\r\n\r\n  loadSalaryAdmin().catch(() => {});\r\n\r\n  loadWalkinAdmin().catch(() => {});\r\n\r\n  loadWaSubs().catch(() => {});\r\n\r\n  loadCompanyReviews().catch(() => {});\r\n\r\n  loadBlogAdmin().catch(() => {});\r\n\r\n  loadInterviewAdmin().catch(() => {});\r\n}\r\n\r\nfunction renderContactMessages(list){\r\n  const root=$('adminContact'); if(!root)return;\r\n  root.innerHTML=list.length?list.map(m=>`<article class=\"dash-card\" style=\"margin-bottom:10px\"><div style=\"display:flex;justify-content:space-between;gap:12px\"><div><b>${esc(m.name)}</b><div style=\"color:#94a3b8\">${esc(m.email)} · ${esc(m.created_at||'')}</div></div><select data-contact-status=\"${esc(m.id)}\"><option ${m.status==='New'?'selected':''}>New</option><option ${m.status==='Read'?'selected':''}>Read</option><option ${m.status==='Resolved'?'selected':''}>Resolved</option><option ${m.status==='Spam'?'selected':''}>Spam</option></select></div><p style=\"white-space:pre-wrap;color:#cbd5e1;margin:12px 0\">${esc(m.message)}</p></article>`).join(''):'<p style=\"color:#6a8aaa\">No contact messages.</p>';\r\n  root.querySelectorAll('[data-contact-status]').forEach(el=>el.onchange=async()=>{try{await api('/api/contact',{method:'PATCH',body:JSON.stringify({id:el.dataset.contactStatus,status:el.value})});toast('Contact status updated.')}catch(e){toast(e.message)}});\r\n}\r\n\r\n/* METRICS */\r\n\r\nfunction renderMetrics(an,reports){\r\n\r\n  $('metrics').innerHTML=[\r\n\r\n    ['Visitors today',an.visitors_today||0],\r\n\r\n    ['Unique visitors',an.unique_visitors||0],\r\n\r\n    ['This week',an.visitors_week||0],\r\n\r\n    ['This month',an.visitors_month||0],\r\n\r\n    ['Page views',an.total_page_views||0],\r\n\r\n    ['Total jobs',jobs.length],\r\n\r\n    [\r\n      'Published jobs',\r\n      jobs.filter(j=>j.published).length\r\n    ],\r\n\r\n    [\r\n      'Open reports',\r\n      reports.filter(\r\n        r=>r.status==='Open'\r\n      ).length\r\n    ]\r\n\r\n  ].map(x=>\r\n    `<div class=\"metric\">\r\n      <span>${x[0]}</span>\r\n      <b>${Number(x[1]).toLocaleString('en-IN')}</b>\r\n    </div>`\r\n  ).join('');\r\n}\r\n\r\n/* ANALYTICS */\r\n\r\nfunction bars(rows,lk,vk){\r\n\r\n  const max=Math.max(\r\n    1,\r\n    ...rows.map(x=>Number(x[vk]||0))\r\n  );\r\n\r\n  return rows.length\r\n\r\n    ?rows.map(x=>\r\n      `<div class=\"bar-row\">\r\n        <span>${esc(x[lk])}</span>\r\n        <div class=\"bar\">\r\n          <i style=\"width:${Math.max(\r\n            3,\r\n            Number(x[vk]||0)/max*100\r\n          )}%\"></i>\r\n        </div>\r\n        <b>${Number(x[vk]||0)}</b>\r\n      </div>`\r\n    ).join('')\r\n\r\n    :'<p style=\"color:#6a8aaa;font-size:.82rem\">No data yet.</p>';\r\n}\r\n\r\nfunction renderAnalytics(a){\r\n\r\n  $('analyticsPanel').innerHTML=`\r\n\r\n    <div class=\"dash-card\">\r\n      <h3>Page views — last 7 days</h3>\r\n      ${bars(a.daily||[],'view_date','views')}\r\n    </div>\r\n\r\n    <div class=\"dash-card\">\r\n      <h3>Devices</h3>\r\n      ${bars(a.devices||[],'device','visits')}\r\n    </div>\r\n\r\n    <div class=\"dash-card\">\r\n      <h3>Top pages</h3>\r\n      ${bars(a.top_pages||[],'path','views')}\r\n    </div>\r\n\r\n    <div class=\"dash-card\">\r\n      <h3>Traffic sources</h3>\r\n      ${bars(a.traffic_sources||[],'source','visits')}\r\n    </div>\r\n\r\n    <div class=\"dash-card\">\r\n      <h3>Countries</h3>\r\n      ${bars(a.countries||[],'country','visits')}\r\n    </div>\r\n\r\n    <div class=\"dash-card\">\r\n      <h3>Searches this month</h3>\r\n      <p style=\"color:#fff;font-size:1.5rem;font-weight:800\">\r\n        ${Number(\r\n          a.searches_month||0\r\n        ).toLocaleString('en-IN')}\r\n      </p>\r\n    </div>\r\n  `;\r\n}\r\n\r\n/* JOBS */\r\n\r\nfunction loadAdminJobs(){\r\n\r\n  const showExpired=\r\n    $('showExpiredAdmin').checked;\r\n  const statusFilter=\r\n    $('adminJobStatusFilter')?.value || 'all';\r\n\r\n  let list=showExpired\r\n    ?jobs\r\n    :jobs.filter(\r\n      j=>j.status!=='Expired'\r\n    );\r\n\r\n  /* Drafts belong to the Discovery → Review Jobs queue; the Jobs tab manages the\r\n     live list (published / deleted / needs-edit). Unpublished rows that the\r\n     pipeline staged are therefore never listed here. */\r\n  const isDraftRow=j=>j.published===false && j.status!=='Deleted' && j.review_state!=='Deleted';\r\n  list=list.filter(j=>!isDraftRow(j));\r\n\r\n  if(statusFilter==='published'){\r\n    list=list.filter(j=>j.published===true && j.status!=='Deleted');\r\n  }else if(statusFilter==='deleted'){\r\n    list=list.filter(j=>j.status==='Deleted' || j.review_state==='Deleted');\r\n  }else if(statusFilter==='needs_edit'){\r\n    list=list.filter(j=>String(j.review_state||'').toLowerCase()==='needs edit' || String(j.status||'').toLowerCase()==='needs edit');\r\n  }\r\n\r\n  $('adminJobs').innerHTML=\r\n\r\n    list.length\r\n\r\n    ?list.map(j=>`\r\n\r\n      <div class=\"list-item admin-job-row\" data-job-id=\"${esc(j.id)}\">\r\n\r\n        <input class=\"admin-job-select\" type=\"checkbox\" value=\"${esc(j.id)}\" aria-label=\"Select ${esc(j.role||'Untitled')}\" onchange=\"toggleSelectedJob(this)\">\r\n\r\n        <div class=\"list-item-info\">\r\n\r\n          <h4>\r\n\r\n            ${esc(j.role||'Untitled')}\r\n\r\n            <span class=\"status-badge ${\r\n              j.published\r\n              ?'published'\r\n              :'unpublished'\r\n            }\">\r\n\r\n              ${j.published\r\n                ?'Published'\r\n                :'Draft'}\r\n\r\n            </span>\r\n\r\n            ${\r\n              j.status==='Expired'\r\n              ?'<span class=\"status-badge expired\">Expired</span>'\r\n              :j.status==='Deleted' || j.review_state==='Deleted'\r\n              ?'<span class=\"status-badge expired\">Deleted</span>'\r\n              :String(j.review_state||'').toLowerCase()==='needs edit' || String(j.status||'').toLowerCase()==='needs edit'\r\n              ?'<span class=\"status-badge unpublished\">Needs to be edited</span>'\r\n              :''\r\n            }\r\n\r\n          </h4>\r\n\r\n          <p>\r\n            ${esc(j.company||'')}\r\n            ·\r\n            ${esc(j.sector||'Private')}\r\n            ·\r\n            ${esc(j.location||'')}\r\n          </p>\r\n\r\n        </div>\r\n\r\n        <div class=\"mini-actions\">\r\n\r\n          <button\r\n            onclick=\"jobEditor(jobs.find(x=>x.id==='${j.id}'))\">\r\n            Edit\r\n          </button>\r\n\r\n          <button\r\n            class=\"btn-publish\"\r\n            onclick=\"toggleJob('${j.id}',${!j.published})\">\r\n\r\n            ${j.published\r\n              ?'Unpublish'\r\n              :'Publish'}\r\n\r\n          </button>\r\n\r\n          <button\r\n            class=\"btn-delete\"\r\n            onclick=\"confirmDelete('/api/jobs','${j.id}')\">\r\n            Delete\r\n          </button>\r\n\r\n        </div>\r\n\r\n      </div>\r\n\r\n    `).join('')\r\n\r\n    :'<p style=\"color:#6a8aaa;padding:1rem\">No jobs found.</p>';\r\n\r\n  /* Server-side pagination (Phase AG): the admin browser holds one bounded\r\n     page; older pages stay on the server. */\r\n  const pager=$('adminJobsPager')||(()=>{const el=document.createElement('div');el.id='adminJobsPager';$('adminJobs').parentElement.appendChild(el);return el})();\r\n  pager.innerHTML=ccJobsMeta.pages>1\r\n    ?`<div class=\"cc-pagination\">\r\n        <button class=\"btn-ghost\" ${ccJobsMeta.page<=1?'disabled':''} onclick=\"loadAll(${ccJobsMeta.page-1})\">Previous</button>\r\n        <span>Page ${ccJobsMeta.page} of ${ccJobsMeta.pages} · ${Number(ccJobsMeta.total||0).toLocaleString('en-IN')} jobs</span>\r\n        <button class=\"btn-ghost\" ${!ccJobsMeta.has_next?'disabled':''} onclick=\"loadAll(${ccJobsMeta.page+1})\">Next</button>\r\n      </div>`\r\n    :'';\r\n}\r\n\r\nasync function toggleJob(id,published){\r\n\r\n  await api('/api/jobs',{\r\n    method:'PATCH',\r\n    key:adminKey,\r\n    body:JSON.stringify({\r\n      id,\r\n      published\r\n    })\r\n  });\r\n\r\n  toast(\r\n    published\r\n    ?'Job published ✓'\r\n    :'Job unpublished'\r\n  );\r\n\r\n  const j=jobs.find(\r\n    x=>x.id===id\r\n  );\r\n\r\n  if(j)j.published=published;\r\n\r\n  loadAdminJobs();\r\n}\r\n\r\nasync function confirmDelete(url,id){\r\n\r\n  if(!confirm('Delete permanently?'))return;\r\n\r\n  await api(url,{\r\n    method:'DELETE',\r\n    key:adminKey,\r\n    body:JSON.stringify({id})\r\n  });\r\n\r\n  toast('Deleted.');\r\n\r\n  jobs=jobs.filter(\r\n    x=>x.id!==id\r\n  );\r\n\r\n  exams=exams.filter(\r\n    x=>x.id!==id\r\n  );\r\n\r\n  materials=materials.filter(\r\n    x=>x.id!==id\r\n  );\r\n\r\n  loadAdminJobs();\r\n\r\n  loadAdminExams();\r\n\r\n  loadAdminMaterials();\r\n}\r\n\r\nasync function statusUpdate(url,id,status){\r\n\r\n  await api(url,{\r\n    method:'PATCH',\r\n    key:adminKey,\r\n    body:JSON.stringify({\r\n      id,\r\n      status\r\n    })\r\n  });\r\n\r\n  toast('Updated.');\r\n\r\n  await loadAll();\r\n}\r\n\r\n/* EXAMS */\r\n\r\nfunction loadAdminExams(){\r\n\r\n  $('adminExams').innerHTML=\r\n\r\n    exams.length\r\n\r\n    ?exams.map(x=>`\r\n\r\n      <div class=\"list-item\">\r\n\r\n        <div class=\"list-item-info\">\r\n\r\n          <h4>\r\n            ${esc(x.code||'')}\r\n            —\r\n            ${esc(x.title_en||'Untitled')}\r\n          </h4>\r\n\r\n          <p>\r\n            ${esc(x.authority||'')}\r\n            · Deadline:\r\n            ${x.application_end||'—'}\r\n          </p>\r\n\r\n        </div>\r\n\r\n        <div class=\"mini-actions\">\r\n\r\n          <button\r\n            onclick=\"examEditor(exams.find(e=>e.id==='${x.id}'))\">\r\n            Edit\r\n          </button>\r\n\r\n          <button\r\n            class=\"btn-delete\"\r\n            onclick=\"confirmDelete('/api/exams','${x.id}')\">\r\n            Delete\r\n          </button>\r\n\r\n        </div>\r\n\r\n      </div>\r\n\r\n    `).join('')\r\n\r\n    :'<p style=\"color:#6a8aaa;padding:1rem\">No exams found.</p>';\r\n}\r\n\r\n/* MATERIALS */\r\n\r\nfunction loadAdminMaterials(){\r\n\r\n  $('adminMaterials').innerHTML=\r\n\r\n    materials.length\r\n\r\n    ?materials.map(m=>`\r\n\r\n      <div class=\"list-item\">\r\n\r\n        <div class=\"list-item-info\">\r\n\r\n          <h4>\r\n            ${esc(m.title_en||'Untitled')}\r\n            ${m.published\r\n              ?''\r\n              :'<span class=\"status-badge unpublished\">Pending</span>'}\r\n          </h4>\r\n\r\n          <p>\r\n            ${esc(m.category||'')}\r\n            ·\r\n            <a\r\n              href=\"${esc(m.file_url)}\"\r\n              target=\"_blank\"\r\n              style=\"color:#c9973c\">\r\n              Open →\r\n            </a>\r\n          </p>\r\n\r\n        </div>\r\n\r\n        <div class=\"mini-actions\">\r\n\r\n          <button\r\n            class=\"btn-publish\"\r\n            onclick=\"toggleMaterial('${m.id}',${!m.published})\">\r\n            ${m.published\r\n              ?'Unpublish'\r\n              :'Publish'}\r\n          </button>\r\n\r\n          <button\r\n            onclick=\"materialEditor(materials.find(x=>x.id==='${m.id}'))\">\r\n            Edit\r\n          </button>\r\n\r\n          <button\r\n            class=\"btn-delete\"\r\n            onclick=\"confirmDelete('/api/materials','${m.id}')\">\r\n            Delete\r\n          </button>\r\n\r\n        </div>\r\n\r\n      </div>\r\n\r\n    `).join('')\r\n\r\n    :'<p style=\"color:#6a8aaa;padding:1rem\">No materials found.</p>';\r\n}\r\n\r\n/* SUBMISSIONS */\r\n\r\nfunction renderSubmissions(emp,res){\r\n\r\n  $('adminSubmissions').innerHTML=`\r\n\r\n    <h3 style=\"color:#fff;font-size:1rem;font-weight:700;margin-bottom:12px\">\r\n      Employer job submissions\r\n    </h3>\r\n\r\n    ${\r\n      emp.length\r\n\r\n      ?emp.map(x=>`\r\n\r\n        <div class=\"list-item\">\r\n\r\n          <div class=\"list-item-info\">\r\n\r\n            <h4>\r\n\r\n              ${esc(x.job_title||'')}\r\n\r\n              <span class=\"status-badge ${\r\n                x.status==='Approved'\r\n                ?'published'\r\n                :x.status==='Rejected'\r\n                ?'expired'\r\n                :'unpublished'\r\n              }\">\r\n\r\n                ${esc(x.status||'')}\r\n\r\n              </span>\r\n\r\n            </h4>\r\n\r\n            <p>\r\n              ${esc(x.company_name||'')}\r\n              ·\r\n              <a\r\n                href=\"${esc(x.official_url||'#')}\"\r\n                target=\"_blank\"\r\n                style=\"color:#c9973c\">\r\n                ${x.is_featured?'<span class=\"status-badge published\">⭐ FEATURED</span>':''}\r\n              <a\r\n                href=\"${esc(x.official_url||'#')}\"\r\n                target=\"_blank\"\r\n                style=\"color:#c9973c\">\r\n                View URL →\r\n              </a>\r\n            </p>\r\n            ${x.payment_utr?`<p>UTR: <code>${esc(x.payment_utr)}</code></p>`:''}\r\n\r\n          </div>\r\n\r\n          <div class=\"mini-actions\">\r\n\r\n            <button onclick=\"jobEditor({\r\n              role:'${esc(x.job_title)}',\r\n              company:'${esc(x.company_name)}',\r\n              location:'${esc(x.location)}',\r\n              description:'${esc(x.description)}',\r\n              qualification:'${esc(x.qualification)}',\r\n              experience_level:'${esc(x.experience)}',\r\n              employment_type:'${esc(x.employment_type)}',\r\n              salary:'${esc(x.salary)}',\r\n              source_url:'${esc(x.official_url)}',\r\n              sector:'Private',\r\n              _submission:'${x.id}'\r\n            })\">\r\n              Review\r\n            </button>\r\n\r\n            <button\r\n              class=\"btn-delete\"\r\n              onclick=\"statusUpdate('/api/employer-submissions','${x.id}','Rejected')\">\r\n              Reject\r\n            </button>\r\n\r\n          </div>\r\n\r\n        </div>\r\n\r\n      `).join('')\r\n\r\n      :'<p style=\"color:#6a8aaa;padding:1rem\">No employer submissions.</p>'\r\n    }\r\n\r\n    <h3 style=\"color:#fff;font-size:1rem;font-weight:700;margin:1.5rem 0 12px\">\r\n      Resource submissions\r\n    </h3>\r\n\r\n    ${\r\n      res.length\r\n\r\n      ?res.map(x=>`\r\n\r\n        <div class=\"list-item\">\r\n\r\n          <div class=\"list-item-info\">\r\n\r\n            <h4>\r\n\r\n              ${esc(x.title||'')}\r\n\r\n              <span class=\"status-badge ${\r\n                x.status==='Approved'\r\n                ?'published'\r\n                :x.status==='Rejected'\r\n                ?'expired'\r\n                :'unpublished'\r\n              }\">\r\n\r\n                ${esc(x.status||'')}\r\n\r\n              </span>\r\n\r\n            </h4>\r\n\r\n            <p>\r\n              ${esc(x.category||'')}\r\n              ·\r\n              <a\r\n                href=\"${esc(x.resource_url||'#')}\"\r\n                target=\"_blank\"\r\n                style=\"color:#c9973c\">\r\n                Open →\r\n              </a>\r\n            </p>\r\n\r\n          </div>\r\n\r\n          <div class=\"mini-actions\">\r\n\r\n            <button\r\n              class=\"btn-publish\"\r\n              onclick=\"statusUpdate('/api/resource-submissions','${x.id}','Approved')\">\r\n              Approve\r\n            </button>\r\n\r\n            <button\r\n              class=\"btn-delete\"\r\n              onclick=\"statusUpdate('/api/resource-submissions','${x.id}','Rejected')\">\r\n              Reject\r\n            </button>\r\n\r\n          </div>\r\n\r\n        </div>\r\n\r\n      `).join('')\r\n\r\n      :'<p style=\"color:#6a8aaa;padding:1rem\">No resource submissions.</p>'\r\n    }\r\n  `;\r\n}\r\n\r\n/* REPORTS */\r\n\r\nfunction renderReports(reports){\r\n\r\n  $('adminReports').innerHTML=\r\n\r\n    reports.length\r\n\r\n    ?reports.map(x=>`\r\n\r\n      <div class=\"list-item\">\r\n\r\n        <div class=\"list-item-info\">\r\n\r\n          <h4>\r\n\r\n            ${esc(x.report_type||'')}\r\n\r\n            <span class=\"status-badge ${\r\n              x.status==='Resolved'\r\n              ?'published'\r\n              :x.status==='Dismissed'\r\n              ?'expired'\r\n              :'unpublished'\r\n            }\">\r\n\r\n              ${esc(x.status||'')}\r\n\r\n            </span>\r\n\r\n          </h4>\r\n\r\n          <p>\r\n            ${esc(\r\n              (x.details||'').slice(0,100)\r\n            )}\r\n          </p>\r\n\r\n        </div>\r\n\r\n        <div class=\"mini-actions\">\r\n\r\n          <button\r\n            class=\"btn-publish\"\r\n            onclick=\"statusUpdate('/api/reports','${x.id}','Resolved')\">\r\n            Resolve\r\n          </button>\r\n\r\n          <button\r\n            class=\"btn-delete\"\r\n            onclick=\"statusUpdate('/api/reports','${x.id}','Dismissed')\">\r\n            Dismiss\r\n          </button>\r\n\r\n        </div>\r\n\r\n      </div>\r\n\r\n    `).join('')\r\n\r\n    :'<p style=\"color:#6a8aaa;padding:1rem\">No reports.</p>';\r\n}\r\n\r\n/* JOB EDITOR */\r\n\r\nfunction jobEditor(j={}){\r\n\r\n  $('editorTitle').textContent=\r\n    j.id\r\n    ?'Edit opportunity'\r\n    :'Add opportunity';\r\n\r\n  $('editorBody').innerHTML=`\r\n\r\n<form id=\"jobEdit\">\r\n\r\n<div class=\"field-grid\">\r\n\r\n<label>\r\nSector\r\n<select name=\"sector\" id=\"adminSectorSelect\">\r\n\r\n<option ${\r\n  (j.sector||'Private')==='Private'\r\n  ?'selected'\r\n  :''\r\n}>\r\nPrivate\r\n</option>\r\n\r\n<option ${\r\n  j.sector==='Government'\r\n  ?'selected'\r\n  :''\r\n}>\r\nGovernment\r\n</option>\r\n\r\n<option ${\r\n  j.sector==='Public Sector'\r\n  ?'selected'\r\n  :''\r\n}>\r\nPublic Sector\r\n</option>\r\n\r\n</select>\r\n</label>\r\n\r\n<label>\r\nJob title *\r\n<input\r\nname=\"role\"\r\nvalue=\"${val(j.role)}\"\r\nrequired\r\nplaceholder=\"e.g. Site Engineer\">\r\n</label>\r\n\r\n<label>\r\nCompany / Department\r\n<input\r\nname=\"company\"\r\nvalue=\"${val(j.company)}\"\r\nplaceholder=\"e.g. L&T, KPSC\">\r\n</label>\r\n\r\n<label>\r\nLocation\r\n<input\r\nname=\"location\"\r\nvalue=\"${val(j.location)}\"\r\nplaceholder=\"e.g. Bengaluru, Karnataka\">\r\n</label>\r\n\r\n<label>\r\nState\r\n<input\r\nname=\"state\"\r\nvalue=\"${val(j.state)}\"\r\nplaceholder=\"e.g. Karnataka\">\r\n</label>\r\n\r\n<label>\r\nCountry\r\n<input\r\nname=\"country\"\r\nvalue=\"${val(j.country||'India')}\"\r\nplaceholder=\"e.g. India\">\r\n</label>\r\n\r\n<label>\r\nQualification\r\n<input\r\nname=\"qualification\"\r\nvalue=\"${val(j.qualification)}\"\r\nplaceholder=\"e.g. B.E. Civil\">\r\n</label>\r\n\r\n<label>\r\nExperience\r\n<input\r\nname=\"experience_level\"\r\nvalue=\"${val(j.experience_level)}\"\r\nplaceholder=\"e.g. 2-5 years\">\r\n</label>\r\n\r\n<label>\r\nEmployment type\r\n<input\r\nname=\"employment_type\"\r\nvalue=\"${val(j.employment_type||'Full-time')}\">\r\n</label>\r\n\r\n<label>\r\nSalary / Pay scale\r\n<input\r\nname=\"salary\"\r\nvalue=\"${val(j.salary)}\"\r\nplaceholder=\"e.g. ₹4-7 LPA\">\r\n</label>\r\n\r\n<label class=\"gov-only-field\">\r\nVacancies\r\n<input\r\ntype=\"number\"\r\nname=\"vacancy_count\"\r\nvalue=\"${val(j.vacancy_count)}\"\r\nplaceholder=\"e.g. 50\">\r\n</label>\r\n\r\n<label class=\"gov-only-field\">\r\nApplication starts\r\n<input\r\ntype=\"date\"\r\nname=\"application_start\"\r\nvalue=\"${val(j.application_start)}\">\r\n</label>\r\n\r\n<label class=\"gov-only-field\">\r\nApplication deadline\r\n<input\r\ntype=\"date\"\r\nname=\"deadline\"\r\nvalue=\"${val(j.deadline)}\">\r\n</label>\r\n\r\n<label class=\"gov-only-field\">\r\nAge limit\r\n<input\r\nname=\"age_limit\"\r\nvalue=\"${val(j.age_limit)}\"\r\nplaceholder=\"e.g. 18-35\">\r\n</label>\r\n\r\n<label class=\"gov-only-field\">\r\nApplication fee\r\n<input\r\nname=\"application_fee\"\r\nvalue=\"${val(j.application_fee)}\"\r\nplaceholder=\"e.g. ₹200\">\r\n</label>\r\n\r\n<label>\r\nStatus\r\n<select name=\"status\">\r\n\r\n<option ${\r\n  j.status!=='Expired'\r\n  ?'selected'\r\n  :''\r\n}>\r\nActive\r\n</option>\r\n\r\n<option ${\r\n  j.status==='Expired'\r\n  ?'selected'\r\n  :''\r\n}>\r\nExpired\r\n</option>\r\n\r\n</select>\r\n</label>\r\n\r\n<label class=\"gov-only-field\">\r\nLast verified\r\n<input\r\ntype=\"date\"\r\nname=\"last_verified\"\r\nvalue=\"${val(\r\n  j.last_verified||\r\n  new Date().toISOString().slice(0,10)\r\n)}\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nSkills\r\n<input\r\nname=\"skills\"\r\nvalue=\"${val(j.skills)}\"\r\nplaceholder=\"AutoCAD, STAAD Pro, estimation, site supervision\">\r\n</label>\r\n\r\n<label class=\"wide gov-only-field\">\r\nRecruitment authority\r\n<input\r\nname=\"recruitment_authority\"\r\nvalue=\"${val(j.recruitment_authority)}\"\r\nplaceholder=\"KPSC, department, recruiting authority\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nOfficial notification / source URL *\r\n<input\r\ntype=\"url\"\r\nname=\"source_url\"\r\nvalue=\"${val(j.source_url)}\"\r\nrequired\r\nplaceholder=\"https://...\">\r\n</label>\r\n\r\n<label class=\"wide gov-only-field\">\r\nOnline apply URL\r\n<input\r\ntype=\"url\"\r\nname=\"application_url\"\r\nvalue=\"${val(\r\n  j.application_url||\r\n  j.apply_url\r\n)}\"\r\nplaceholder=\"https://...\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nApplication email\r\n<input\r\ntype=\"email\"\r\nname=\"application_email\"\r\nvalue=\"${val(\r\n  j.application_email||\r\n  j.application_method\r\n)}\"\r\nplaceholder=\"hr@company.com\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nDescription\r\n<textarea name=\"description\">${val(j.description)}</textarea>\r\n</label>\r\n\r\n<button type=\"submit\" class=\"btn-save\">\r\n${j._keepUnpublished\r\n  ?'Save (stays unpublished)'\r\n  :'Save & Publish'}\r\n</button>\r\n\r\n<div class=\"save-status\" id=\"saveStatus\"></div>\r\n\r\n</div>\r\n\r\n</form>\r\n`;\r\n\r\n  $('editorDialog').showModal();\r\n\r\n  /* ── Dynamic sector fields: Government shows recruitment fields,\r\n     Private hides them. Switching back and forth is fully reversible. ── */\r\n  function syncAdminSectorFields(){\r\n    const sel=$('adminSectorSelect');\r\n    if(!sel)return;\r\n    const isGov=/gov|public/i.test(sel.value);\r\n    document.querySelectorAll('#jobEdit .gov-only-field').forEach(l=>{\r\n      l.style.display=isGov?'':'none';\r\n    });\r\n  }\r\n  window.syncAdminSectorFields=syncAdminSectorFields;\r\n  $('adminSectorSelect').addEventListener('change',syncAdminSectorFields);\r\n  syncAdminSectorFields();\r\n\r\n  $('jobEdit').onsubmit=async e=>{\r\n\r\n    e.preventDefault();\r\n\r\n    const d=formObject(e.target);\r\n\r\n    /* Private jobs: drop government-recruitment values instead of saving\r\n       stale/empty ones. Government/Public Sector keeps every field. */\r\n    if(!/gov|public/i.test(d.sector)){\r\n      ['application_start','deadline','age_limit','application_fee','last_verified','recruitment_authority','application_url'].forEach(n=>{delete d[n];});\r\n    }\r\n\r\n    /* Review-first: items opened from the Agent Reach inbox keep their\r\n       pending state after an edit — publishing stays an explicit action\r\n       in the inbox. Regular admin jobs still save as published. */\r\n    d.published=j._keepUnpublished===true?false:true;\r\n\r\n    if(j.id)d.id=j.id;\r\n\r\n    const st=$('saveStatus');\r\n\r\n    st.className='save-status show';\r\n\r\n    st.textContent='Saving…';\r\n\r\n    try{\r\n\r\n      const saved=await api(\r\n        '/api/jobs',\r\n        {\r\n          method:j.id?'PATCH':'POST',\r\n          key:adminKey,\r\n          body:JSON.stringify(d)\r\n        }\r\n      );\r\n\r\n      if(j._submission){\r\n\r\n        await statusUpdate(\r\n          '/api/employer-submissions',\r\n          j._submission,\r\n          'Approved'\r\n        );\r\n      }\r\n\r\n      if(!j.id){\r\n\r\n        fetch('/api/telegram',{\r\n          method:'POST',\r\n          headers:{\r\n            'content-type':'application/json'\r\n          },\r\n          body:JSON.stringify({job:d})\r\n        }).catch(()=>{});\r\n\r\n      }\r\n\r\n      st.className=\r\n        'save-status show success';\r\n\r\n      st.textContent=\r\n        'Saved successfully ✓';\r\n\r\n      toast('Opportunity saved.');\r\n\r\n      const newJob=\r\n        saved.job||\r\n        {...d,id:Date.now().toString()};\r\n\r\n      if(j.id){\r\n\r\n        const idx=\r\n          jobs.findIndex(\r\n            x=>x.id===j.id\r\n          );\r\n\r\n        if(idx>-1)jobs[idx]=newJob;\r\n\r\n      }else{\r\n\r\n        jobs.unshift(newJob);\r\n      }\r\n\r\n      loadAdminJobs();\r\n\r\n      setTimeout(\r\n        ()=>$('editorDialog').close(),\r\n        800\r\n      );\r\n\r\n    }catch(err){\r\n\r\n      st.className=\r\n        'save-status show error';\r\n\r\n      st.textContent=\r\n        err.message;\r\n    }\r\n  };\r\n}\r\n\r\n/* EXAM EDITOR */\r\n\r\nfunction examEditor(x={}){\r\n\r\n  $('editorTitle').textContent=\r\n    x.id\r\n    ?'Edit exam'\r\n    :'Add exam';\r\n\r\n  $('editorBody').innerHTML=`\r\n\r\n<form id=\"examEdit\">\r\n\r\n<div class=\"field-grid\">\r\n\r\n<label>\r\nCode *\r\n<input\r\nname=\"code\"\r\nvalue=\"${val(x.code)}\"\r\nrequired\r\nplaceholder=\"e.g. KPSC-AE\">\r\n</label>\r\n\r\n<label>\r\nAuthority\r\n<input\r\nname=\"authority\"\r\nvalue=\"${val(x.authority)}\"\r\nplaceholder=\"e.g. Karnataka PSC\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nTitle (English) *\r\n<input\r\nname=\"title_en\"\r\nvalue=\"${val(x.title_en)}\"\r\nrequired\r\nplaceholder=\"e.g. KPSC AE Recruitment 2026\">\r\n</label>\r\n\r\n<label>\r\nVacancies\r\n<input\r\ntype=\"number\"\r\nname=\"vacancy_count\"\r\nvalue=\"${val(x.vacancy_count)}\">\r\n</label>\r\n\r\n<label>\r\nStatus\r\n<input\r\nname=\"status\"\r\nvalue=\"${val(x.status||'Open')}\"\r\nplaceholder=\"Open / Upcoming / Closed\">\r\n</label>\r\n\r\n<label>\r\nApplication start\r\n<input\r\ntype=\"date\"\r\nname=\"application_start\"\r\nvalue=\"${val(x.application_start)}\">\r\n</label>\r\n\r\n<label>\r\nApplication deadline\r\n<input\r\ntype=\"date\"\r\nname=\"application_end\"\r\nvalue=\"${val(x.application_end)}\">\r\n</label>\r\n\r\n<label>\r\nExam date\r\n<input\r\ntype=\"date\"\r\nname=\"exam_date\"\r\nvalue=\"${val(x.exam_date)}\">\r\n</label>\r\n\r\n<label>\r\nLast verified\r\n<input\r\ntype=\"date\"\r\nname=\"last_verified\"\r\nvalue=\"${val(\r\n  x.last_verified||\r\n  new Date().toISOString().slice(0,10)\r\n)}\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nPost names\r\n<input\r\nname=\"post_names\"\r\nvalue=\"${val(x.post_names)}\"\r\nplaceholder=\"e.g. AE Civil, JE Civil\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nOverview\r\n<textarea name=\"overview\">${val(x.overview)}</textarea>\r\n</label>\r\n\r\n<label class=\"wide\">\r\nEligibility\r\n<textarea name=\"eligibility_en\">${val(x.eligibility_en)}</textarea>\r\n</label>\r\n\r\n<label class=\"wide\">\r\nAge limit\r\n<textarea name=\"age_limit\">${val(x.age_limit)}</textarea>\r\n</label>\r\n\r\n<label class=\"wide\">\r\nPay scale\r\n<textarea name=\"pay_scale\">${val(x.pay_scale)}</textarea>\r\n</label>\r\n\r\n<label class=\"wide\">\r\nApplication fee\r\n<textarea name=\"application_fee\">${val(x.application_fee)}</textarea>\r\n</label>\r\n\r\n<label class=\"wide\">\r\nHow to apply\r\n<textarea name=\"how_to_apply\">${val(x.how_to_apply)}</textarea>\r\n</label>\r\n\r\n<label class=\"wide\">\r\nOfficial notification PDF URL\r\n<input\r\ntype=\"url\"\r\nname=\"official_notification_url\"\r\nvalue=\"${val(x.official_notification_url)}\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nApply online URL\r\n<input\r\ntype=\"url\"\r\nname=\"apply_url\"\r\nvalue=\"${val(x.apply_url)}\">\r\n</label>\r\n\r\n<button type=\"submit\" class=\"btn-save\">\r\nSave & Publish\r\n</button>\r\n\r\n<div class=\"save-status\" id=\"saveStatus\"></div>\r\n\r\n</div>\r\n</form>\r\n`;\r\n\r\n  $('editorDialog').showModal();\r\n\r\n  $('examEdit').onsubmit=async e=>{\r\n\r\n    e.preventDefault();\r\n\r\n    const d=formObject(e.target);\r\n\r\n    if(x.id)d.id=x.id;\r\n\r\n    const st=$('saveStatus');\r\n\r\n    st.className='save-status show';\r\n\r\n    st.textContent='Saving…';\r\n\r\n    try{\r\n\r\n      await api('/api/exams',{\r\n        method:x.id?'PATCH':'POST',\r\n        key:adminKey,\r\n        body:JSON.stringify(d)\r\n      });\r\n\r\n      st.className=\r\n        'save-status show success';\r\n\r\n      st.textContent='Saved ✓';\r\n\r\n      toast('Exam saved.');\r\n\r\n      loadAdminExams();\r\n\r\n      setTimeout(\r\n        ()=>$('editorDialog').close(),\r\n        800\r\n      );\r\n\r\n    }catch(err){\r\n\r\n      st.className=\r\n        'save-status show error';\r\n\r\n      st.textContent=err.message;\r\n    }\r\n  };\r\n}\r\n\r\n/* MATERIAL EDITOR */\r\n\r\nfunction materialEditor(m={}){\r\n\r\n  $('editorTitle').textContent=\r\n    m.id\r\n    ?'Edit material'\r\n    :'Add material';\r\n\r\n  $('editorBody').innerHTML=`\r\n\r\n<form id=\"materialEdit\">\r\n\r\n<div class=\"field-grid\">\r\n\r\n<label class=\"wide\">\r\nTitle *\r\n<input\r\nname=\"title_en\"\r\nvalue=\"${val(m.title_en)}\"\r\nrequired\r\nplaceholder=\"e.g. KPSC AE Civil Notes\">\r\n</label>\r\n\r\n<label>\r\nCategory\r\n<input\r\nname=\"category\"\r\nvalue=\"${val(m.category)}\"\r\nplaceholder=\"Civil Engineering / Competitive Exams\">\r\n</label>\r\n\r\n<label>\r\nAuthor\r\n<input\r\nname=\"author\"\r\nvalue=\"${val(m.author)}\">\r\n</label>\r\n\r\n<label>\r\nPages\r\n<input\r\ntype=\"number\"\r\nname=\"page_count\"\r\nvalue=\"${val(m.page_count)}\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nDescription\r\n<textarea name=\"description_en\">${val(m.description_en)}</textarea>\r\n</label>\r\n\r\n<label class=\"wide\">\r\nResource URL *\r\n<input\r\ntype=\"url\"\r\nname=\"file_url\"\r\nvalue=\"${val(m.file_url)}\"\r\nrequired\r\nplaceholder=\"https://drive.google.com/...\">\r\n</label>\r\n\r\n<button type=\"submit\" class=\"btn-save\">\r\nSave Material\r\n</button>\r\n\r\n<div class=\"save-status\" id=\"saveStatus\"></div>\r\n\r\n</div>\r\n</form>\r\n`;\r\n\r\n  $('editorDialog').showModal();\r\n\r\n  $('materialEdit').onsubmit=async e=>{\r\n\r\n    e.preventDefault();\r\n\r\n    const d=formObject(e.target);\r\n\r\n    d.access_type='Free';\r\n\r\n    if(m.id)d.id=m.id;\r\n\r\n    const st=$('saveStatus');\r\n\r\n    st.className='save-status show';\r\n\r\n    st.textContent='Saving…';\r\n\r\n    try{\r\n\r\n      await api('/api/materials',{\r\n        method:m.id?'PATCH':'POST',\r\n        key:adminKey,\r\n        body:JSON.stringify(d)\r\n      });\r\n\r\n      st.className=\r\n        'save-status show success';\r\n\r\n      st.textContent='Saved ✓';\r\n\r\n      toast('Material saved.');\r\n\r\n      loadAdminMaterials();\r\n\r\n      setTimeout(\r\n        ()=>$('editorDialog').close(),\r\n        800\r\n      );\r\n\r\n    }catch(err){\r\n\r\n      st.className=\r\n        'save-status show error';\r\n\r\n      st.textContent=err.message;\r\n    }\r\n  };\r\n}\r\n\r\n/* =====================================================\r\n   AI JOB IMPORT — FINAL VERSION\r\n   ===================================================== */\r\n\r\nasync function importJobLink(){\r\n\r\n  const url=\r\n    $('importJobUrl').value.trim();\r\n\r\n  const text=\r\n    $('importJobText').value.trim();\r\n\r\n  if(!url&&!text){\r\n\r\n    return setImportStatus(\r\n      'importJobStatus',\r\n      'Paste a URL, text, or both.',\r\n      'error'\r\n    );\r\n  }\r\n\r\n  const btn=$('importJobBtn');\r\n\r\n  btn.disabled=true;\r\n\r\n  btn.textContent='Extracting…';\r\n\r\n  setImportStatus(\r\n    'importJobStatus',\r\n    'Analyzing vacancy with the free AI fallback chain…'\r\n  );\r\n\r\n  try{\r\n\r\n    const data=await api(\r\n      '/api/extract',\r\n      {\r\n        method:'POST',\r\n        key:adminKey,\r\n        body:JSON.stringify({\r\n          url,\r\n          text\r\n        })\r\n      }\r\n    );\r\n\r\n    /*\r\n      IMPORTANT:\r\n\r\n      extract.js returns:\r\n\r\n      {\r\n        extracted: {...},\r\n        source: \"groq\"\r\n      }\r\n\r\n      Therefore we MUST read:\r\n\r\n      data.extracted\r\n\r\n      NOT:\r\n\r\n      data.job\r\n    */\r\n\r\n    const ai=data.extracted||{};\r\n\r\n    if(!Object.keys(ai).length){\r\n\r\n      throw new Error(\r\n        'AI returned no extracted fields.'\r\n      );\r\n    }\r\n\r\n    /*\r\n      Convert AI response into the exact\r\n      fields used by jobEditor().\r\n    */\r\n\r\n    const x={\r\n\r\n      role:ai.role||'',\r\n\r\n      company:ai.company||'',\r\n\r\n      location:ai.location||'',\r\n\r\n      state:ai.state||'',\r\n\r\n      country:ai.country||'India',\r\n\r\n      description:ai.description||'',\r\n\r\n      qualification:\r\n        ai.qualification||'',\r\n\r\n      skills:\r\n        ai.skills||'',\r\n\r\n      experience_level:\r\n        ai.experience_level||'',\r\n\r\n      salary:\r\n        ai.salary||'',\r\n\r\n      vacancy_count:\r\n        ai.vacancy_count||'',\r\n\r\n      deadline:\r\n        ai.deadline||'',\r\n\r\n      employment_type:\r\n        ai.employment_type||'',\r\n\r\n      sector:\r\n        ai.sector||'Private',\r\n\r\n      source_url:\r\n        ai.source_url||\r\n        url||\r\n        '',\r\n\r\n      application_url:\r\n        ai.apply_url||\r\n        ai.application_url||\r\n        '',\r\n\r\n      application_email:\r\n        ai.application_email||\r\n        '',\r\n\r\n      recruitment_authority:\r\n        ai.recruitment_authority||\r\n        '',\r\n\r\n      posted_date:\r\n        ai.posted_date||\r\n        '',\r\n\r\n      last_verified:\r\n        new Date()\r\n          .toISOString()\r\n          .slice(0,10),\r\n\r\n      status:'Active'\r\n\r\n    };\r\n\r\n    /*\r\n      Normalize date.\r\n    */\r\n\r\n    x.deadline=\r\n      (x.deadline||'')\r\n      .slice(0,10);\r\n\r\n    x.posted_date=\r\n      (x.posted_date||'')\r\n      .slice(0,10);\r\n\r\n    /*\r\n      Detect email addresses directly from\r\n      the pasted vacancy text.\r\n\r\n      This is independent of AI.\r\n    */\r\n\r\n    const emailSource=\r\n      text+' '+(url||'');\r\n\r\n    const emails=[\r\n      ...new Set(\r\n        emailSource.match(\r\n          /[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}/gi\r\n        )||[]\r\n      )\r\n    ];\r\n\r\n    const sel=\r\n      $('detectedEmailSelect');\r\n\r\n    sel.innerHTML=\r\n\r\n      emails.length\r\n\r\n      ?emails.map(email=>\r\n        `<option value=\"${esc(email)}\">\r\n          ${esc(email)}\r\n        </option>`\r\n      ).join('')\r\n\r\n      :'<option value=\"\">No email detected</option>';\r\n\r\n    /*\r\n      If AI supplied an email, use it.\r\n\r\n      Otherwise use the first detected\r\n      email from the vacancy text.\r\n    */\r\n\r\n    if(x.application_email){\r\n\r\n      $('importApplicationEmail').value=\r\n        x.application_email;\r\n\r\n    }else if(emails.length){\r\n\r\n      $('importApplicationEmail').value=\r\n        emails[0];\r\n\r\n      x.application_email=\r\n        emails[0];\r\n    }\r\n\r\n    /*\r\n      Tell the admin extraction succeeded.\r\n    */\r\n\r\n    setImportStatus(\r\n      'importJobStatus',\r\n\r\n      `Extraction complete using ${\r\n        data.source||'AI'\r\n      }. Verify every field before saving.${data.warning?' '+data.warning:''}`,\r\n\r\n      'success'\r\n    );\r\n\r\n    /*\r\n      Open the job editor with the\r\n      extracted information.\r\n    */\r\n\r\n    jobEditor(x);\r\n\r\n  }catch(err){\r\n\r\n    console.error(\r\n      'CivilCareer job extraction failed:',\r\n      err\r\n    );\r\n\r\n    setImportStatus(\r\n      'importJobStatus',\r\n      err.message||\r\n      'AI extraction failed.',\r\n      'error'\r\n    );\r\n\r\n  }finally{\r\n\r\n    btn.disabled=false;\r\n\r\n    btn.textContent=\r\n      'Extract & fill fields';\r\n  }\r\n}\r\n\r\nfunction useDetectedEmailFn(){\r\n\r\n  const v=\r\n    $('detectedEmailSelect').value;\r\n\r\n  if(v){\r\n\r\n    $('importApplicationEmail').value=v;\r\n  }\r\n}\r\n\r\nfunction clearJobImport(){\r\n\r\n  $('importJobUrl').value='';\r\n\r\n  $('importJobText').value='';\r\n\r\n  $('importApplicationEmail').value='';\r\n\r\n  $('detectedEmailSelect').innerHTML=\r\n    '<option value=\"\">No email detected yet</option>';\r\n\r\n  $('importJobStatus').className=\r\n    'import-status';\r\n\r\n  $('importJobStatus').textContent='';\r\n}\r\n\r\nfunction setImportStatus(\r\n  id,\r\n  msg,\r\n  type=''\r\n){\r\n\r\n  const el=$(id);\r\n\r\n  el.textContent=msg;\r\n\r\n  el.className=\r\n    `import-status show${\r\n      type?' '+type:''\r\n    }`;\r\n}\r\n\r\n/* PDF */\r\n\r\nasync function pdfText(file){\r\n\r\n  if(!window.pdfjsLib){\r\n\r\n    throw Error(\r\n      'PDF reader not loaded. Refresh and try again.'\r\n    );\r\n  }\r\n\r\n  window.pdfjsLib.GlobalWorkerOptions.workerSrc=\r\n    'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';\r\n\r\n  const bytes=\r\n    new Uint8Array(\r\n      await file.arrayBuffer()\r\n    );\r\n\r\n  const doc=\r\n    await window.pdfjsLib\r\n      .getDocument({data:bytes})\r\n      .promise;\r\n\r\n  let text='';\r\n\r\n  for(\r\n    let p=1;\r\n    p<=Math.min(doc.numPages,160);\r\n    p++\r\n  ){\r\n\r\n    const page=\r\n      await doc.getPage(p);\r\n\r\n    const content=\r\n      await page.getTextContent();\r\n\r\n    text+=\r\n      content.items\r\n        .map(x=>x.str)\r\n        .join(' ')+'\\n';\r\n  }\r\n\r\n  return text;\r\n}\r\n\r\nasync function importExamPdf(){\r\n\r\n  const file=\r\n    $('importExamPdf').files[0];\r\n\r\n  if(!file){\r\n\r\n    return setImportStatus(\r\n      'importExamStatus',\r\n      'Select a PDF first.',\r\n      'error'\r\n    );\r\n  }\r\n\r\n  if(\r\n    file.size>\r\n    20*1024*1024\r\n  ){\r\n\r\n    return setImportStatus(\r\n      'importExamStatus',\r\n      'Use a PDF under 20 MB.',\r\n      'error'\r\n    );\r\n  }\r\n\r\n  const btn=\r\n    $('importExamBtn');\r\n\r\n  btn.disabled=true;\r\n\r\n  btn.textContent='Reading…';\r\n\r\n  setImportStatus(\r\n    'importExamStatus',\r\n    'Extracting text…'\r\n  );\r\n\r\n  try{\r\n\r\n    const text=\r\n      await pdfText(file);\r\n\r\n    setImportStatus(\r\n      'importExamStatus',\r\n      'Organizing fields with AI…'\r\n    );\r\n\r\n    const data=\r\n      await api(\r\n        '/api/exam-extract',\r\n        {\r\n          method:'POST',\r\n          key:adminKey,\r\n          body:JSON.stringify({text})\r\n        }\r\n      );\r\n\r\n    const x=data.exam||{};\r\n\r\n    x.last_verified=\r\n      new Date()\r\n      .toISOString()\r\n      .slice(0,10);\r\n\r\n    setImportStatus(\r\n      'importExamStatus',\r\n      data.warning||\r\n      'Done. Verify all fields before saving.',\r\n      'success'\r\n    );\r\n\r\n    examEditor(x);\r\n\r\n  }catch(err){\r\n\r\n    setImportStatus(\r\n      'importExamStatus',\r\n      err.message,\r\n      'error'\r\n    );\r\n\r\n  }finally{\r\n\r\n    btn.disabled=false;\r\n\r\n    btn.textContent='Read PDF';\r\n  }\r\n}\r\n\r\n\r\n/* WEB DISCOVERY */\r\nfunction discoveryStatus(message,type='show'){\r\n  const el=$('discoveryStatus');\r\n  el.className=`discovery-status ${type}`;\r\n  el.textContent=message||'';\r\n}\r\n\r\n/* ── Phase 7: source label mapping ── */\r\nconst SOURCE_LABELS={\r\n  google_jobs:'Google Jobs (SerpApi)',\r\n  the_muse:'The Muse',\r\n  adzuna:'Adzuna',\r\n  jobvetta:'Jobvetta',\r\n  devglobal:'Dev Global Jobs (free)',\r\n  himalayas:'Himalayas (free)',\r\n  google_news:'Google News RSS (free)',\r\n  bing_news:'Bing News RSS (free)',\r\n  jobicy:'Jobicy (free)',\r\n  arbeitnow:'Arbeitnow (free)',\r\n  onjob:'OnJob India (free)',\r\n  hopin:'Hopin (free)',\r\n  company_careers:'Company career pages (free)'\r\n};\r\n\r\nfunction renderSourceHealth(sourceStats){\r\n  const panel=$('sourceHealthPanel');\r\n  const tbody=$('sourceHealthBody');\r\n  if(!sourceStats||!Object.keys(sourceStats).length){panel.classList.remove('show');return;}\r\n  const ORDER=['company_careers','devglobal','himalayas','onjob','hopin','google_news','bing_news','arbeitnow','jobicy','google_jobs','adzuna','the_muse','jobvetta'];\r\n  const allKeys=[...new Set([...ORDER,...Object.keys(sourceStats)])];\r\n  tbody.innerHTML=allKeys.map(key=>{\r\n    const v=sourceStats[key];\r\n    const label=SOURCE_LABELS[key]||key.replaceAll('_',' ');\r\n    if(!v){\r\n      return `<tr><td>${esc(label)}</td><td class=\"sh-nc\">⚪ Not run</td><td>—</td><td style=\"color:#4a6a8a;font-size:.72rem\">Not in this search</td></tr>`;\r\n    }\r\n    if(v.configured===false){\r\n      return `<tr><td>${esc(label)}</td><td class=\"sh-nc\">⚪ Not configured</td><td>—</td><td style=\"color:#4a6a8a;font-size:.72rem\">Add API key in Vercel env vars</td></tr>`;\r\n    }\r\n    if(v.ok){\r\n      const extra=v.remaining!=null?`Quota remaining: ${v.remaining}`:'';\r\n      return `<tr><td>${esc(label)}</td><td class=\"sh-ok\">🟢 OK</td><td class=\"sh-ok\">${Number(v.items||0)}</td><td style=\"color:#4a6a8a;font-size:.72rem\">${esc(extra)}</td></tr>`;\r\n    }\r\n    const errMsg=v.error||'Error';\r\n    const isQuota=/429|quota|rate.limit/i.test(errMsg);\r\n    const isTimeout=/timeout|abort/i.test(errMsg);\r\n    const isBlocked=v.blocked||/403|blocked|forbidden/i.test(errMsg);\r\n    const statusIcon=isQuota?'🟡 Quota':isBlocked?'🔵 Blocked':'🔴 Error';\r\n    const statusClass=isQuota?'sh-warn':isBlocked?'':'sh-error';\r\n    const statusStyle=isBlocked?'color:#60a5fa':'';\r\n    const resetNote=v.reset?` (resets ${v.reset})`:'';\r\n    return `<tr><td>${esc(label)}</td><td class=\"${statusClass}\" style=\"${statusStyle}\">${statusIcon}${resetNote}</td><td>0</td><td style=\"font-size:.72rem;color:${isBlocked?'#60a5fa':'#fca5a5'}\">${esc(isBlocked?'Source blocks server access':errMsg)}</td></tr>`;\r\n  }).join('');\r\n  panel.classList.add('show');\r\n}\r\n\r\nfunction renderDiscoverySummary(data){\r\n  const el=$('discoverySummary');\r\n  if(!data){el.classList.remove('show');return;}\r\n  const newDrafts=Number(data.count||0);\r\n  /*\r\n   * fresh24hCandidates is the POST-deduplication count of truly fresh (<24h)\r\n   * items that were newly saved this run. The old data.candidates was a\r\n   * PRE-dedup count — it caused \"3 fresh candidates\" to appear even when\r\n   * those 3 fresh jobs were already in the DB and the 3 newly inserted jobs\r\n   * were 10+ days old backup items. Fixed in api/jobs.js.\r\n   */\r\n  const fresh24h=Number(data.fresh24hCandidates!=null?data.fresh24hCandidates:data.candidates||0);\r\n  const backup30d=Number(data.backup30dCandidates||0);\r\n  const skipped=Number(data.skippedExisting||0);\r\n  const older=Number(data.olderCandidates||0);\r\n  const unknownDate=Number(data.unknownDateCandidates||0);\r\n  el.innerHTML=\r\n    `<strong>${newDrafts}</strong> new draft${newDrafts===1?'':'s'} added &nbsp;&middot;&nbsp; `+\r\n    `<strong style=\"color:#6ee7b7\">${fresh24h}</strong> &#x1F7E2; fresh (last 24&nbsp;h) &nbsp;&middot;&nbsp; `+\r\n    `<strong style=\"color:#fbbf24\">${backup30d}</strong> &#x1F554; backup (1&ndash;30&nbsp;d) &nbsp;&middot;&nbsp; `+\r\n    `<strong>${skipped}</strong> skipped (already in CivilCareer) &nbsp;&middot;&nbsp; `+\r\n    `<strong>${older}</strong> older than 30&nbsp;d`+\r\n    (unknownDate?` &nbsp;&middot;&nbsp; <strong>${unknownDate}</strong> no usable date`:'');\r\n  el.classList.add('show');\r\n}\r\n\r\nfunction renderDiscoveryResults(results){\r\n  const root=$('discoveryResults');\r\n  if(!results||!results.length){\r\n    root.innerHTML='<div class=\"dash-card\"><p style=\"color:#fca5a5;font-size:.82rem\">No new drafts were created — all discovered jobs are already in CivilCareer, or no sources returned results. Check Source Status above.</p></div>';\r\n    return;\r\n  }\r\n  root.innerHTML=results.map((r,i)=>{\r\n    const tier=r.tier||(r.ageHours!=null&&r.ageHours<=24?'fresh24h':'backup30d');\r\n    const tierBadge=tier==='fresh24h'\r\n      ?`<span style=\\\"font-size:.6rem;background:rgba(16,185,129,.15);color:#6ee7b7;border:1px solid rgba(16,185,129,.3);border-radius:999px;padding:2px 6px;font-weight:700;margin-left:5px\\\">&#x1F7E2; Fresh</span>`\r\n      :`<span style=\\\"font-size:.6rem;background:rgba(251,191,36,.12);color:#fbbf24;border:1px solid rgba(251,191,36,.25);border-radius:999px;padding:2px 6px;font-weight:700;margin-left:5px\\\">&#x1F554; Backup</span>`;\r\n    const hasAge=r.postedAt&&r.postedAt!=='';\r\n    const hasRaw=r.postedAtRaw&&r.postedAtRaw!=='';\r\n    const rawShort=hasRaw?r.postedAtRaw.slice(0,10):'';\r\n    const articleNote=r.dateIsArticleDate?` <span style=\"color:#6a8aaa;font-size:.65rem\">(article date)</span>`:'';\r\n    const dateLabel=hasAge\r\n      ?`<span class=\"dr-date\">${esc(r.postedAt)}${rawShort?' · '+esc(rawShort):''}${articleNote}</span>`\r\n      :(hasRaw\r\n        ?`<span class=\"dr-date\">${esc(rawShort)}${articleNote}</span>`\r\n        :`<span class=\"dr-date unknown\">Posting date: unknown</span>`);\r\n    const sourceBadge=r.sourceDomain||r.source\r\n      ?`<span class=\"dr-source-badge\">${esc(r.sourceDomain||r.source)}</span>`:'';\r\n    const companyLine=r.company\r\n      ?`<span class=\"dr-company\">${esc(r.company)}${r.location?' · '+esc(r.location):''}</span>`\r\n      :(r.location?`<span class=\"dr-company\">${esc(r.location)}</span>`:'');\r\n    return `<article class=\"discovery-result\">\r\n      <div style=\"min-width:0;flex:1\">\r\n        <h4>${esc(r.title||'Untitled vacancy')}${tierBadge}</h4>\r\n        <div class=\"dr-meta\">${companyLine}${sourceBadge}${dateLabel}</div>\r\n        <p>${esc((r.snippet||'').slice(0,220)||'Open the original source to verify vacancy details.')}</p>\r\n        <a href=\"${esc(r.url||r.applicationUrl||'#')}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(r.url||r.applicationUrl||'')}</a>\r\n      </div>\r\n      <div class=\"discovery-actions\">\r\n        <button class=\"btn-review\" type=\"button\" onclick=\"openReviewModal(${i})\">Review</button>\r\n        <button class=\"btn-reject\" type=\"button\" onclick=\"rejectDraft('${esc(r.id||'')}',${i})\">Reject</button>\r\n        <a class=\"btn-open-src\" href=\"${esc(r.applicationUrl||r.url||'#')}\" target=\"_blank\" rel=\"noopener noreferrer\">Open ↗</a>\r\n      </div>\r\n    </article>`;\r\n  }).join('');\r\n  window._discoveryResults=results;\r\n}\r\n\r\nfunction renderReviewQueue(drafts){\r\n  const section=$('reviewQueueSection');\r\n  const list=$('reviewQueueList');\r\n  const countEl=$('reviewQueueCount');\r\n  if(!drafts||!drafts.length){\r\n    countEl.textContent='0';\r\n    list.innerHTML='<p class=\"rq-empty\">No pending drafts in the review queue for this search.</p>';\r\n    section.classList.add('show');\r\n    return;\r\n  }\r\n  countEl.textContent=String(drafts.length);\r\n  list.innerHTML=drafts.map((r,i)=>{\r\n    const tier=r.tier||(r.ageHours!=null&&r.ageHours<=24?'fresh24h':'backup30d');\r\n    const tierBadge=tier==='fresh24h'?`<span style=\\\"font-size:.6rem;background:rgba(16,185,129,.15);color:#6ee7b7;border:1px solid rgba(16,185,129,.3);border-radius:999px;padding:2px 6px;font-weight:700;margin-left:5px\\\">&#x1F7E2; Fresh</span>`:`<span style=\\\"font-size:.6rem;background:rgba(251,191,36,.12);color:#fbbf24;border:1px solid rgba(251,191,36,.25);border-radius:999px;padding:2px 6px;font-weight:700;margin-left:5px\\\">&#x1F554; Backup</span>`;\r\n    const hasAge=r.postedAt&&r.postedAt!=='';\r\n    const hasRaw=r.postedAtRaw&&r.postedAtRaw!=='';\r\n    const rawShort=hasRaw?r.postedAtRaw.slice(0,10):'';\r\n    const dateLabel=hasAge?r.postedAt+(rawShort?' · '+rawShort:''):(rawShort||'Posting time: Unknown');\r\n    return `<article class=\"discovery-result\">\r\n      <div style=\"min-width:0;flex:1\">\r\n        <h4>${esc(r.title||'Untitled')}${tierBadge}\r\n          <span style=\"font-size:.62rem;background:rgba(251,191,36,.12);color:#fbbf24;border:1px solid rgba(251,191,36,.25);border-radius:999px;padding:2px 7px;margin-left:6px;font-weight:600\">Draft</span>\r\n        </h4>\r\n        <div class=\"dr-meta\">\r\n          ${r.company?`<span class=\"dr-company\">${esc(r.company)}${r.location?' · '+esc(r.location):''}</span>`:''}\r\n          ${r.sourceDomain||r.source?`<span class=\"dr-source-badge\">${esc(r.sourceDomain||r.source)}</span>`:''}\r\n          <span class=\"dr-date${hasAge||hasRaw?'':' unknown'}\">${esc(dateLabel)}</span>\r\n        </div>\r\n        <p>${esc((r.snippet||'').slice(0,180)||'No description available.')}</p>\r\n      </div>\r\n      <div class=\"discovery-actions\">\r\n        <button class=\"btn-review\" type=\"button\" onclick=\"openReviewModal(${i},true)\">Review</button>\r\n        <button class=\"btn-reject\" type=\"button\" onclick=\"rejectDraft('${esc(r.id||'')}',${i},true)\">Reject</button>\r\n        <a class=\"btn-open-src\" href=\"${esc(r.applicationUrl||r.url||'#')}\" target=\"_blank\" rel=\"noopener noreferrer\">Open ↗</a>\r\n      </div>\r\n    </article>`;\r\n  }).join('');\r\n  section.classList.add('show');\r\n}\r\n\r\n/* ── Review Modal ── */\r\nlet _reviewCurrentId=null;\r\n\r\nfunction openReviewModal(index,fromQueue){\r\n  const arr=fromQueue?(window._reviewQueueData||[]):(window._discoveryResults||[]);\r\n  const r=arr[index];\r\n  if(!r)return;\r\n  _reviewCurrentId=r.id||null;\r\n  $('rmTitle').textContent=r.title||'Untitled vacancy';\r\n  $('rmCompany').textContent=[r.company,r.location].filter(Boolean).join(' · ')||'—';\r\n  $('rmSource').textContent=r.source||r.sourceDomain||'—';\r\n  const _hasAge=r.postedAt&&r.postedAt!=='';\r\n  const _hasRaw=r.postedAtRaw&&r.postedAtRaw!=='';\r\n  const _rawShort=_hasRaw?r.postedAtRaw.slice(0,10):'';\r\n  const _articleNote=r.dateIsArticleDate?' (article date — not necessarily the original job posting date)':'';\r\n  const _postedText=_hasAge\r\n    ?r.postedAt+(_rawShort?' · '+_rawShort:'')+_articleNote\r\n    :(_rawShort?_rawShort+_articleNote:'Unknown — posting date not confirmed by source');\r\n  const _tier=r.tier||(r.ageHours!=null&&r.ageHours<=24?'fresh24h':'backup30d');\r\n  $('rmPosted').textContent=_postedText+' [ '+(_tier==='fresh24h'?'Fresh <24h':'Backup 1–30d')+']';\r\n  $('rmPosted').className='rm-value'+(_hasAge||_hasRaw?'':' dr-date unknown');\r\n  const applyUrl=r.applicationUrl||r.url||'';\r\n  $('rmUrl').href=applyUrl;\r\n  $('rmUrl').textContent=applyUrl||'—';\r\n  $('rmOpenSrc').href=applyUrl;\r\n  $('rmDescription').textContent=r.snippet||r.description||'No description available.';\r\n  $('reviewModalOverlay').classList.add('show');\r\n  document.body.style.overflow='hidden';\r\n}\r\n\r\nfunction closeReviewModal(){\r\n  $('reviewModalOverlay').classList.remove('show');\r\n  document.body.style.overflow='';\r\n  _reviewCurrentId=null;\r\n}\r\n\r\nasync function rejectDraft(id,index,fromQueue){\r\n  if(!id){discoveryStatus('Cannot reject: draft ID missing.','error');return;}\r\n  if(!confirm('Delete this draft job? This cannot be undone.'))return;\r\n  try{\r\n    await api('/api/jobs',{method:'DELETE',key:adminKey,body:JSON.stringify({id})});\r\n    /* Remove card from UI */\r\n    const arr=fromQueue?(window._reviewQueueData||[]):(window._discoveryResults||[]);\r\n    if(arr[index])arr.splice(index,1);\r\n    if(fromQueue){renderReviewQueue(window._reviewQueueData||[]);}\r\n    else{renderDiscoveryResults(window._discoveryResults||[]);}\r\n    $('reviewQueueCount').textContent=String((window._reviewQueueData||[]).length);\r\n    discoveryStatus('Draft deleted.','show');\r\n  }catch(e){\r\n    discoveryStatus(`Delete failed: ${e.message}`,'error');\r\n  }\r\n}\r\n\r\nasync function publishReviewedDraft(){\r\n  if(!_reviewCurrentId){discoveryStatus('Cannot publish: draft ID missing.','error');closeReviewModal();return;}\r\n  try{\r\n    await api('/api/jobs',{method:'PATCH',key:adminKey,body:JSON.stringify({id:_reviewCurrentId,published:true,status:'Active',review_state:'Published',verification_status:'Verified'})});\r\n    closeReviewModal();\r\n    /* Refresh jobs list */\r\n    const resp=await authedApi(`/api/jobs?page=${ccJobsPage}&limit=50&auth=1`,{});\r\n    jobs=(resp.jobs||[]);\r\n    loadAdminJobs();\r\n    /* Remove from queues */\r\n    [window._discoveryResults,window._reviewQueueData].forEach(arr=>{\r\n      if(!Array.isArray(arr))return;\r\n      const idx=arr.findIndex(r=>r.id===_reviewCurrentId);\r\n      if(idx!==-1)arr.splice(idx,1);\r\n    });\r\n    renderDiscoveryResults(window._discoveryResults||[]);\r\n    renderReviewQueue(window._reviewQueueData||[]);\r\n    discoveryStatus('Job published and is now live.','show');\r\n  }catch(e){\r\n    discoveryStatus(`Publish failed: ${e.message}`,'error');\r\n  }\r\n}\r\n\r\nasync function discoverJobs(){\r\n  const btn=$('discoverySearchBtn');\r\n  const q=$('discoveryQuery').value.trim()||'civil engineering jobs India';\r\n  const location=$('discoveryLocation').value.trim();\r\n  const type=$('discoveryType').value;\r\n  btn.disabled=true;\r\n  const old=btn.textContent; btn.textContent='Searching…';\r\n  $('sourceHealthPanel').classList.remove('show');\r\n  $('discoverySummary').classList.remove('show');\r\n  $('reviewQueueSection').classList.remove('show');\r\n  $('setupGuidePanel').classList.remove('show');\r\n  discoveryStatus('Searching sources in parallel…','show');\r\n  try{\r\n    const data=await api('/api/jobs?discovery=1',{\r\n      method:'POST',\r\n      key:adminKey,\r\n      body:JSON.stringify({q,location,type,limit:20})\r\n    });\r\n    const results=data.results||[];\r\n    window._discoveryResults=results;\r\n    window._reviewQueueData=[...results]; /* same data, separate reference for queue */\r\n    renderSourceHealth(data.sourceStats||{});\r\n    renderDiscoverySummary(data);\r\n    renderDiscoveryResults(results);\r\n    renderReviewQueue(results);\r\n    const newCount=Number(data.count||0);\r\n    const totalFound=Object.values(data.sourceStats||{}).reduce((s,v)=>s+(v.ok?Number(v.items||0):0),0);\r\n    if(newCount===0 && totalFound===0){\r\n      /* All sources returned zero — show the setup guide again */\r\n      $('setupGuidePanel').classList.add('show');\r\n    }\r\n    discoveryStatus(\r\n      newCount>0\r\n        ?`${newCount} new draft${newCount===1?'':'s'} added — review them below before publishing.`\r\n        :totalFound>0\r\n          ?`Search complete. ${totalFound} listings found but all were duplicates already in CivilCareer or outside the freshness window.`\r\n          :'Search complete. No jobs found. See the setup guide above to connect an India job source.',\r\n      newCount>0?'show':'show'\r\n    );\r\n  }catch(e){\r\n    renderDiscoveryResults([]);\r\n    discoveryStatus(e.message||'Web discovery failed.','error');\r\n  }finally{\r\n    btn.disabled=false; btn.textContent=old;\r\n  }\r\n}\r\n\r\nasync function discoverExtract(index){\r\n  const item=(window._discoveryResults||[])[index];\r\n  if(!item?.url)return;\r\n  discoveryStatus('Fetching the original vacancy page and extracting structured fields…','show');\r\n  try{\r\n    const data=await api('/api/extract',{\r\n      method:'POST',\r\n      key:adminKey,\r\n      body:JSON.stringify({url:item.url,text:''})\r\n    });\r\n    const x={...(data.extracted||data.job||{})};\r\n    x.source_url=x.source_url||item.url;\r\n    x.status='Active';\r\n    x.last_verified=new Date().toISOString().slice(0,10);\r\n    discoveryStatus(data.warning||`Extraction complete using ${data.source||'free AI/local fallback'}. Verify every field before saving.` ,'show');\r\n    jobEditor(x);\r\n  }catch(e){\r\n    discoveryStatus(`Could not extract this page: ${e.message}. You can still open the source and paste the vacancy text into the Jobs importer.`,'error');\r\n  }\r\n}\r\n\r\n$('discoverySearchBtn').onclick=discoverJobs;\r\n$('discoveryQuery').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();discoverJobs()}};\r\n$('discoveryLocation').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();discoverJobs()}};\r\n\r\n/* Review modal wiring */\r\n$('rmClose').onclick=closeReviewModal;\r\n$('reviewModalOverlay').onclick=e=>{if(e.target===$('reviewModalOverlay'))closeReviewModal();};\r\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape')closeReviewModal();});\r\n$('rmPublish').onclick=publishReviewedDraft;\r\n$('rmReject').onclick=()=>{\r\n  if(!_reviewCurrentId)return;\r\n  /* find index in both arrays */\r\n  const arr=window._reviewQueueData||[];\r\n  const idx=arr.findIndex(r=>r.id===_reviewCurrentId);\r\n  closeReviewModal();\r\n  if(idx!==-1)rejectDraft(_reviewCurrentId,idx,true);\r\n};\r\n$('rmEdit').onclick=()=>{\r\n  if(!_reviewCurrentId)return;\r\n  const allJobs=Array.isArray(jobs)?jobs:[];\r\n  const found=allJobs.find(j=>j.id===_reviewCurrentId);\r\n  closeReviewModal();\r\n  if(found)jobEditor(found);\r\n  else discoveryStatus('Job not found in current jobs list. Reload the Jobs tab.','error');\r\n};\r\n\r\n/* =====================================================\r\n   AGENT REACH INBOX — pending review of ingested items\r\n   ===================================================== */\r\n\r\nlet agentReachItems=[];\r\n\r\nasync function loadAgentReach(){\r\n\r\n  try{\r\n\r\n    const [jr,mr]=await Promise.all([\r\n      authedApi('/api/jobs?limit=100&auth=1',{}),\r\n      authedApi('/api/materials?auth=1',{})\r\n    ]);\r\n\r\n    jobs=jr.jobs||jobs;\r\n\r\n    materials=mr.materials||materials;\r\n\r\n    agentReachItems=[\r\n      ...jobs\r\n        .filter(j=>j.ingestion_source==='agent_reach')\r\n        .map(j=>({...j,_arType:'job'})),\r\n      ...materials\r\n        .filter(m=>m.ingestion_source==='agent_reach')\r\n        .map(m=>({...m,_arType:'material'}))\r\n    ];\r\n\r\n    renderAgentReachInbox();\r\n\r\n  }catch(e){\r\n\r\n    $('agentReachInbox').innerHTML=\r\n      `<p style=\"color:#fca5a5;padding:1rem\">Could not load the inbox: ${esc(e.message)}</p>`;\r\n  }\r\n}\r\n\r\nfunction renderAgentReachInbox(){\r\n\r\n  const showRejected=$('arShowRejected')&&$('arShowRejected').checked;\r\n\r\n  const list=agentReachItems\r\n    .filter(x=>showRejected||x.review_state!=='Rejected')\r\n    .sort((a,b)=>String(b.ingested_at||b.created_at||'').localeCompare(String(a.ingested_at||a.created_at||'')));\r\n\r\n  const pending=agentReachItems.filter(x=>x.review_state==='Pending Review').length;\r\n\r\n  $('agentReachInbox').innerHTML=`\r\n\r\n    <p style=\"color:#cbd5e1;font-size:.8rem;margin:0 0 10px\">\r\n      <strong>${pending}</strong> pending &middot;\r\n      <strong>${agentReachItems.filter(x=>x.review_state==='Published').length}</strong> published &middot;\r\n      <strong>${agentReachItems.filter(x=>x.review_state==='Rejected').length}</strong> rejected\r\n    </p>`\r\n\r\n    +(list.length\r\n\r\n    ?list.map(x=>{\r\n\r\n      const isJob=x._arType==='job';\r\n\r\n      const badge=x.review_state==='Published'\r\n        ?'<span class=\"status-badge published\">Published</span>'\r\n        :x.review_state==='Rejected'\r\n          ?'<span class=\"status-badge expired\">Rejected</span>'\r\n          :'<span class=\"ar-badge\">Pending Review</span>';\r\n\r\n      const meta=isJob\r\n        ?[x.company,x.location,x.salary].filter(Boolean).join(' · ')\r\n        :[x.category,x.author].filter(Boolean).join(' · ');\r\n\r\n      const link=isJob?(x.application_url||x.source_url):x.file_url;\r\n\r\n      const srcName=x.source_name||'';\r\n\r\n      const when=String(x.ingested_at||x.created_at||'').slice(0,10);\r\n\r\n      return `\r\n\r\n      <div class=\"ar-item ${isJob?'ar-job':'ar-material'} ${x.review_state==='Rejected'?'ar-rejected':''}\">\r\n\r\n        <div style=\"min-width:0\">\r\n\r\n          <h4>\r\n            ${esc(x.role||x.title_en||'Untitled')}\r\n            ${badge}\r\n            <span class=\"ar-badge\" style=\"background:rgba(96,165,250,.12);color:#93c5fd;border-color:rgba(96,165,250,.25)\">${isJob?'Job':'Resource'}</span>\r\n          </h4>\r\n\r\n          <p>${esc(meta||'—')} · ingested ${esc(when)}${srcName?' · from '+esc(srcName):''}</p>\r\n\r\n          ${link?`<a href=\"${esc(link)}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(link)}</a>`:''}\r\n\r\n        </div>\r\n\r\n        <div class=\"ar-actions\">\r\n\r\n          <button class=\"btn-review\" onclick=\"openAgentReachModal('${x.id}')\">Review</button>\r\n\r\n          <button onclick=\"editAgentReachItem('${x.id}')\">Edit</button>\r\n\r\n          ${x.review_state!=='Published'\r\n            ?`<button class=\"btn-publish\" onclick=\"publishAgentReachItem('${x.id}')\">Publish</button>`\r\n            :''}\r\n\r\n          ${x.review_state!=='Rejected'\r\n            ?`<button class=\"btn-reject\" onclick=\"rejectAgentReachItem('${x.id}')\">Reject</button>`\r\n            :`<button class=\"btn-delete\" onclick=\"rejectAgentReachItem('${x.id}',true)\">Delete</button>`}\r\n\r\n        </div>\r\n\r\n      </div>`;\r\n\r\n    }).join('')\r\n\r\n    :'<p style=\"color:#6a8aaa;padding:1rem\">Inbox empty. Nothing has been ingested from Agent Reach yet.</p>');\r\n}\r\n\r\nfunction agentReachFind(id){\r\n\r\n  return agentReachItems.find(x=>x.id===id);\r\n}\r\n\r\nfunction openAgentReachModal(id){\r\n\r\n  const x=agentReachFind(id);\r\n\r\n  if(!x)return;\r\n\r\n  _reviewAgentId=id;\r\n\r\n  const isJob=x._arType==='job';\r\n\r\n  $('arTitle').textContent=x.role||x.title_en||'Untitled';\r\n\r\n  $('arCompany').textContent=(isJob?x.company:x.author)||'—';\r\n\r\n  const rows=isJob?[\r\n    ['Location',x.location],\r\n    ['Employment type',x.employment_type],\r\n    ['Experience',x.experience_level],\r\n    ['Skills',x.skills],\r\n    ['Salary',x.salary],\r\n    ['Application URL',x.application_url],\r\n    ['Source URL',x.source_url],\r\n    ['Source name',x.source_name],\r\n    ['Published date',x.date_posted],\r\n    ['Deadline',x.deadline],\r\n    ['Ingested',x.ingested_at],\r\n    ['Review state',x.review_state]\r\n  ]:[\r\n    ['URL',x.file_url],\r\n    ['Source page',x.source_url],\r\n    ['Source name',x.source_name],\r\n    ['Category',x.category],\r\n    ['Content type',(x.agent_reach_meta||{}).content_type],\r\n    ['Description',x.description_en],\r\n    ['Ingested',x.ingested_at],\r\n    ['Review state',x.review_state]\r\n  ];\r\n\r\n  $('arFields').innerHTML=rows\r\n    .filter(r=>r[1]!=null&&r[1]!=='')\r\n    .map(r=>`\r\n      <div class=\"rm-field\">\r\n        <span class=\"rm-label\">${r[0]}</span>\r\n        <span class=\"rm-value\" style=\"white-space:pre-wrap\">${esc(r[1])}</span>\r\n      </div>`)\r\n    .join('')\r\n    ||'<p class=\"rm-value\">No extra fields were supplied.</p>';\r\n\r\n  const link=isJob?(x.application_url||x.source_url):x.file_url;\r\n\r\n  $('arOpenSrc').href=link||'#';\r\n\r\n  $('agentReachModalOverlay').classList.add('show');\r\n\r\n  document.body.style.overflow='hidden';\r\n}\r\n\r\nfunction closeAgentReachModal(){\r\n\r\n  $('agentReachModalOverlay').classList.remove('show');\r\n\r\n  document.body.style.overflow='';\r\n}\r\n\r\nfunction editAgentReachItem(id){\r\n\r\n  const x=agentReachFind(id);\r\n\r\n  if(!x)return;\r\n\r\n  closeAgentReachModal();\r\n\r\n  if(x._arType==='job'){\r\n\r\n    /* _keepUnpublished makes the job editor save without publishing; the\r\n       item stays in the inbox until it is explicitly published. */\r\n\r\n    jobEditor({...x,_keepUnpublished:true});\r\n\r\n  }else{\r\n\r\n    materialEditor(x);\r\n  }\r\n}\r\n\r\nasync function publishAgentReachItem(id){\r\n\r\n  const x=agentReachFind(id);\r\n\r\n  if(!x)return;\r\n\r\n  try{\r\n\r\n    if(x._arType==='job'){\r\n\r\n      await api('/api/jobs',{method:'PATCH',key:adminKey,body:JSON.stringify({id,published:true,status:'Active',review_state:'Published',verification_status:'Verified',published_at:new Date().toISOString()})});\r\n\r\n      const j=jobs.find(z=>z.id===id);\r\n\r\n      if(j){j.published=true;j.review_state='Published';}\r\n\r\n    }else{\r\n\r\n      await api('/api/materials',{method:'PATCH',key:adminKey,body:JSON.stringify({id,published:true,review_state:'Published'})});\r\n\r\n      const m=materials.find(z=>z.id===id);\r\n\r\n      if(m){m.published=true;m.review_state='Published';}\r\n\r\n    }\r\n\r\n    x.review_state='Published';\r\n\r\n    renderAgentReachInbox();\r\n\r\n    closeAgentReachModal();\r\n\r\n    toast('Published ✓');\r\n\r\n  }catch(e){\r\n\r\n    toast(`Publish failed: ${e.message}`);\r\n  }\r\n}\r\n\r\nasync function rejectAgentReachItem(id,deletePermanently){\r\n\r\n  if(!confirm(deletePermanently?'Delete permanently? This cannot be undone.':'Reject this item? It stays in the database but is marked Rejected and never appears publicly.'))return;\r\n\r\n  try{\r\n\r\n    if(deletePermanently){\r\n\r\n      const x=agentReachFind(id);\r\n\r\n      await api(x&&x._arType==='material'?'/api/materials':'/api/jobs',{method:'DELETE',key:adminKey,body:JSON.stringify({id})});\r\n\r\n      agentReachItems=agentReachItems.filter(z=>z.id!==id);\r\n\r\n      jobs=jobs.filter(z=>z.id!==id);\r\n\r\n      materials=materials.filter(z=>z.id!==id);\r\n\r\n    }else{\r\n\r\n      const x=agentReachFind(id);\r\n\r\n      const isJob=x&&x._arType==='job';\r\n\r\n      await api(isJob?'/api/jobs':'/api/materials',{method:'PATCH',key:adminKey,body:JSON.stringify({id,published:false,review_state:'Rejected'})});\r\n\r\n      if(x){x.review_state='Rejected';x.published=false;}\r\n\r\n      const cache=isJob?jobs:materials;\r\n\r\n      const row=cache.find(z=>z.id===id);\r\n\r\n      if(row){row.review_state='Rejected';row.published=false;}\r\n\r\n    }\r\n\r\n    renderAgentReachInbox();\r\n\r\n    closeAgentReachModal();\r\n\r\n    toast(deletePermanently?'Deleted.':'Marked Rejected.');\r\n\r\n  }catch(e){\r\n\r\n    toast(`Reject failed: ${e.message}`);\r\n  }\r\n}\r\n\r\n$('arClose').onclick=closeAgentReachModal;\r\n\r\n$('agentReachModalOverlay').onclick=e=>{if(e.target===$('agentReachModalOverlay'))closeAgentReachModal();};\r\n\r\n$('arPublish').onclick=()=>{_reviewAgentId&&publishAgentReachItem(_reviewAgentId)};\r\n\r\n$('arEdit').onclick=()=>{_reviewAgentId&&editAgentReachItem(_reviewAgentId)};\r\n\r\n$('arReject').onclick=()=>{_reviewAgentId&&rejectAgentReachItem(_reviewAgentId)};\r\n\r\nlet _reviewAgentId=null;\r\n\r\n/* ════════════════════════════════════════════════\r\n   EXAM TRACKER (Feature 2)\r\n   Inline-editable rows → PUT /api/exam-tracker.\r\n   Status → application_open auto-posts to Telegram (server side).\r\n   ════════════════════════════════════════════════ */\r\n\r\nlet examTrackerRows = [];\r\n\r\nconst XT_STATUSES = [\r\n  ['upcoming','Awaited'],\r\n  ['notification_out','Notification Out'],\r\n  ['application_open','Applications Open'],\r\n  ['application_closed','Applications Closed'],\r\n  ['admit_card','Admit Card'],\r\n  ['exam_scheduled','Exam Scheduled'],\r\n  ['result_out','Result Out'],\r\n];\r\n\r\nconst XT_CATEGORIES = ['GATE','SSC','RRB','UPSC','STATE_PSC','PSU'];\r\n\r\nfunction setExamTrackerStatus(msg, type='') {\r\n  const el = $('examTrackerStatus');\r\n  if (!el) return;\r\n  el.textContent = msg || '';\r\n  el.className = `import-status show${type ? ' ' + type : ''}`;\r\n}\r\n\r\nasync function loadExamTracker() {\r\n  try {\r\n    const d = await api('/api/exam-tracker', { key: adminKey });\r\n    examTrackerRows = d.exams || [];\r\n    renderExamTracker();\r\n  } catch (e) {\r\n    $('adminExamTracker').innerHTML =\r\n      `<p style=\"color:#fca5a5;padding:1rem\">Could not load the exam tracker: ${esc(e.message)}</p>` +\r\n      (/missing|not exist|PGRST205/i.test(e.message || '')\r\n        ? '<p style=\"color:#fbbf24;font-size:.82rem;padding:0 1rem\">Run <b>supabase-v20-exam-tracker.sql</b> in the Supabase SQL Editor, then press Refresh.</p>'\r\n        : '');\r\n  }\r\n}\r\n\r\nfunction xtStatusBadge(status) {\r\n  const s = String(status || 'upcoming');\r\n  const color = {\r\n    application_open:'#6ee7b7', result_out:'#7fd8c8', admit_card:'#c4b5fd',\r\n    exam_scheduled:'#fbbf24', application_closed:'#fbbf24', notification_out:'#93c5fd',\r\n    upcoming:'#94a3b8',\r\n  }[s] || '#94a3b8';\r\n  const label = (XT_STATUSES.find(x => x[0] === s) || ['', s])[1];\r\n  return `<span class=\"status-badge\" style=\"background:rgba(255,255,255,.06);color:${color};border:1px solid ${color}44\">${esc(label)}</span>`;\r\n}\r\n\r\nfunction renderExamTracker() {\r\n  const rows = examTrackerRows;\r\n  if (!rows.length) {\r\n    $('adminExamTracker').innerHTML = '<p style=\"color:#6a8aaa;padding:1rem\">No exams yet. Add one with “+ Add new exam”.</p>';\r\n    return;\r\n  }\r\n  const opts = (list, current) => list.map(v =>\r\n    `<option value=\"${esc(v[0] ?? v)}\" ${String(current) === String(v[0] ?? v) ? 'selected' : ''}>${esc(v[1] ?? v)}</option>`\r\n  ).join('');\r\n\r\n  $('adminExamTracker').innerHTML = rows.map(x => `\r\n    <div class=\"list-item\" style=\"align-items:flex-start\" data-row=\"${esc(x.id)}\">\r\n\r\n      <div style=\"min-width:0;flex:1\">\r\n        <h4>\r\n          ${esc(x.name || 'Untitled exam')}\r\n          ${xtStatusBadge(x.status)}\r\n          ${x.is_active === false ? '<span class=\"status-badge expired\">Hidden</span>' : ''}\r\n        </h4>\r\n        <p>\r\n          ${esc(x.authority || '—')}\r\n          · ${esc((XT_CATEGORIES.includes(x.category) ? x.category : '—'))}\r\n          ${x.application_end ? ` · Apply by ${esc(x.application_end)}` : ''}\r\n          ${x.vacancy_count ? ` · ~${Number(x.vacancy_count).toLocaleString('en-IN')} vacancies` : ''}\r\n        </p>\r\n\r\n        <div class=\"field-grid\" style=\"margin-top:10px;grid-template-columns:repeat(auto-fit,minmax(150px,1fr))\">\r\n          <label>Status\r\n            <select data-f=\"status\" data-id=\"${esc(x.id)}\">${opts(XT_STATUSES, x.status)}</select>\r\n          </label>\r\n          <label>Notification\r\n            <input type=\"date\" data-f=\"notification_date\" data-id=\"${esc(x.id)}\" value=\"${esc(x.notification_date || '')}\">\r\n          </label>\r\n          <label>Applications start\r\n            <input type=\"date\" data-f=\"application_start\" data-id=\"${esc(x.id)}\" value=\"${esc(x.application_start || '')}\">\r\n          </label>\r\n          <label>Applications end\r\n            <input type=\"date\" data-f=\"application_end\" data-id=\"${esc(x.id)}\" value=\"${esc(x.application_end || '')}\">\r\n          </label>\r\n          <label>Exam date (text ok)\r\n            <input data-f=\"exam_date\" data-id=\"${esc(x.id)}\" value=\"${val(x.exam_date)}\" placeholder=\"Feb 1-16, 2026\">\r\n          </label>\r\n          <label>Result date\r\n            <input type=\"date\" data-f=\"result_date\" data-id=\"${esc(x.id)}\" value=\"${esc(x.result_date || '')}\">\r\n          </label>\r\n          <label>Vacancies\r\n            <input type=\"number\" min=\"0\" data-f=\"vacancy_count\" data-id=\"${esc(x.id)}\" value=\"${val(x.vacancy_count)}\">\r\n          </label>\r\n          <label>Official URL\r\n            <input type=\"url\" data-f=\"official_url\" data-id=\"${esc(x.id)}\" value=\"${val(x.official_url)}\" placeholder=\"https://…\">\r\n          </label>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"mini-actions\" style=\"flex-direction:column;align-items:stretch\">\r\n        <button class=\"btn-publish\" data-save=\"${esc(x.id)}\">Save</button>\r\n        <button onclick=\"examTrackerEditor(examTrackerRows.find(z => z.id === '${esc(x.id)}'))\">Edit all fields</button>\r\n        <button class=\"btn-delete\" onclick=\"deleteExamTracker('${esc(x.id)}')\">Delete</button>\r\n      </div>\r\n\r\n    </div>`).join('');\r\n\r\n  $('adminExamTracker').querySelectorAll('[data-save]').forEach(b => {\r\n    b.onclick = () => saveExamTrackerRow(b.getAttribute('data-save'));\r\n  });\r\n}\r\n\r\nasync function saveExamTrackerRow(id) {\r\n  const row = examTrackerRows.find(z => z.id === id);\r\n  if (!row) return;\r\n  const container = $(`adminExamTracker`).querySelector(`[data-row=\"${id}\"]`);\r\n  if (!container) return;\r\n\r\n  const payload = { id };\r\n  container.querySelectorAll('[data-f]').forEach(el => {\r\n    payload[el.getAttribute('data-f')] = el.value;\r\n  });\r\n\r\n  const btn = container.querySelector('[data-save]');\r\n  btn.disabled = true; btn.textContent = 'Saving…';\r\n  try {\r\n    const d = await api('/api/exam-tracker', {\r\n      method: 'PUT',\r\n      key: adminKey,\r\n      body: JSON.stringify(payload),\r\n    });\r\n    if (d.exam) Object.assign(row, d.exam);\r\n    const tg = d.telegram || {};\r\n    setExamTrackerStatus(\r\n      tg.sent\r\n        ? 'Saved ✓ — Applications Open announced via the Social Engine 📢'\r\n        : tg.queued\r\n          ? `Saved ✓ — announcement queued in the Social tab (suggestion #${tg.suggestion_id})`\r\n          : tg.reason\r\n            ? `Saved ✓ (announcement: ${tg.reason})`\r\n            : 'Saved ✓',\r\n      'success'\r\n    );\r\n    toast('Exam saved.');\r\n    renderExamTracker();\r\n  } catch (e) {\r\n    setExamTrackerStatus(`Save failed: ${e.message}`, 'error');\r\n  } finally {\r\n    btn.disabled = false; btn.textContent = 'Save';\r\n  }\r\n}\r\n\r\nasync function deleteExamTracker(id) {\r\n  if (!confirm('Delete this exam from the tracker? This cannot be undone.')) return;\r\n  try {\r\n    await api('/api/exam-tracker', { method: 'DELETE', key: adminKey, body: JSON.stringify({ id }) });\r\n    examTrackerRows = examTrackerRows.filter(z => z.id !== id);\r\n    renderExamTracker();\r\n    toast('Exam deleted.');\r\n  } catch (e) {\r\n    toast(e.message);\r\n  }\r\n}\r\n\r\nfunction examTrackerEditor(x = {}) {\r\n  $('editorTitle').textContent = x.id ? 'Edit exam (tracker)' : 'Add exam (tracker)';\r\n  $('editorBody').innerHTML = `\r\n<form id=\"xtEdit\">\r\n<div class=\"field-grid\">\r\n\r\n<label class=\"wide\">\r\nName *\r\n<input name=\"name\" value=\"${val(x.name)}\" required placeholder=\"e.g. SSC Junior Engineer Civil\">\r\n</label>\r\n\r\n<label>\r\nShort name\r\n<input name=\"short_name\" value=\"${val(x.short_name)}\" placeholder=\"e.g. SSC JE\">\r\n</label>\r\n\r\n<label>\r\nAuthority\r\n<input name=\"authority\" value=\"${val(x.authority)}\" placeholder=\"e.g. Staff Selection Commission\">\r\n</label>\r\n\r\n<label>\r\nCategory\r\n<select name=\"category\">\r\n${XT_CATEGORIES.map(c => `<option value=\"${c}\" ${x.category === c ? 'selected' : ''}>${c === 'STATE_PSC' ? 'State PSC' : c}</option>`).join('')}\r\n</select>\r\n</label>\r\n\r\n<label>\r\nStatus\r\n<select name=\"status\">\r\n${XT_STATUSES.map(([v, l]) => `<option value=\"${v}\" ${(x.status || 'upcoming') === v ? 'selected' : ''}>${l}</option>`).join('')}\r\n</select>\r\n</label>\r\n\r\n<label>\r\nNotification date\r\n<input type=\"date\" name=\"notification_date\" value=\"${val(x.notification_date)}\">\r\n</label>\r\n\r\n<label>\r\nApplications start\r\n<input type=\"date\" name=\"application_start\" value=\"${val(x.application_start)}\">\r\n</label>\r\n\r\n<label>\r\nApplications end\r\n<input type=\"date\" name=\"application_end\" value=\"${val(x.application_end)}\">\r\n</label>\r\n\r\n<label>\r\nExam date (text allowed)\r\n<input name=\"exam_date\" value=\"${val(x.exam_date)}\" placeholder=\"Feb 1-16, 2026\">\r\n</label>\r\n\r\n<label>\r\nResult date\r\n<input type=\"date\" name=\"result_date\" value=\"${val(x.result_date)}\">\r\n</label>\r\n\r\n<label>\r\nVacancies\r\n<input type=\"number\" min=\"0\" name=\"vacancy_count\" value=\"${val(x.vacancy_count)}\">\r\n</label>\r\n\r\n<label>\r\nApplication fee\r\n<input name=\"exam_fee\" value=\"${val(x.exam_fee)}\" placeholder=\"e.g. ₹100\">\r\n</label>\r\n\r\n<label>\r\nAge limit\r\n<input name=\"age_limit\" value=\"${val(x.age_limit)}\" placeholder=\"e.g. 18-32\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nOfficial URL\r\n<input type=\"url\" name=\"official_url\" value=\"${val(x.official_url)}\" placeholder=\"https://ssc.gov.in\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nEligibility summary\r\n<textarea name=\"eligibility_summary\">${val(x.eligibility_summary)}</textarea>\r\n</label>\r\n\r\n<label class=\"wide\">\r\nQualification\r\n<input name=\"qualification\" value=\"${val(x.qualification)}\" placeholder=\"e.g. Diploma or Degree in Civil Engineering\">\r\n</label>\r\n\r\n<label class=\"wide\">\r\nInternal notes (never public)\r\n<textarea name=\"notes\">${val(x.notes)}</textarea>\r\n</label>\r\n\r\n<label class=\"check\" style=\"display:flex;align-items:center;gap:8px\">\r\n<input type=\"checkbox\" name=\"is_active\" ${x.is_active !== false ? 'checked' : 'style=\"accent-color:#c9973c\"'}> Visible on the public exam tracker page\r\n</label>\r\n\r\n<button type=\"submit\" class=\"btn-save\">${x.id ? 'Save Exam' : 'Create Exam'}</button>\r\n<div class=\"save-status\" id=\"xtSaveStatus\"></div>\r\n\r\n</div>\r\n</form>`;\r\n\r\n  $('editorDialog').showModal();\r\n\r\n  $('xtEdit').onsubmit = async e => {\r\n    e.preventDefault();\r\n    const d = formObject(e.target);\r\n    d.is_active = e.target.elements['is_active'].checked;\r\n    if (x.id) d.id = x.id;\r\n    const st = $('xtSaveStatus');\r\n    st.className = 'save-status show';\r\n    st.textContent = 'Saving…';\r\n    try {\r\n      await api('/api/exam-tracker', {\r\n        method: x.id ? 'PUT' : 'POST',\r\n        key: adminKey,\r\n        body: JSON.stringify(d),\r\n      });\r\n      st.className = 'save-status show success';\r\n      st.textContent = 'Saved ✓';\r\n      toast('Exam tracker saved.');\r\n      await loadExamTracker();\r\n      setTimeout(() => $('editorDialog').close(), 700);\r\n    } catch (err) {\r\n      st.className = 'save-status show error';\r\n      st.textContent = err.message;\r\n    }\r\n  };\r\n}\r\n\r\n/* ════════════════════════════════════════════════\r\n   SOCIAL CONTENT ENGINE (Phase 2 — v27 tables)\r\n   Suggestions queue, send ledger, connections and\r\n   engine settings. Every platform send is approved,\r\n   Truth-Locked and capped by the engine first.\r\n   ════════════════════════════════════════════════ */\r\n\r\nlet socialRows = [];\r\nlet socialFilter = '';\r\nlet socialExpanded = null;\r\n\r\nfunction setSocialStatus(msg, type='') {\r\n  const el = $('socialStatus');\r\n  if (!el) return;\r\n  el.textContent = msg || '';\r\n  el.className = `import-status show${type ? ' ' + type : ''}`;\r\n}\r\n\r\nconst SOCIAL_BADGES = {\r\n  suggestion: {\r\n    pending:      ['⏳ Pending', '#c9973c'],\r\n    approved:     ['✅ Approved', '#6ee7b7'],\r\n    publishing:   ['📤 Publishing', '#7dd3fc'],\r\n    published:    ['📣 Published', '#4ade80'],\r\n    partial:      ['🧩 Partial', '#fbbf24'],\r\n    rejected:     ['🚫 Rejected', '#f87171'],\r\n    archived:     ['🗄️ Archived', '#94a3b8'],\r\n  },\r\n  truth: {\r\n    locked:     ['🔒 Truth locked', '#6ee7b7'],\r\n    stale:      ['⚠️ Source changed', '#f87171'],\r\n    unverified: ['❓ Unverified', '#c9973c'],\r\n  },\r\n  ledger: {\r\n    pending:           ['⏳ Pending', '#c9973c'],\r\n    publishing:        ['📤 Publishing', '#7dd3fc'],\r\n    sent:              ['✅ Sent', '#4ade80'],\r\n    failed:            ['❌ Failed', '#f87171'],\r\n    uncertain:         ['❓ Uncertain', '#fbbf24'],\r\n    cancelled:         ['🚫 Cancelled', '#94a3b8'],\r\n    needs_second_step: ['🔁 Second step', '#7dd3fc'],\r\n    expired:           ['⏰ Expired', '#94a3b8'],\r\n  },\r\n};\r\n\r\nfunction socialBadge(kind, key) {\r\n  const b = (SOCIAL_BADGES[kind] || {})[key] || ['•', '#94a3b8'];\r\n  return `<span style=\"display:inline-block;padding:1px 8px;border-radius:999px;font-size:.72rem;background:${b[1]}1f;color:${b[1]};border:1px solid ${b[1]}55;white-space:nowrap\">${b[0]}</span>`;\r\n}\r\n\r\nconst socialWhen = iso => {\r\n  const d = new Date(iso);\r\n  return Number.isNaN(d.getTime()) ? (iso || '—') : d.toLocaleString('en-IN', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });\r\n};\r\n\r\nfunction socialSetFilter(f) {\r\n  socialFilter = f;\r\n  renderSocialQueue();\r\n}\r\n\r\nasync function loadSocial() {\r\n  try {\r\n    const d = await api('/api/social', { key: adminKey });\r\n    socialRows = d.suggestions || [];\r\n    renderSocialSettings(d.settings || {});\r\n    renderSocialConnections(d.connections || []);\r\n    renderSocialQueue();\r\n  } catch (e) {\r\n    const el = $('socialQueue');\r\n    if (el) el.innerHTML = `<p style=\"color:#fca5a5;padding:1rem\">Could not load the Social queue: ${esc(e.message)}</p>`;\r\n  }\r\n}\r\n\r\n/* ── settings ─────────────────────────────── */\r\n\r\nfunction renderSocialSettings(s) {\r\n  const el = $('socialSettings');\r\n  if (!el) return;\r\n  const caps = s.per_platform_daily_caps || {};\r\n  el.innerHTML = `\r\n  <form id=\"socialSettingsForm\" class=\"import-box\" style=\"padding:14px\">\r\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px;align-items:start\">\r\n      <label style=\"display:flex;gap:8px;align-items:center;font-size:.85rem;color:#e2e8f0\">\r\n        <input type=\"checkbox\" id=\"ssKill\" ${s.kill_switch ? 'checked' : ''}>\r\n        <span>Kill switch<br><span style=\"color:#6a8aaa;font-size:.72rem\">blocks all publishing instantly</span></span>\r\n      </label>\r\n      <label style=\"display:flex;gap:8px;align-items:center;font-size:.85rem;color:#e2e8f0\">\r\n        <input type=\"checkbox\" id=\"ssApproval\" ${s.require_approval !== false ? 'checked' : ''}>\r\n        <span>Require approval<br><span style=\"color:#6a8aaa;font-size:.72rem\">new suggestions wait in the queue</span></span>\r\n      </label>\r\n      <label style=\"font-size:.8rem;color:#cbd5e1\">Telegram / day\r\n        <input type=\"number\" min=\"0\" max=\"1000\" id=\"ssCapTg\" value=\"${caps.telegram != null ? caps.telegram : 5}\" style=\"width:90px\">\r\n      </label>\r\n      <label style=\"font-size:.8rem;color:#cbd5e1\">LinkedIn / day\r\n        <input type=\"number\" min=\"0\" max=\"1000\" id=\"ssCapLi\" value=\"${caps.linkedin != null ? caps.linkedin : 2}\" style=\"width:90px\">\r\n      </label>\r\n      <label style=\"font-size:.8rem;color:#cbd5e1\">Instagram / day\r\n        <input type=\"number\" min=\"0\" max=\"1000\" id=\"ssCapIg\" value=\"${caps.instagram != null ? caps.instagram : 2}\" style=\"width:90px\">\r\n      </label>\r\n      <label style=\"font-size:.8rem;color:#cbd5e1\">Caps timezone (IANA)\r\n        <input type=\"text\" id=\"ssTz\" value=\"${esc(s.caps_timezone || 'Asia/Kolkata')}\" style=\"width:150px\">\r\n      </label>\r\n    </div>\r\n    <label style=\"display:block;font-size:.8rem;color:#cbd5e1;margin-top:12px\">Footer appended to every post (≤200 chars)\r\n      <input type=\"text\" id=\"ssFooter\" value=\"${esc(s.footer || '')}\" style=\"width:100%;max-width:560px\">\r\n    </label>\r\n    <label style=\"display:block;font-size:.8rem;color:#cbd5e1;margin-top:10px\">Default Instagram hashtags (comma separated, ≤30)\r\n      <input type=\"text\" id=\"ssTags\" value=\"${esc((s.default_hashtags || []).join(', '))}\" style=\"width:100%;max-width:560px\">\r\n    </label>\r\n    <div class=\"import-actions\" style=\"margin-top:12px\">\r\n      <button class=\"btn-gold\" type=\"submit\">Save settings</button>\r\n    </div>\r\n  </form>`;\r\n  $('socialSettingsForm').onsubmit = async (e) => {\r\n    e.preventDefault();\r\n    const tags = String($('ssTags').value || '').split(',').map(t => t.trim()).filter(Boolean).slice(0, 30);\r\n    try {\r\n      await api('/api/social?op=settings', {\r\n        method: 'PATCH', key: adminKey,\r\n        body: JSON.stringify({\r\n          kill_switch: $('ssKill').checked,\r\n          require_approval: $('ssApproval').checked,\r\n          per_platform_daily_caps: {\r\n            telegram: Number($('ssCapTg').value) || 0,\r\n            linkedin: Number($('ssCapLi').value) || 0,\r\n            instagram: Number($('ssCapIg').value) || 0,\r\n          },\r\n          caps_timezone: $('ssTz').value.trim() || 'Asia/Kolkata',\r\n          footer: $('ssFooter').value.trim() || null,\r\n          default_hashtags: tags,\r\n        }),\r\n      });\r\n      setSocialStatus('Settings saved ✓', 'success');\r\n      toast('Social settings saved.');\r\n    } catch (err) {\r\n      setSocialStatus('❌ ' + err.message, 'error');\r\n    }\r\n  };\r\n}\r\n\r\n/* ── connections ──────────────────────────── */\r\n\r\nfunction renderSocialConnections(conns) {\r\n  const el = $('socialConnections');\r\n  if (!el) return;\r\n  const list = conns.map(c => {\r\n    const actions = [\r\n      `<button onclick=\"socialConnAction(${c.id},'verify')\">Verify</button>`,\r\n      c.is_primary\r\n        ? '<span style=\"color:#c9973c;font-size:.75rem\">★ primary</span>'\r\n        : `<button onclick=\"socialConnAction(${c.id},'primary')\">Make primary</button>`,\r\n      c.status === 'disabled'\r\n        ? `<button onclick=\"socialConnAction(${c.id},'enable')\">Enable</button>`\r\n        : `<button onclick=\"socialConnAction(${c.id},'disable')\">Disable</button>`,\r\n    ].join(' ');\r\n    return `<div style=\"display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:10px 12px;border:1px solid #23405c;border-radius:8px;margin-bottom:8px;background:#0d1b29\">\r\n      <div>\r\n        <b style=\"color:#e2e8f0\">${esc(c.platform)}</b>\r\n        ${c.route ? `<span style=\"color:#6a8aaa;font-size:.75rem\"> · ${esc(c.route)}</span>` : ''}\r\n        ${c.display_name ? `<div style=\"color:#cbd5e1;font-size:.85rem\">${esc(c.display_name)}</div>` : ''}\r\n        <div style=\"color:#6a8aaa;font-size:.72rem\">id ${esc(c.external_id)}${c.facebook_page_id ? ` · page ${esc(c.facebook_page_id)}` : ''}${c.scope ? ` · scope ${esc(c.scope)}` : ''}${c.status ? ` · ${esc(c.status)}` : ''}${c.last_verified_at ? ` · verified ${socialWhen(c.last_verified_at)}` : ''}</div>\r\n      </div>\r\n      <div style=\"display:flex;gap:6px;align-items:center;flex-wrap:wrap\">${actions}</div>\r\n    </div>`;\r\n  }).join('');\r\n  el.innerHTML = (list || '<p style=\"color:#6a8aaa;font-size:.85rem\">No connections registered yet.</p>') + `\r\n  <div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:10px;align-items:center\">\r\n    <select id=\"scPlatform\" style=\"background:#0d1b29;color:#e2e8f0;border:1px solid #23405c;border-radius:6px;padding:6px\">\r\n      <option value=\"telegram\">Telegram</option>\r\n      <option value=\"linkedin\">LinkedIn</option>\r\n      <option value=\"instagram\">Instagram</option>\r\n    </select>\r\n    <select id=\"scRoute\" style=\"background:#0d1b29;color:#e2e8f0;border:1px solid #23405c;border-radius:6px;padding:6px\">\r\n      <option value=\"\">— route (optional) —</option>\r\n      <option value=\"telegram_bot\">telegram_bot</option>\r\n      <option value=\"linkedin_member\">linkedin_member</option>\r\n      <option value=\"linkedin_organization\">linkedin_organization</option>\r\n      <option value=\"instagram_login\">instagram_login</option>\r\n      <option value=\"facebook_login\">facebook_login</option>\r\n    </select>\r\n    <input id=\"scExternal\" placeholder=\"External ID — the account id, never a token\" style=\"background:#0d1b29;color:#e2e8f0;border:1px solid #23405c;border-radius:6px;padding:6px;min-width:220px\">\r\n    <input id=\"scName\" placeholder=\"Display name\" style=\"background:#0d1b29;color:#e2e8f0;border:1px solid #23405c;border-radius:6px;padding:6px\">\r\n    <button class=\"btn-ghost\" onclick=\"socialAddConnection()\">+ Add connection</button>\r\n  </div>`;\r\n}\r\n\r\nasync function socialConnAction(id, action) {\r\n  try {\r\n    await api('/api/social?op=connections', {\r\n      method: 'POST', key: adminKey,\r\n      body: JSON.stringify({ op: 'connections', id, action }),\r\n    });\r\n    setSocialStatus(`Connection ${action} ✓`, 'success');\r\n    await loadSocial();\r\n  } catch (e) {\r\n    setSocialStatus('❌ Connection: ' + e.message, 'error');\r\n  }\r\n}\r\n\r\nasync function socialAddConnection() {\r\n  const platform = $('scPlatform').value;\r\n  const externalId = String($('scExternal').value || '').trim();\r\n  if (!externalId) {\r\n    setSocialStatus('❌ External ID is required (the account id — never a token)', 'error');\r\n    return;\r\n  }\r\n  try {\r\n    await api('/api/social?op=connections', {\r\n      method: 'POST', key: adminKey,\r\n      body: JSON.stringify({\r\n        op: 'connections',\r\n        platform,\r\n        route: $('scRoute').value || undefined,\r\n        external_id: externalId,\r\n        display_name: $('scName').value.trim() || undefined,\r\n      }),\r\n    });\r\n    setSocialStatus('Connection added ✓', 'success');\r\n    await loadSocial();\r\n  } catch (e) {\r\n    setSocialStatus('❌ Add connection: ' + e.message, 'error');\r\n  }\r\n}\r\n\r\n/* ── queue ────────────────────────────────── */\r\n\r\nfunction renderSocialQueue() {\r\n  const el = $('socialQueue');\r\n  if (!el) return;\r\n  const rows = socialFilter\r\n    ? socialRows.filter(r => r.status === socialFilter)\r\n    : socialRows;\r\n  if (!rows.length) {\r\n    el.innerHTML = '<p style=\"color:#6a8aaa;font-size:.85rem\">No suggestions' +\r\n      (socialFilter ? ` with status “${socialFilter}”` : ' yet') +\r\n      '. Suggestions appear automatically when an exam enters “Applications Open”, a job is published, or a government vacancy is verified.</p>';\r\n    return;\r\n  }\r\n  el.innerHTML = rows.map(s => {\r\n    const ledger = Array.isArray(s.social_publishes) ? s.social_publishes : [];\r\n    const real = ledger.filter(r => !r.is_test);\r\n    const open = socialExpanded === s.id;\r\n    const actions = [];\r\n    if (s.status === 'pending' || s.status === 'partial') {\r\n      actions.push(`<button class=\"btn-gold\" onclick=\"socialApprove(${s.id})\">✅ Approve</button>`);\r\n      actions.push(`<button onclick=\"socialReject(${s.id})\">🚫 Reject</button>`);\r\n    }\r\n    if (s.status === 'approved' || s.status === 'partial') {\r\n      actions.push(`<button class=\"btn-gold\" onclick=\"socialPublish(${s.id})\">📣 Publish</button>`);\r\n      actions.push(`<button onclick=\"socialTest(${s.id})\">🧪 Test send</button>`);\r\n    }\r\n    if (s.truth_state === 'stale') {\r\n      actions.push(`<button onclick=\"socialRegenerate(${s.id})\">↻ Regenerate</button>`);\r\n    }\r\n    if (s.status !== 'rejected' && s.status !== 'archived') {\r\n      actions.push(`<button onclick=\"socialArchive(${s.id})\">🗄️ Archive</button>`);\r\n    }\r\n    actions.push(`<button onclick=\"socialToggleLedger(${s.id})\">📜 Ledger (${real.length})</button>`);\r\n    const ledgerHtml = open ? `\r\n      <div style=\"margin-top:10px;padding:10px 12px;border:1px solid #23405c;border-radius:8px;background:#0a1520\">\r\n        ${real.length ? real.map(r => `\r\n          <div style=\"display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:6px 0;border-bottom:1px solid #16283a\">\r\n            <div style=\"font-size:.82rem\">\r\n              <b style=\"color:#e2e8f0\">${esc(r.platform)}</b> ${socialBadge('ledger', r.status)}\r\n              ${r.is_test ? '<span style=\"color:#6a8aaa;font-size:.72rem\"> · test</span>' : ''}\r\n              <div style=\"color:#6a8aaa;font-size:.72rem\">attempts ${r.attempts != null ? r.attempts : '—'}${r.last_attempt_at ? ` · last ${socialWhen(r.last_attempt_at)}` : ''}${r.external_url ? ` · <a href=\"${esc(r.external_url)}\" target=\"_blank\" rel=\"noopener\" style=\"color:#7dd3fc\">view post</a>` : ''}${r.destination_ref ? ` · dest ${esc(r.destination_ref)}` : ''}</div>\r\n              ${r.last_error ? `<div style=\"color:#f87171;font-size:.75rem;margin-top:2px\">${esc(r.last_error)}</div>` : ''}\r\n            </div>\r\n            <div style=\"display:flex;gap:6px\">\r\n              ${['failed', 'uncertain', 'expired', 'cancelled'].includes(r.status)\r\n                ? `<button onclick=\"socialResolve(${s.id},'${esc(r.platform)}','retry')\">↻ Retry</button>\r\n                   <button onclick=\"socialResolve(${s.id},'${esc(r.platform)}','cancel')\">✖ Cancel</button>`\r\n                : ''}\r\n            </div>\r\n          </div>`).join('')\r\n        : '<p style=\"color:#6a8aaa;font-size:.78rem;margin:0\">No real sends yet.</p>'}\r\n      </div>` : '';\r\n    return `<div style=\"padding:12px 14px;border:1px solid #23405c;border-radius:10px;margin-bottom:10px;background:#0d1b29\">\r\n      <div style=\"display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:start\">\r\n        <div style=\"min-width:0\">\r\n          <div style=\"display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:4px\">\r\n            ${socialBadge('suggestion', s.status)}\r\n            ${socialBadge('truth', s.truth_state || 'unverified')}\r\n            <span style=\"color:#6a8aaa;font-size:.72rem\">${esc(s.source_type)} #${esc(s.source_id)} · ${esc(s.template_key)}</span>\r\n          </div>\r\n          <b style=\"color:#e2e8f0;font-size:.95rem\">${esc(s.title)}</b>\r\n          <div style=\"color:#6a8aaa;font-size:.72rem;margin-top:2px\">created ${socialWhen(s.created_at)}</div>\r\n        </div>\r\n        <div style=\"display:flex;gap:6px;flex-wrap:wrap\">${actions.join('')}</div>\r\n      </div>\r\n      ${ledgerHtml}\r\n    </div>`;\r\n  }).join('');\r\n}\r\n\r\nfunction socialToggleLedger(id) {\r\n  socialExpanded = socialExpanded === id ? null : id;\r\n  renderSocialQueue();\r\n}\r\n\r\nasync function socialApi(op, body) {\r\n  return api(`/api/social?op=${op}`, {\r\n    method: 'POST', key: adminKey,\r\n    body: JSON.stringify({ op, ...body }),\r\n  });\r\n}\r\n\r\nasync function socialApprove(id) {\r\n  try {\r\n    await socialApi('approve', { id });\r\n    setSocialStatus('Suggestion approved ✓ — ready to publish', 'success');\r\n    await loadSocial();\r\n  } catch (e) {\r\n    setSocialStatus('❌ Approve: ' + e.message, 'error');\r\n  }\r\n}\r\n\r\nasync function socialReject(id) {\r\n  try {\r\n    await socialApi('reject', { id });\r\n    setSocialStatus('Suggestion rejected', 'success');\r\n    await loadSocial();\r\n  } catch (e) {\r\n    setSocialStatus('❌ Reject: ' + e.message, 'error');\r\n  }\r\n}\r\n\r\nasync function socialArchive(id) {\r\n  try {\r\n    await socialApi('archive', { id });\r\n    setSocialStatus('Suggestion archived', 'success');\r\n    await loadSocial();\r\n  } catch (e) {\r\n    setSocialStatus('❌ Archive: ' + e.message, 'error');\r\n  }\r\n}\r\n\r\nasync function socialPublish(id) {\r\n  try {\r\n    const d = await socialApi('publish', { id });\r\n    const results = (d.result && d.result.results) || [];\r\n    const summary = results\r\n      .map(r => `${r.platform}: ${r.ok ? (r.skipped ? 'skipped (already sent)' : 'sent ✓') : (r.error || 'failed')}`)\r\n      .join(' · ');\r\n    const failed = results.some(r => !r.ok && !r.skipped);\r\n    setSocialStatus(summary || 'Publish finished', failed ? 'error' : 'success');\r\n    await loadSocial();\r\n  } catch (e) {\r\n    setSocialStatus('❌ Publish: ' + e.message, 'error');\r\n  }\r\n}\r\n\r\nasync function socialTest(id) {\r\n  try {\r\n    await socialApi('test', { id, platform: 'telegram' });\r\n    setSocialStatus('Test send queued — check the private test channel (TELEGRAM_TEST_CHANNEL_ID)', 'success');\r\n    await loadSocial();\r\n  } catch (e) {\r\n    setSocialStatus('❌ Test send: ' + e.message, 'error');\r\n  }\r\n}\r\n\r\nasync function socialRegenerate(id) {\r\n  try {\r\n    await socialApi('reject', { id });\r\n    const s = socialRows.find(r => r.id === id);\r\n    if (!s) throw new Error('Suggestion not in the loaded queue — reload');\r\n    await socialApi('create', { source_type: s.source_type, source_id: s.source_id });\r\n    setSocialStatus('Suggestion regenerated from the current source record ✓', 'success');\r\n    await loadSocial();\r\n  } catch (e) {\r\n    setSocialStatus('❌ Regenerate: ' + e.message, 'error');\r\n  }\r\n}\r\n\r\nasync function socialResolve(id, platform, action) {\r\n  try {\r\n    await socialApi('resolve', { id, platform, action });\r\n    setSocialStatus(`Ledger row ${action}ed — queue re-rolled ✓`, 'success');\r\n    await loadSocial();\r\n  } catch (e) {\r\n    setSocialStatus('❌ Resolve: ' + e.message, 'error');\r\n  }\r\n}\r\n\r\n/* ════════════════════════════════════════════════\r\n   SALARY ADMIN (Feature 3)\r\n   Unverified queue + aggregated role × city table.\r\n   ════════════════════════════════════════════════ */\r\n\r\nlet salaryRows = [];\r\n\r\nfunction setSalaryStatus(msg, type='') {\r\n  const el = $('salaryAdminStatus');\r\n  if (!el) return;\r\n  el.textContent = msg || '';\r\n  el.className = `import-status show${type ? ' ' + type : ''}`;\r\n}\r\n\r\nconst inrShort = n => {\r\n  n = Number(n || 0);\r\n  if (n >= 10000000) return '₹' + (n / 10000000).toFixed(2) + ' Cr';\r\n  if (n >= 100000) return '₹' + (n / 100000).toFixed(1).replace(/\\.0$/, '') + 'L';\r\n  return '₹' + Number(n).toLocaleString('en-IN');\r\n};\r\n\r\nasync function loadSalaryAdmin() {\r\n  try {\r\n    const d = await api('/api/salary?admin=1', { key: adminKey });\r\n    salaryRows = d.unverified || [];\r\n    renderSalaryAggregate(d.aggregateTable || []);\r\n    renderSalaryUnverified();\r\n  } catch (e) {\r\n    $('adminSalary').innerHTML =\r\n      `<p style=\"color:#fca5a5;padding:1rem\">Could not load salary data: ${esc(e.message)}</p>` +\r\n      (/missing|not exist|PGRST205/i.test(e.message || '')\r\n        ? '<p style=\"color:#fbbf24;font-size:.82rem;padding:0 1rem\">Run <b>supabase-v21-salary.sql</b> in the Supabase SQL Editor, then press Refresh.</p>'\r\n        : '');\r\n  }\r\n}\r\n\r\nfunction renderSalaryAggregate(rows) {\r\n  if (!rows.length) {\r\n    $('salaryAggregate').innerHTML = '<p style=\"color:#6a8aaa;padding:.5rem 1rem\">No data yet.</p>';\r\n    return;\r\n  }\r\n  $('salaryAggregate').innerHTML = `\r\n    <div style=\"overflow-x:auto\">\r\n    <table class=\"source-health-table\" style=\"width:100%\">\r\n      <thead><tr><th>Role</th><th>City</th><th>Points</th><th>Min</th><th>Median</th><th>Max</th></tr></thead>\r\n      <tbody>${rows.map(r => `\r\n        <tr>\r\n          <td style=\"color:#fff;font-weight:650\">${esc(r.role)}</td>\r\n          <td>${esc(r.city || '—')}</td>\r\n          <td>${Number(r.data_points).toLocaleString('en-IN')}</td>\r\n          <td style=\"color:#6ee7b7\">${inrShort(r.min_sal)}</td>\r\n          <td style=\"color:#c9973c;font-weight:750\">${inrShort(r.median_sal)}</td>\r\n          <td style=\"color:#93c5fd\">${inrShort(r.max_sal)}</td>\r\n        </tr>`).join('')}\r\n      </tbody>\r\n    </table>\r\n    </div>`;\r\n}\r\n\r\nfunction renderSalaryUnverified() {\r\n  if (!salaryRows.length) {\r\n    $('adminSalary').innerHTML = '<p style=\"color:#6a8aaa;padding:.5rem 1rem\">No unverified submissions. All caught up ✓</p>';\r\n    return;\r\n  }\r\n  $('adminSalary').innerHTML = salaryRows.map(x => `\r\n    <div class=\"list-item\" data-sal-row=\"${esc(x.id)}\">\r\n      <div class=\"list-item-info\">\r\n        <h4>\r\n          ${esc(x.role)}\r\n          <span style=\"color:#c9973c;font-weight:800\">· ${inrShort(x.salary_annual)}/yr</span>\r\n          ${x.is_verified ? '<span class=\"status-badge published\">Verified</span>' : '<span class=\"status-badge unpublished\">Unverified</span>'}\r\n        </h4>\r\n        <p>\r\n          ${esc(x.company_type || '—')} · ${esc(x.city || '—')}${x.state ? ', ' + esc(x.state) : ''}\r\n          · ${esc(String(x.experience_years ?? '—'))} yrs\r\n          · submitted ${esc(String(x.created_at || '').slice(0, 10))}\r\n        </p>\r\n      </div>\r\n      <div class=\"mini-actions\">\r\n        <button class=\"btn-publish\" onclick=\"verifySalary('${esc(x.id)}',true)\">✓ Verify</button>\r\n        <button onclick=\"verifySalary('${esc(x.id)}',false)\">Unverify</button>\r\n        <button class=\"btn-delete\" onclick=\"deleteSalary('${esc(x.id)}')\">Delete</button>\r\n      </div>\r\n    </div>`).join('');\r\n}\r\n\r\nasync function verifySalary(id, isVerified) {\r\n  try {\r\n    await api('/api/salary', {\r\n      method: 'PATCH',\r\n      key: adminKey,\r\n      body: JSON.stringify({ id, is_verified: isVerified }),\r\n    });\r\n    salaryRows = salaryRows.filter(z => z.id !== id);\r\n    renderSalaryUnverified();\r\n    setSalaryStatus(isVerified ? 'Submission verified ✓' : 'Submission unverified.', 'success');\r\n    toast(isVerified ? 'Verified ✓' : 'Unverified.');\r\n    loadSalaryAdmin();\r\n  } catch (e) {\r\n    setSalaryStatus(`Failed: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function deleteSalary(id) {\r\n  if (!confirm('Delete this salary submission permanently?')) return;\r\n  try {\r\n    await api('/api/salary', { method: 'DELETE', key: adminKey, body: JSON.stringify({ id }) });\r\n    salaryRows = salaryRows.filter(z => z.id !== id);\r\n    renderSalaryUnverified();\r\n    toast('Submission deleted.');\r\n    loadSalaryAdmin();\r\n  } catch (e) {\r\n    toast(e.message);\r\n  }\r\n}\r\n\r\n/* ════════════════════════════════════════════════\r\n   WALK-INS ADMIN (Feature 6)\r\n   Add form + all-rows list with Publish/Delete.\r\n   ════════════════════════════════════════════════ */\r\n\r\nlet walkinRows = [];\r\n\r\nfunction setWalkinStatus(msg, type='') {\r\n  const el = $('walkinAdminStatus');\r\n  if (!el) return;\r\n  el.textContent = msg || '';\r\n  el.className = `import-status show${type ? ' ' + type : ''}`;\r\n}\r\n\r\nasync function loadWalkinAdmin() {\r\n  try {\r\n    /* Authenticated admin fetch → returns ALL rows (published + pending). */\r\n    const d = await api('/api/walkin?admin=all', { key: adminKey });\r\n    walkinRows = d.walkins || [];\r\n    renderWalkins();\r\n  } catch (e) {\r\n    $('adminWalkins').innerHTML =\r\n      `<p style=\"color:#fca5a5;padding:1rem\">Could not load walk-ins: ${esc(e.message)}</p>` +\r\n      (/missing|not exist|PGRST205/i.test(e.message || '')\r\n        ? '<p style=\"color:#fbbf24;font-size:.82rem;padding:0 1rem\">Run <b>supabase-v22-walkin.sql</b> in the Supabase SQL Editor, then press Refresh.</p>'\r\n        : '');\r\n  }\r\n}\r\n\r\nfunction walkinWhen(x) {\r\n  const d = x.date ? String(x.date).slice(0, 10) : '';\r\n  const t = x.time_start ? String(x.time_start).slice(0, 5) : '';\r\n  return [d, t].filter(Boolean).join(' · ');\r\n}\r\n\r\nfunction renderWalkins() {\r\n  if (!walkinRows.length) {\r\n    $('adminWalkins').innerHTML = '<p style=\"color:#6a8aaa;padding:.5rem 1rem\">No walk-ins yet. Add one with the form above.</p>';\r\n    return;\r\n  }\r\n  const today = new Date();\r\n  const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;\r\n  const sorted = [...walkinRows].sort((a, b) => String(a.date).localeCompare(String(b.date)));\r\n\r\n  $('adminWalkins').innerHTML = sorted.map(x => {\r\n    const isPast = x.date && String(x.date) < todayStr;\r\n    return `\r\n    <div class=\"list-item\" data-wi-row=\"${esc(x.id)}\">\r\n      <div class=\"list-item-info\">\r\n        <h4>\r\n          ${esc(x.company)}\r\n          <span class=\"status-badge ${x.published ? 'published' : 'unpublished'}\">${x.published ? 'Published' : 'Pending'}</span>\r\n          ${isPast ? '<span class=\"status-badge expired\">Past</span>' : ''}\r\n        </h4>\r\n        <p>\r\n          ${esc(x.roles || '')}\r\n          · ${esc(walkinWhen(x))}\r\n          · ${esc(x.venue || '')}${x.city ? ', ' + esc(x.city) : ''}\r\n          ${x.experience_required ? ' · ' + esc(x.experience_required) : ''}\r\n        </p>\r\n      </div>\r\n      <div class=\"mini-actions\">\r\n        <button class=\"${x.published ? '' : 'btn-publish'}\" onclick=\"toggleWalkin('${esc(x.id)}',${!x.published})\">${x.published ? 'Unpublish' : '✓ Publish'}</button>\r\n        <button class=\"btn-delete\" onclick=\"deleteWalkin('${esc(x.id)}')\">Delete</button>\r\n      </div>\r\n    </div>`;\r\n  }).join('');\r\n}\r\n\r\nasync function createWalkin() {\r\n  const payload = {\r\n    company: $('wiCompany').value.trim(),\r\n    roles: $('wiRoles').value.trim(),\r\n    date: $('wiDate').value,\r\n    time_start: $('wiStart').value,\r\n    time_end: $('wiEnd').value,\r\n    venue: $('wiVenue').value.trim(),\r\n    city: $('wiCity').value.trim(),\r\n    state: $('wiState').value.trim(),\r\n    experience_required: $('wiExp').value.trim(),\r\n    qualification: $('wiQual').value.trim(),\r\n    salary_offered: $('wiSalary').value.trim(),\r\n    expires_at: $('wiExpires').value,\r\n    documents_required: $('wiDocs').value.trim(),\r\n    contact: $('wiContact').value.trim(),\r\n    source_url: $('wiSource').value.trim(),\r\n    published: false,\r\n  };\r\n  const missing = ['company', 'roles', 'date', 'venue'].filter(f => !payload[f]);\r\n  if (missing.length) {\r\n    return setWalkinStatus('Please fill: ' + missing.join(', '), 'error');\r\n  }\r\n  const btns = document.querySelectorAll('#panel-walkins .btn-gold');\r\n  btns.forEach(b => b.disabled = true);\r\n  try {\r\n    await api('/api/walkin', { method: 'POST', key: adminKey, body: JSON.stringify(payload) });\r\n    setWalkinStatus('Walk-in added (pending). Publish it below when ready.', 'success');\r\n    clearWalkinForm();\r\n    await loadWalkinAdmin();\r\n  } catch (e) {\r\n    setWalkinStatus(`Save failed: ${e.message}`, 'error');\r\n  } finally {\r\n    btns.forEach(b => b.disabled = false);\r\n  }\r\n}\r\n\r\nfunction clearWalkinForm() {\r\n  ['wiCompany','wiRoles','wiDate','wiStart','wiEnd','wiVenue','wiCity','wiState','wiExp','wiQual','wiSalary','wiExpires','wiDocs','wiContact','wiSource'].forEach(id => { $(id).value = ''; });\r\n}\r\n\r\nasync function toggleWalkin(id, published) {\r\n  try {\r\n    await api('/api/walkin', { method: 'PUT', key: adminKey, body: JSON.stringify({ id, published }) });\r\n    setWalkinStatus(published ? 'Published ✓ — live on the public board' : 'Unpublished.', 'success');\r\n    toast(published ? 'Published ✓' : 'Unpublished.');\r\n    await loadWalkinAdmin();\r\n  } catch (e) {\r\n    setWalkinStatus(`Failed: ${e.message}`, 'error');\r\n  }\r\n}\r\n\r\nasync function deleteWalkin(id) {\r\n  if (!confirm('Delete this walk-in permanently?')) return;\r\n  try {\r\n    await api('/api/walkin', { method: 'DELETE', key: adminKey, body: JSON.stringify({ id }) });\r\n    walkinRows = walkinRows.filter(z => z.id !== id);\r\n    renderWalkins();\r\n    toast('Walk-in deleted.');\r\n  } catch (e) {\r\n    toast(e.message);\r\n  }\r\n}\r\n\r\n/* ════════════════════════════════════════════════\r\n   WHATSAPP SUBSCRIBERS ADMIN (Feature 9)\r\n   Count, filterable table, copy-all numbers, CSV export.\r\n   ════════════════════════════════════════════════ */\r\n\r\nlet waSubs = [];\r\n\r\nasync function loadWaSubs() {\r\n  try {\r\n    const d = await api('/api/whatsapp-subscribe', { key: adminKey });\r\n    waSubs = d.subscribers || [];\r\n    renderWaMetrics();\r\n    renderWaFilters();\r\n    renderWaSubs();\r\n  } catch (e) {\r\n    $('adminWaSubs').innerHTML =\r\n      `<p style=\"color:#fca5a5;padding:1rem\">Could not load subscribers: ${esc(e.message)}</p>` +\r\n      (/missing|not exist|PGRST205/i.test(e.message || '')\r\n        ? '<p style=\"color:#fbbf24;font-size:.82rem;padding:0 1rem\">Run <b>supabase-v23-whatsapp-subscribers.sql</b> in the Supabase SQL Editor, then press Refresh.</p>'\r\n        : '');\r\n  }\r\n}\r\n\r\nfunction waFiltered() {\r\n  const city = ($('waFilterCity').value || '').toLowerCase();\r\n  const role = ($('waFilterRole').value || '').toLowerCase();\r\n  const sector = $('waFilterSector').value || '';\r\n  return waSubs.filter(s =>\r\n    (!city || String(s.city || '').toLowerCase().includes(city)) &&\r\n    (!role || (s.preferred_roles || []).some(r => String(r).toLowerCase().includes(role))) &&\r\n    (!sector || (s.preferred_sectors || []).includes(sector))\r\n  );\r\n}\r\n\r\nfunction renderWaMetrics() {\r\n  $('waSubCount').textContent = Number(waSubs.length).toLocaleString('en-IN');\r\n  $('waSubActive').textContent = Number(waSubs.filter(s => s.is_active !== false).length).toLocaleString('en-IN');\r\n  $('waSubCities').textContent = new Set(waSubs.map(s => s.city).filter(Boolean)).size;\r\n  $('waSubHindi').textContent = Number(waSubs.filter(s => s.language === 'hi').length).toLocaleString('en-IN');\r\n}\r\n\r\nfunction renderWaFilters() {\r\n  const cities = [...new Set(waSubs.map(s => s.city).filter(Boolean))].sort();\r\n  const roles = [...new Set(waSubs.flatMap(s => s.preferred_roles || []))].sort();\r\n  const citySel = $('waFilterCity'), roleSel = $('waFilterRole');\r\n  const keepCity = citySel.value, keepRole = roleSel.value;\r\n  citySel.innerHTML = '<option value=\"\">All cities</option>' + cities.map(c => `<option ${c === keepCity ? 'selected' : ''}>${esc(c)}</option>`).join('');\r\n  roleSel.innerHTML = '<option value=\"\">All roles</option>' + roles.map(r => `<option ${r === keepRole ? 'selected' : ''}>${esc(r)}</option>`).join('');\r\n}\r\n\r\nfunction renderWaSubs() {\r\n  const rows = waFiltered();\r\n  if (!waSubs.length) {\r\n    $('adminWaSubs').innerHTML = '<p style=\"color:#6a8aaa;padding:.5rem 1rem\">No subscribers yet. The floating WhatsApp button on the homepage collects them.</p>';\r\n    return;\r\n  }\r\n  $('adminWaSubs').innerHTML = `\r\n    <table class=\"source-health-table\" style=\"width:100%\">\r\n      <thead><tr><th>Name</th><th>WhatsApp</th><th>City</th><th>Role(s)</th><th>Sectors</th><th>Lang</th><th>Joined</th></tr></thead>\r\n      <tbody>${rows.map(s => `\r\n        <tr>\r\n          <td style=\"color:#fff;font-weight:650\">${esc(s.name || '—')}</td>\r\n          <td>${esc(s.whatsapp || '')}</td>\r\n          <td>${esc(s.city || '—')}</td>\r\n          <td>${esc((s.preferred_roles || []).join(', ') || 'Any')}</td>\r\n          <td>${esc((s.preferred_sectors || []).join(', ') || '—')}</td>\r\n          <td>${esc(s.language === 'hi' ? 'हिं' : s.language === 'en' ? 'EN' : esc(s.language))}</td>\r\n          <td>${esc(String(s.created_at || '').slice(0, 10))}</td>\r\n        </tr>`).join('')}\r\n      </tbody>\r\n    </table>\r\n    ${rows.length !== waSubs.length ? `<p style=\"color:#6a8aaa;font-size:.76rem;padding:8px 4px\">Showing ${rows.length} of ${waSubs.length} subscribers.</p>` : ''}`;\r\n}\r\n\r\n/* Copy all (filtered) numbers as a comma list. Clipboard API needs HTTPS,\r\n   so fall back to a hidden textarea + execCommand on http/older browsers. */\r\nasync function copyWaNumbers() {\r\n  const nums = waFiltered().map(s => s.whatsapp).filter(Boolean);\r\n  if (!nums.length) { toast('No numbers to copy.'); return; }\r\n  const text = nums.join(',');\r\n  try {\r\n    await navigator.clipboard.writeText(text);\r\n    toast(`Copied ${nums.length} numbers ✓`);\r\n  } catch (_) {\r\n    const ta = document.createElement('textarea');\r\n    ta.value = text;\r\n    ta.style.cssText = 'position:fixed;left:-9999px';\r\n    document.body.appendChild(ta);\r\n    ta.select();\r\n    try { document.execCommand('copy'); toast(`Copied ${nums.length} numbers ✓`); }\r\n    catch (_) { toast('Copy failed — use Export CSV instead.'); }\r\n    ta.remove();\r\n  }\r\n}\r\n\r\nfunction exportWaCSV() {\r\n  const rows = waFiltered();\r\n  if (!rows.length) { toast('No subscribers to export.'); return; }\r\n  const q = v => `\"${String(v ?? '').replace(/\"/g, '\"\"')}\"`;\r\n  const csv = 'Name,WhatsApp,City,Role,Sectors,Language,Joined\\n' + rows.map(r =>\r\n    [r.name, r.whatsapp, r.city, (r.preferred_roles || []).join('; '), (r.preferred_sectors || []).join('; '), r.language, String(r.created_at || '').slice(0, 10)]\r\n      .map(q).join(',')\r\n  ).join('\\n');\r\n  const a = document.createElement('a');\r\n  a.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent('\\ufeff' + csv);\r\n  a.download = 'whatsapp-subscribers-' + new Date().toISOString().slice(0, 10) + '.csv';\r\n  a.click();\r\n  toast(`Exported ${rows.length} subscribers ✓`);\r\n}\r\n\r\n/* ══════════ COMPANY REVIEWS (Feature 5) ══════════ */\r\n\r\nlet ccReviews = [];\r\n\r\nasync function loadCompanyReviews() {\r\n  const root = $('adminCompanyReviews');\r\n  if (!root) return;\r\n  root.innerHTML = '<p style=\"color:#6a8aaa;font-size:.85rem\">Loading reviews…</p>';\r\n  try {\r\n    const d = await authedApi('/api/companies?status=pending', {});\r\n    ccReviews = d.reviews || [];\r\n    renderCompanyReviews();\r\n  } catch (e) {\r\n    root.innerHTML = `<p style=\"color:#fca5a5;padding:1rem\">Failed to load reviews: ${esc(e.message||'Unknown error')} — <button class=\"btn-ghost\" onclick=\"loadCompanyReviews()\">Retry</button></p>`;\r\n  }\r\n}\r\n\r\nfunction renderCompanyReviews() {\r\n  const root = $('adminCompanyReviews');\r\n  if (!root) return;\r\n  if (!ccReviews.length) {\r\n    root.innerHTML = '<p style=\"color:#6a8aaa;padding:1rem\">No reviews awaiting moderation. New submissions appear here automatically on refresh.</p>';\r\n    return;\r\n  }\r\n  const stars = n => n ? '★'.repeat(n) + '☆'.repeat(5 - n) : '—';\r\n  root.innerHTML = ccReviews.map(r => `\r\n    <div class=\"list-item\" data-review-id=\"${esc(r.id)}\">\r\n      <div class=\"list-item-info\">\r\n        <h4>${esc(r.company_name)}\r\n          <span class=\"status-badge unpublished\">${stars(r.rating_overall)} (${r.rating_overall || '—'}/5)</span>\r\n        </h4>\r\n        <p>${esc(r.reviewer_role || 'Civil engineer')}${r.reviewer_experience ? ' · ' + esc(r.reviewer_experience) : ''}${r.reviewer_city ? ' · ' + esc(r.reviewer_city) : ''} · ${esc(String(r.created_at || '').slice(0, 10))}</p>\r\n        ${r.pros ? `<p><b>Pros:</b> ${esc(r.pros)}</p>` : ''}\r\n        ${r.cons ? `<p><b>Cons:</b> ${esc(r.cons)} </p>` : ''}\r\n        ${r.advice ? `<p><b>Advice:</b> ${esc(r.advice)}</p>` : ''}\r\n        <p style=\"color:#94a3b8;font-size:.78rem\">\r\n          Salary on time: ${r.salary_paid_on_time == null ? '—' : (r.salary_paid_on_time ? 'Yes' : 'No')}\r\n          · Recommends: ${r.would_recommend == null ? '—' : (r.would_recommend ? 'Yes' : 'No')}\r\n        </p>\r\n      </div>\r\n      <div class=\"mini-actions\">\r\n        <button onclick=\"approveReview('${esc(r.id)}',true)\">Approve</button>\r\n        <button class=\"btn-delete\" onclick=\"approveReview('${esc(r.id)}',false)\">Reject</button>\r\n      </div>\r\n    </div>`).join('');\r\n}\r\n\r\nasync function approveReview(id, approve) {\r\n  if (!approve && !confirm('Reject and permanently delete this review?')) return;\r\n  try {\r\n    await authedApi('/api/companies', { method: 'PATCH', body: JSON.stringify({ id, is_approved: approve }) });\r\n    ccReviews = ccReviews.filter(x => x.id !== id);\r\n    renderCompanyReviews();\r\n    toast(approve ? 'Review approved ✓' : 'Review rejected.');\r\n  } catch (e) {\r\n    toast(e.message || 'Action failed.');\r\n  }\r\n}\r\n\r\n/* ══════════ BLOG (Feature C) ══════════ */\r\n\r\nlet ccBlog = [];\r\nlet ccBlogEditingSlug = null;\r\n\r\nasync function loadBlogAdmin() {\r\n  const root = $('adminBlog');\r\n  if (!root) return;\r\n  root.innerHTML = '<p style=\"color:#6a8aaa;font-size:.85rem\">Loading posts…</p>';\r\n  try {\r\n    const d = await authedApi('/api/blog', {});\r\n    ccBlog = d.posts || [];\r\n    renderBlogAdmin();\r\n  } catch (e) {\r\n    root.innerHTML = `<p style=\"color:#fca5a5;padding:1rem\">Failed to load posts: ${esc(e.message||'Unknown error')} — <button class=\"btn-ghost\" onclick=\"loadBlogAdmin()\">Retry</button></p>`;\r\n  }\r\n}\r\n\r\nfunction renderBlogAdmin() {\r\n  const root = $('adminBlog');\r\n  if (!root) return;\r\n  if (!ccBlog.length) {\r\n    root.innerHTML = '<p style=\"color:#6a8aaa;padding:1rem\">No posts yet. Click “+ New post” to write the first article.</p>';\r\n    return;\r\n  }\r\n  root.innerHTML = ccBlog.map(p => `\r\n    <div class=\"list-item\" data-blog-slug=\"${esc(p.slug)}\">\r\n      <div class=\"list-item-info\">\r\n        <h4>${esc(p.title)}\r\n          <span class=\"status-badge ${p.is_published ? 'published' : 'unpublished'}\">${p.is_published ? 'Published' : 'Draft'}</span>\r\n        </h4>\r\n        <p>${esc(p.category || 'Career')} · ${esc(p.author || 'CivilCareer Team')} · ${(p.views || 0)} views · /blog/${esc(p.slug)}</p>\r\n      </div>\r\n      <div class=\"mini-actions\">\r\n        <a href=\"/blog/${esc(p.slug)}\" target=\"_blank\" rel=\"noopener\">View</a>\r\n        <button onclick=\"blogEditor('${esc(p.slug)}')\">Edit</button>\r\n        <button class=\"btn-publish\" onclick=\"toggleBlogPublish('${esc(p.slug)}')\">${p.is_published ? 'Unpublish' : 'Publish'}</button>\r\n        <button class=\"btn-delete\" onclick=\"deleteBlogPost('${esc(p.slug)}')\">Delete</button>\r\n      </div>\r\n    </div>`).join('');\r\n}\r\n\r\nfunction blogEditor(slug) {\r\n  ccBlogEditingSlug = slug || null;\r\n  const box = $('blogEditor');\r\n  if (!box) return;\r\n  box.style.display = 'block';\r\n  box.scrollIntoView({ behavior: 'smooth', block: 'start' });\r\n  if (slug) {\r\n    const p = ccBlog.filter(x => x.slug === slug)[0];\r\n    if (!p) { toast('Post not found.'); return; }\r\n    $('blogEditorTitle').textContent = 'Edit post';\r\n    $('blogTitle').value = p.title || '';\r\n    $('blogSlug').value = p.slug || '';\r\n    $('blogCategory').value = p.category || 'Career';\r\n    $('blogAuthor').value = p.author || 'CivilCareer Team';\r\n    $('blogTags').value = (p.tags || []).join(', ');\r\n    $('blogExcerpt').value = p.excerpt || '';\r\n    $('blogContent').value = p.content || '';\r\n  } else {\r\n    $('blogEditorTitle').textContent = 'New post';\r\n    ['blogTitle','blogSlug','blogTags','blogExcerpt','blogContent'].forEach(id => { $(id).value = ''; });\r\n    $('blogAuthor').value = 'CivilCareer Team';\r\n  }\r\n}\r\n\r\nfunction hideBlogEditor() {\r\n  ccBlogEditingSlug = null;\r\n  const box = $('blogEditor');\r\n  if (box) box.style.display = 'none';\r\n}\r\n\r\nasync function saveBlogPost(publish) {\r\n  const title = ($('blogTitle').value || '').trim();\r\n  if (!title) { toast('Title is required.'); return; }\r\n  const st = $('blogEditorStatus');\r\n  st.className = 'import-status show';\r\n  st.textContent = 'Saving…';\r\n  try {\r\n    await authedApi('/api/blog', {\r\n      method: 'POST',\r\n      body: JSON.stringify({\r\n        title,\r\n        slug: ($('blogSlug').value || '').trim() || undefined,\r\n        category: $('blogCategory').value,\r\n        author: $('blogAuthor').value,\r\n        tags: $('blogTags').value,\r\n        excerpt: $('blogExcerpt').value,\r\n        content: $('blogContent').value,\r\n        is_published: Boolean(publish),\r\n      }),\r\n    });\r\n    st.className = 'import-status show success';\r\n    st.textContent = publish ? 'Published ✓' : 'Draft saved ✓';\r\n    toast(publish ? 'Post published.' : 'Draft saved.');\r\n    hideBlogEditor();\r\n    await loadBlogAdmin();\r\n  } catch (e) {\r\n    st.className = 'import-status show error';\r\n    st.textContent = e.message || 'Save failed.';\r\n  }\r\n}\r\n\r\nasync function toggleBlogPublish(slug) {\r\n  const p = ccBlog.filter(x => x.slug === slug)[0];\r\n  if (!p) return;\r\n  try {\r\n    await authedApi('/api/blog', {\r\n      method: 'POST',\r\n      body: JSON.stringify({\r\n        title: p.title, slug: p.slug, category: p.category, author: p.author,\r\n        tags: (p.tags || []).join(','), excerpt: p.excerpt, content: p.content,\r\n        is_published: !p.is_published,\r\n      }),\r\n    });\r\n    toast(p.is_published ? 'Post unpublished.' : 'Post published.');\r\n    await loadBlogAdmin();\r\n  } catch (e) {\r\n    toast(e.message || 'Action failed.');\r\n  }\r\n}\r\n\r\nasync function deleteBlogPost(slug) {\r\n  if (!confirm('Permanently delete this post?')) return;\r\n  try {\r\n    await authedApi(`/api/blog?slug=${encodeURIComponent(slug)}`, { method: 'DELETE' });\r\n    ccBlog = ccBlog.filter(x => x.slug !== slug);\r\n    renderBlogAdmin();\r\n    toast('Post deleted.');\r\n  } catch (e) {\r\n    toast(e.message || 'Delete failed.');\r\n  }\r\n}\r\n\r\n/* ══════════ INTERVIEW Q&A (Feature E) ══════════ */\r\n\r\nlet ccInterview = [];\r\n\r\nasync function loadInterviewAdmin() {\r\n  const root = $('adminInterview');\r\n  if (!root) return;\r\n  root.innerHTML = '<p style=\"color:#6a8aaa;font-size:.85rem\">Loading submissions…</p>';\r\n  try {\r\n    const d = await authedApi('/api/interview?status=pending', {});\r\n    ccInterview = d.questions || [];\r\n    renderInterviewAdmin();\r\n  } catch (e) {\r\n    root.innerHTML = `<p style=\"color:#fca5a5;padding:1rem\">Failed to load submissions: ${esc(e.message||'Unknown error')} — <button class=\"btn-ghost\" onclick=\"loadInterviewAdmin()\">Retry</button></p>`;\r\n  }\r\n}\r\n\r\nfunction renderInterviewAdmin() {\r\n  const root = $('adminInterview');\r\n  if (!root) return;\r\n  if (!ccInterview.length) {\r\n    root.innerHTML = '<p style=\"color:#6a8aaa;padding:1rem\">No questions awaiting moderation. Visitor submissions appear here automatically on refresh.</p>';\r\n    return;\r\n  }\r\n  root.innerHTML = ccInterview.map(q => `\r\n    <div class=\"list-item\" data-question-id=\"${esc(q.id)}\">\r\n      <div class=\"list-item-info\">\r\n        <h4>${esc(q.company)}\r\n          <span class=\"status-badge unpublished\">${esc(q.round || 'Technical')} · ${esc(q.difficulty || 'medium')}</span>\r\n        </h4>\r\n        <p>${esc(q.role)}${q.year ? ' · ' + esc(q.year) : ''} · ${esc(String(q.created_at || '').slice(0, 10))}</p>\r\n        <p style=\"white-space:pre-wrap;color:#cbd5e1\">${esc(q.question)}</p>\r\n        ${q.answer ? `<p><b>Answer:</b> ${esc(q.answer)}</p>` : ''}\r\n      </div>\r\n      <div class=\"mini-actions\">\r\n        <button class=\"btn-publish\" onclick=\"approveQuestion('${esc(q.id)}',true)\">Approve</button>\r\n        <button class=\"btn-delete\" onclick=\"approveQuestion('${esc(q.id)}',false)\">Reject</button>\r\n      </div>\r\n    </div>`).join('');\r\n}\r\n\r\nasync function approveQuestion(id, approve) {\r\n  if (!approve && !confirm('Reject and permanently delete this question?')) return;\r\n  try {\r\n    await authedApi('/api/interview', { method: 'PATCH', body: JSON.stringify({ id, is_approved: approve }) });\r\n    ccInterview = ccInterview.filter(x => x.id !== id);\r\n    renderInterviewAdmin();\r\n    toast(approve ? 'Question approved ✓' : 'Question rejected.');\r\n  } catch (e) {\r\n    toast(e.message || 'Action failed.');\r\n  }\r\n}\r\n\r\n/* ── AI Job Collector + Admin Job Inbox ────────────────────────────────\r\n   The owner submits material they already have (pasted text, screenshots,\r\n   PDFs, public links). The server extracts every role, scores civil\r\n   relevance + confidence, flags duplicates and parks the candidates in an\r\n   admin-only inbox. Only \"Approve & publish\" writes to the public jobs table.\r\n   No automatic scraping of WhatsApp, LinkedIn or login-protected portals. */\r\n\r\nlet jcBatchesCache=[];\r\nlet jiActive='all',jiItemsCache=[],jiCurrent=null;\r\nconst JC_MAX_FILE_BYTES=4*1024*1024;\r\n\r\nconst JC_REJECT_REASONS=[\r\n  'Not a civil engineering job',\r\n  'Duplicate of an existing job',\r\n  'Too old or already expired',\r\n  'Incomplete information',\r\n  'Non-Indian location',\r\n  'Unverifiable or spam',\r\n  'Other'\r\n];\r\n\r\nconst JI_RELEVANCE=['civil_engineering','construction','quantity_surveying','billing','planning','bim','qa_qc','surveying','geotechnical','structural','transportation','water_resources','infrastructure','government_engineering','architecture_related','project_management','uncertain','non_relevant'];\r\n\r\nconst JI_EDIT_FIELDS=[\r\n  ['title','Job title'],['company','Company'],['city','City'],['state','State'],['location','Location (display)'],\r\n  ['job_type','Job type'],['work_mode','Work mode'],['experience_min','Experience min (years)'],['experience_max','Experience max (years)'],\r\n  ['qualification','Qualification'],['skills','Skills (comma separated)'],['salary','Salary (display)'],['salary_min','Salary min'],\r\n  ['salary_max','Salary max'],['salary_currency','Currency'],['salary_period','Salary period'],\r\n  ['application_email','Application email'],['application_phone','Application phone'],['application_url','Application URL'],\r\n  ['expiry','Apply before (YYYY-MM-DD)']\r\n];\r\n\r\nfunction jcInitialView(){\r\n  const q=new URLSearchParams(location.search).get('view')||'';\r\n  const h=(location.hash||'').replace(/^#/,'');\r\n  const raw=(q||h).toLowerCase();\r\n  const path=(location.pathname||'').toLowerCase();\r\n  if(raw==='collector'||raw==='jobs/collector'||raw==='submit'||path.endsWith('/admin/jobs/collector'))return 'collector';\r\n  if(raw==='inbox'||raw==='jobs/inbox'||path.endsWith('/admin/jobs/inbox'))return 'inbox';\r\n  return '';\r\n}\r\n\r\nfunction jcLoadInitial(){\r\n  const view=jcInitialView();\r\n  if(!view)return;\r\n  const btn=document.querySelector('#tabs button[data-tab=\"'+view+'\"]');\r\n  if(btn)btn.click();\r\n}\r\n\r\nfunction jiGoCollector(){\r\n  const b=document.querySelector('#tabs button[data-tab=\"collector\"]');\r\n  if(b)b.click();\r\n}\r\nfunction jiGoInbox(){\r\n  const b=document.querySelector('#tabs button[data-tab=\"inbox\"]');\r\n  if(b)b.click();\r\n}\r\n\r\nfunction jcMetricCells(m){\r\n  const cell=function(key,label){\r\n    return '<div class=\"metric\"><span>'+label+'</span><b>'+Number((m&&m[key])||0)+'</b></div>';\r\n  };\r\n  return cell('pending','Inbox pending')+cell('needs_attention','Needs attention')+cell('possible_duplicates','Possible duplicates')\r\n    +cell('approved','Approved')+cell('rejected','Rejected')+cell('failed','Failed sources');\r\n}\r\n\r\nlet jcSetupDone=false;\r\n\r\nasync function jcCheckSetup(){\r\n  const box=$('jcSetup');\r\n  if(!box)return;\r\n  box.innerHTML='<p style=\"font-size:.76rem;color:#8a9bb0\">Checking the v30 tables and the job-sources bucket…</p>';\r\n  try{\r\n    const data=await api('/api/job-collector?action=diagnostics',{key:adminKey});\r\n    box.innerHTML=(data.checks||[]).map(function(c){\r\n      const optional=(c.critical===false);\r\n      const icon=c.ok?'✅':(optional?'ℹ️':'❌');\r\n      const colour=c.ok?'#8a9bb0':(optional?'#8a9bb0':'#fca5a5');\r\n      return '<div class=\"jc-itemline\">'+icon+' '+esc(c.name)+(c.ok?'':' · <span style=\"color:'+colour+'\">'+esc(c.error||('HTTP '+c.status))+'</span>')+'</div>';\r\n    }).join('')\r\n      +(data.ok?'<p style=\"font-size:.76rem;color:#6ee7b7;margin:6px 0 0\">All set — every table and the storage bucket are reachable.</p>'\r\n        :'<p style=\"font-size:.76rem;color:#fca5a5;margin:6px 0 0\">Run v30-job-collector.sql in Supabase → SQL editor, then press 🔎 Check setup again.</p>');\r\n  }catch(err){\r\n    box.innerHTML='<p style=\"color:#fca5a5;font-size:.76rem\">'+esc(err.message||'Setup check failed')+'</p>';\r\n  }\r\n}\r\n\r\nasync function jcLoadBatches(){\r\n  const root=$('jcBatches');\r\n  const jcMetrics=$('jcMetrics');\r\n  const jiMetrics=$('jiMetrics');\r\n  if(!root&&!jcMetrics&&!jiMetrics)return;\r\n  if(root&&!jcBatchesCache.length)root.innerHTML='<p style=\"color:#6a8aaa;font-size:.8rem\">Loading batches…</p>';\r\n  try{\r\n    const data=await api('/api/job-collector?action=metrics',{key:adminKey});\r\n    jcBatchesCache=data.batches||[];\r\n    const cells=jcMetricCells(data.metrics);\r\n    if(jcMetrics)jcMetrics.innerHTML=cells;\r\n    if(jiMetrics)jiMetrics.innerHTML=cells;\r\n    if(root)root.innerHTML=jcBatchesHtml();\r\n    if(jiActive==='processing')renderJiProcessing();\r\n  }catch(err){\r\n    if(root)root.innerHTML='<p style=\"color:#fca5a5;font-size:.8rem\">'+esc(err.message||'Could not load batches')+'</p>';\r\n  }\r\n}\r\n\r\nfunction jcBatchHtml(b){\r\n  const st=String(b.status||'open');\r\n  return '<div class=\"jc-batch\">'\r\n    +'<h4>'+esc(b.label||'Untitled batch')+' <span class=\"jc-badge jc-st-'+esc(st)+'\">'+esc(st)+'</span></h4>'\r\n    +'<p>'+new Date(b.created_at||Date.now()).toLocaleString()+' · '+Number(b.source_count||0)+' source(s) · '+Number(b.processed_count||0)+' processed · '+Number(b.jobs_detected||0)+' candidate(s)'\r\n      +(b.duplicates?' · '+Number(b.duplicates)+' possible duplicate(s)':'')\r\n      +(b.failed_count?' · '+Number(b.failed_count)+' failed source(s)':'')+'</p>'\r\n    +'<div style=\"display:flex;gap:6px;flex-wrap:wrap\">'\r\n      +'<button class=\"btn-gold\" style=\"font-size:.74rem;padding:5px 12px\" data-id=\"'+esc(b.id)+'\" onclick=\"jcProcessNow(this.dataset.id)\">▶ Process / resume</button>'\r\n      +'<button class=\"btn-ghost\" style=\"font-size:.74rem\" data-id=\"'+esc(b.id)+'\" onclick=\"jcOpenBatch(this.dataset.id)\">👁 Sources</button>'\r\n      +'<button class=\"btn-ghost\" style=\"font-size:.74rem\" onclick=\"jiGoInbox()\">📬 Open inbox</button>'\r\n    +'</div>'\r\n    +'<div id=\"jcBatchItems-'+esc(b.id)+'\"></div>'\r\n  +'</div>';\r\n}\r\n\r\nfunction jcBatchesHtml(){\r\n  if(!jcBatchesCache.length)return '<p style=\"color:#6a8aaa;font-size:.8rem\">No batches yet — submit your first text, screenshot, PDF or link.</p>';\r\n  return jcBatchesCache.map(jcBatchHtml).join('');\r\n}\r\n\r\nfunction jcFileToBase64(file){\r\n  return new Promise(function(resolve,reject){\r\n    const fr=new FileReader();\r\n    fr.onload=function(){resolve(String(fr.result||'').split(',')[1]||'');};\r\n    fr.onerror=function(){reject(Error('Could not read '+file.name));};\r\n    fr.readAsDataURL(file);\r\n  });\r\n}\r\n\r\nasync function jcSubmit(){\r\n  const btn=$('jcSubmitBtn');\r\n  const statusEl=$('jcStatus');\r\n  const label=String($('jcLabel').value||'').trim();\r\n  const text=String($('jcText').value||'').trim();\r\n  const urls=String($('jcUrls').value||'').split(/\\s*\\n\\s*/).map(function(s){return s.trim();}).filter(Boolean).slice(0,30);\r\n  const files=Array.prototype.slice.call($('jcFiles').files||[]).slice(0,20);\r\n  const items=[];\r\n  if(text)items.push({kind:'text',text:text});\r\n  urls.forEach(function(u){items.push({kind:'url',url:u});});\r\n  for(const f of files){\r\n    if(f.size>JC_MAX_FILE_BYTES){toast(f.name+' is larger than 4 MB — skipped.');continue;}\r\n    let b64='';\r\n    try{b64=await jcFileToBase64(f);}catch(err){toast(err.message);continue;}\r\n    items.push({kind:/pdf/i.test(f.type||f.name)?'pdf':'image',filename:f.name,mime:f.type||null,data_base64:b64});\r\n  }\r\n  if(!items.length)return toast('Paste text, add a link or choose a screenshot/PDF first.');\r\n  btn.disabled=true;btn.textContent='Uploading…';\r\n  if(statusEl)statusEl.textContent='Storing '+items.length+' source(s)…';\r\n  try{\r\n    const created=await api('/api/job-collector?action=create_batch',{method:'POST',key:adminKey,body:JSON.stringify({label:label||null,items:items})});\r\n    $('jcText').value='';$('jcUrls').value='';$('jcFiles').value='';$('jcLabel').value='';\r\n    if(statusEl)statusEl.textContent='Extracting jobs…';\r\n    const summary=await jcProcessBatch(created.batch.id);\r\n    if(statusEl)statusEl.textContent=summary;\r\n    toast('Batch processed — review the candidates in the Job Inbox.');\r\n    await jcLoadBatches();\r\n  }catch(err){\r\n    if(statusEl)statusEl.textContent='❌ '+(err.message||'Failed');\r\n    toast(err.message||'Could not submit the batch.');\r\n  }finally{\r\n    btn.disabled=false;btn.textContent='🚀 Add to batch & extract';\r\n  }\r\n}\r\n\r\nasync function jcProcessBatch(batchId){\r\n  let last=null;\r\n  for(let round=0;round<25;round+=1){\r\n    last=await api('/api/job-collector?action=process',{method:'POST',key:adminKey,body:JSON.stringify({batch_id:batchId})});\r\n    const statusEl=$('jcStatus');\r\n    if(last.remaining&&statusEl)statusEl.textContent='Processing… '+last.remaining+' source(s) still queued';\r\n    if(!last.remaining)break;\r\n  }\r\n  if(!last)return 'Nothing to process.';\r\n  let msg='Processed '+Number(last.processed||0)+' source(s) → '+Number(last.jobs_detected||0)+' candidate(s)';\r\n  if(last.duplicates)msg+=', '+Number(last.duplicates)+' flagged as possible duplicate(s)';\r\n  if(last.failed)msg+=', '+Number(last.failed)+' source(s) failed — paste the text in the batch view to retry';\r\n  if(last.remaining)msg+='. '+last.remaining+' still queued — press “Process / resume”.';\r\n  return msg;\r\n}\r\n\r\nasync function jcProcessNow(batchId){\r\n  if(!batchId)return;\r\n  try{\r\n    const msg=await jcProcessBatch(batchId);\r\n    toast(msg);\r\n    const statusEl=$('jcStatus');\r\n    if(statusEl)statusEl.textContent=msg;\r\n    await jcLoadBatches();\r\n  }catch(err){toast(err.message||'Processing failed.');}\r\n}\r\n\r\nasync function jcOpenBatch(batchId){\r\n  const box=$('jcBatchItems-'+batchId);\r\n  if(!box)return;\r\n  if(box.dataset.open==='1'){box.dataset.open='0';box.innerHTML='';return;}\r\n  box.dataset.open='1';\r\n  box.innerHTML='<p style=\"font-size:.75rem;color:#6a8aaa\">Loading sources…</p>';\r\n  try{\r\n    const data=await api('/api/job-collector?action=batch&id='+encodeURIComponent(batchId),{key:adminKey});\r\n    const items=data.items||[];\r\n    box.innerHTML=items.length?items.map(function(it){\r\n      const retriable=(it.status==='failed'||it.status==='needs_text');\r\n      return '<div class=\"jc-itemline\">• '+esc(it.kind)+(it.filename?' <b>'+esc(it.filename)+'</b>':'')+' — <span class=\"st\">'+esc(it.status)+'</span>'\r\n        +(it.jobs_found?' · '+Number(it.jobs_found)+' candidate(s)':'')\r\n        +(it.error?' · <span style=\"color:#fca5a5\">'+esc(it.error)+'</span>':'')\r\n        +(retriable?' <button class=\"btn-ghost\" style=\"font-size:.7rem;padding:3px 9px\" data-item=\"'+esc(it.id)+'\" data-batch=\"'+esc(batchId)+'\" onclick=\"jcRetryItem(this.dataset.item,this.dataset.batch)\">↻ Retry with text</button>':'')\r\n        +'</div>';\r\n    }).join(''):'<p style=\"font-size:.75rem;color:#6a8aaa\">No sources in this batch.</p>';\r\n  }catch(err){box.innerHTML='<p style=\"color:#fca5a5;font-size:.75rem\">'+esc(err.message||'Could not load sources')+'</p>';}\r\n}\r\n\r\nasync function jcRetryItem(itemId,batchId){\r\n  const text=prompt('Paste the job text for this source (needed when OCR is unavailable). Leave empty to simply retry.');\r\n  if(text===null)return;\r\n  const body={item_id:itemId};\r\n  if(text.trim())body.text=text.trim();\r\n  try{\r\n    await api('/api/job-collector?action=retry',{method:'POST',key:adminKey,body:JSON.stringify(body)});\r\n    toast('Source re-queued.');\r\n    await jcProcessNow(batchId);\r\n  }catch(err){toast(err.message||'Retry failed.');}\r\n}\r\n\r\nasync function jiLoad(tab){\r\n  jiActive=tab||jiActive;\r\n  document.querySelectorAll('#jiTabs button').forEach(function(b){b.classList.toggle('active',b.dataset.jitab===jiActive);});\r\n  const root=$('jiList');\r\n  if(!root)return;\r\n  if(jiActive==='processing'){\r\n    root.innerHTML='<p style=\"color:#6a8aaa;font-size:.85rem\">Loading batches…</p>';\r\n    await jcLoadBatches();\r\n    renderJiProcessing();\r\n    return;\r\n  }\r\n  root.innerHTML='<p style=\"color:#6a8aaa;font-size:.85rem\">Loading…</p>';\r\n  try{\r\n    let url='/api/job-collector?action=inbox&limit=50';\r\n    if(jiActive==='duplicates')url+='&duplicates=1';\r\n    else if(jiActive!=='all')url+='&status='+encodeURIComponent(jiActive);\r\n    const data=await api(url,{key:adminKey});\r\n    jiItemsCache=data.items||[];\r\n    jiRenderList();\r\n    jcLoadBatches();\r\n  }catch(err){root.innerHTML='<p style=\"color:#fca5a5;font-size:.8rem\">'+esc(err.message||'Could not load the inbox')+'</p>';}\r\n}\r\n\r\nfunction renderJiProcessing(){\r\n  const root=$('jiList');\r\n  if(!root)return;\r\n  root.innerHTML='<p style=\"font-size:.78rem;color:#8ea8c4;margin:0 0 10px\">A source stays here until it finishes processing. Failed or OCR-less sources can be retried with pasted text — nothing is lost.</p>'+jcBatchesHtml();\r\n}\r\n\r\nfunction jiFilter(){jiRenderList();}\r\n\r\nfunction jiRenderList(){\r\n  const root=$('jiList');\r\n  if(!root)return;\r\n  const q=String(($('jiSearch')||{}).value||'').toLowerCase().trim();\r\n  let list=jiItemsCache;\r\n  if(q)list=list.filter(function(r){\r\n    return [r.title,r.company,r.city,r.state,r.location,r.application_email].filter(Boolean).join(' ').toLowerCase().indexOf(q)!==-1;\r\n  });\r\n  if(!list.length){root.innerHTML='<p style=\"color:#6a8aaa;font-size:.85rem\">Nothing in this tab right now.</p>';return;}\r\n  root.innerHTML=list.map(jiRowHtml).join('');\r\n}\r\n\r\nfunction jiRowHtml(r){\r\n  const st=String(r.status||'pending');\r\n  const rel=String(r.relevance_category||'uncertain');\r\n  const conf=Math.round(Number(r.confidence_score||0)*100);\r\n  const dup=r.duplicate_of?'<span class=\"ji-badge ji-dup\">⚠ possible duplicate '+Math.round(Number(r.duplicate_score||0)*100)+'%</span>':'';\r\n  const actions=['<button class=\"btn-gold\" style=\"font-size:.74rem;padding:5px 12px\" data-id=\"'+esc(r.id)+'\" onclick=\"jiOpen(this.dataset.id)\">🔎 Review &amp; edit</button>'];\r\n  if(st!=='approved')actions.push('<button class=\"btn-pub-bulk\" style=\"font-size:.74rem;padding:5px 12px\" data-id=\"'+esc(r.id)+'\" onclick=\"jiApprove(this.dataset.id)\">✅ Approve &amp; publish</button>');\r\n  if(st!=='rejected')actions.push('<button class=\"btn-rej-bulk\" style=\"font-size:.74rem;padding:5px 12px\" data-id=\"'+esc(r.id)+'\" onclick=\"jiReject(this.dataset.id)\">✕ Reject</button>');\r\n  return '<div class=\"ji-item\"><div class=\"ji-item-body\">'\r\n    +'<h4>'+esc(r.title||'Untitled role')+' '+dup+'</h4>'\r\n    +'<p>'+esc(r.company||'Company not stated')+' · '+esc(r.location||[r.city,r.state].filter(Boolean).join(', ')||'Location not stated')+' · '+esc(r.salary||'Salary not stated')+(r.expiry?' · apply by '+esc(String(r.expiry).slice(0,10)):'')+'</p>'\r\n    +'<p><span class=\"ji-badge ji-rel-'+esc(rel)+'\">'+esc(rel.replace(/_/g,' '))+'</span> <span class=\"ji-badge\">confidence '+conf+'%</span> <span class=\"ji-badge ji-st-'+esc(st)+'\">'+esc(st.replace(/_/g,' '))+'</span>'\r\n      +(r.admin_edited?' <span class=\"ji-badge\">edited by you</span>':'')\r\n      +' <span style=\"color:#6a8aaa\">· '+esc(r.source_type||'manual')+(r.source_file?' · '+esc(r.source_file):'')+'</span></p>'\r\n    +'<div class=\"ji-actions\">'+actions.join('')+'</div>'\r\n  +'</div></div>';\r\n}\r\n\r\nasync function jiOpen(id){\r\n  const box=$('jiDetail');\r\n  if(!box||!id)return;\r\n  box.style.display='block';\r\n  box.innerHTML='<p style=\"color:#6a8aaa;font-size:.85rem\">Loading…</p>';\r\n  try{\r\n    const data=await api('/api/job-collector?action=item&id='+encodeURIComponent(id),{key:adminKey});\r\n    jiCurrent=data.item||{};\r\n    box.innerHTML=jiDetailHtml(jiCurrent,data);\r\n    box.scrollIntoView({behavior:'smooth',block:'start'});\r\n  }catch(err){box.innerHTML='<p style=\"color:#fca5a5;font-size:.8rem\">'+esc(err.message||'Could not load the item')+'</p>';}\r\n}\r\n\r\nfunction jiCloseDetail(){\r\n  const box=$('jiDetail');\r\n  if(box){box.style.display='none';box.innerHTML='';}\r\n  jiCurrent=null;\r\n}\r\n\r\nfunction jiDetailHtml(row,data){\r\n  const fields=JI_EDIT_FIELDS.map(function(pair){\r\n    const key=pair[0],label=pair[1];\r\n    const raw=row[key];\r\n    const v=raw===null||raw===undefined?'':String(raw);\r\n    const wide=(key==='location'||key==='qualification');\r\n    if(key==='skills'){\r\n      const sv=Array.isArray(raw)?raw.join(', '):v;\r\n      return '<div class=\"ji-field wide\"><label>'+label+'</label><input id=\"jiF-skills\" value=\"'+esc(sv)+'\"></div>';\r\n    }\r\n    return '<div class=\"ji-field'+(wide?' wide':'')+'\"><label>'+label+'</label><input id=\"jiF-'+esc(key)+'\" value=\"'+esc(v)+'\"></div>';\r\n  }).join('');\r\n  const rel=String(row.relevance_category||'uncertain');\r\n  const relOpts=JI_RELEVANCE.map(function(c){return '<option value=\"'+c+'\"'+(c===rel?' selected':'')+'>'+c.replace(/_/g,' ')+'</option>';}).join('');\r\n  const st=String(row.status||'pending');\r\n  const src=(data&&data.source)||{};\r\n  let preview='<p style=\"font-size:.76rem;color:#8ea8c4\">Source: '+esc(src.kind||row.source_type||'manual')+(src.filename?' · '+esc(src.filename):'')+(src.source_url?' · '+esc(src.source_url):'')+'</p>';\r\n  if(data&&data.original_url){\r\n    preview+=(String(src.mime||'').indexOf('image/')===0)\r\n      ?'<a href=\"'+esc(data.original_url)+'\" target=\"_blank\" rel=\"noopener\"><img class=\"ji-original\" src=\"'+esc(data.original_url)+'\" alt=\"Original submitted source\"></a>'\r\n      :'<p style=\"font-size:.8rem\"><a href=\"'+esc(data.original_url)+'\" target=\"_blank\" rel=\"noopener\" style=\"color:#c9973c\">Open the original file (signed link, 10 minutes)</a></p>';\r\n  } else {\r\n    preview+='<p style=\"font-size:.76rem;color:#6a8aaa\">No stored file for this source — the extracted text is kept below.</p>';\r\n  }\r\n  if(src.raw_text)preview+='<details style=\"margin-top:8px\"><summary style=\"cursor:pointer;font-size:.76rem;color:#8ea8c4\">Raw extracted text</summary><pre class=\"ji-raw\">'+esc(String(src.raw_text).slice(0,4000))+'</pre></details>';\r\n  const events=((data&&data.events)||[]).slice(0,12).map(function(e){\r\n    return '<li>'+esc(e.event||'event')+' — '+esc(e.actor||'system')+' · '+esc(String(e.at||e.created_at||'').slice(0,19).replace('T',' '))+(e.notes?' · '+esc(e.notes):'')+'</li>';\r\n  }).join('');\r\n  const dup=row.duplicate_of?'<div class=\"jc-note\">⚠ Possible duplicate ('+Math.round(Number(row.duplicate_score||0)*100)+'%): '+esc((row.duplicate_reasons||[]).join(', ')||'a similar job may already be published')+'. Approving again needs an explicit confirmation.</div>':'';\r\n  return '<div class=\"ji-detail\">'\r\n    +'<div style=\"display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap\">'\r\n      +'<h3>'+esc(row.title||'Untitled role')+' <span class=\"ji-badge ji-st-'+esc(st)+'\">'+esc(st.replace(/_/g,' '))+'</span></h3>'\r\n      +'<div class=\"ji-actions\">'\r\n        +'<button class=\"btn-gold\" onclick=\"jiSave()\">💾 Save changes</button>'\r\n        +(st!=='approved'?'<button class=\"btn-pub-bulk\" data-id=\"'+esc(row.id)+'\" onclick=\"jiApprove(this.dataset.id)\">✅ Approve &amp; publish</button>':'')\r\n        +(st!=='rejected'&&st!=='approved'?'<button class=\"btn-rej-bulk\" data-id=\"'+esc(row.id)+'\" onclick=\"jiReject(this.dataset.id)\">✕ Reject</button>':'')\r\n        +'<button class=\"btn-ghost\" onclick=\"jiCloseDetail()\">✕ Close</button>'\r\n      +'</div>'\r\n    +'</div>'\r\n    +dup\r\n    +'<div class=\"ji-form\">'+fields\r\n      +'<div class=\"ji-field\"><label>Relevance</label><select id=\"jiF-relevance_category\">'+relOpts+'</select></div>'\r\n      +'<div class=\"ji-field wide\"><label>Review notes</label><input id=\"jiF-review_notes\" value=\"'+esc(row.review_notes||'')+'\"></div>'\r\n    +'</div>'\r\n    +'<div class=\"ji-field wide\" style=\"margin-top:10px\"><label>Description</label><textarea id=\"jiF-description\" rows=\"6\">'+esc(row.description||'')+'</textarea></div>'\r\n    +'<div class=\"ji-source\">'+preview+(events?'<ul class=\"ji-events\">'+events+'</ul>':'')+'</div>'\r\n  +'</div>';\r\n}\r\n\r\nasync function jiSave(){\r\n  if(!jiCurrent||!jiCurrent.id)return;\r\n  const payload={};\r\n  JI_EDIT_FIELDS.forEach(function(pair){\r\n    const key=pair[0];\r\n    const el=$('jiF-'+key);\r\n    if(!el)return;\r\n    const v=String(el.value||'').trim();\r\n    if(key==='skills'){payload.skills=v?v.split(',').map(function(s){return s.trim();}).filter(Boolean):[];return;}\r\n    if(['experience_min','experience_max','salary_min','salary_max'].indexOf(key)!==-1){payload[key]=v===''?null:Number(v);return;}\r\n    payload[key]=v===''?null:v;\r\n  });\r\n  const rel=$('jiF-relevance_category');\r\n  if(rel)payload.relevance_category=rel.value;\r\n  const notes=$('jiF-review_notes');\r\n  if(notes)payload.review_notes=notes.value.trim()||null;\r\n  const desc=$('jiF-description');\r\n  if(desc)payload.description=desc.value.trim()||null;\r\n  try{\r\n    const out=await api('/api/job-collector?action=update',{method:'POST',key:adminKey,body:JSON.stringify({id:jiCurrent.id,payload:payload})});\r\n    jiCurrent=out.item||jiCurrent;\r\n    toast('Changes saved.');\r\n    jiLoad(jiActive);\r\n  }catch(err){toast(err.message||'Could not save changes.');}\r\n}\r\n\r\nasync function jiApprove(id){\r\n  const target=id||(jiCurrent&&jiCurrent.id);\r\n  if(!target)return;\r\n  if(!confirm('Publish this job to the live CivilCareer jobs list?'))return;\r\n  try{\r\n    await api('/api/job-collector?action=approve',{method:'POST',key:adminKey,body:JSON.stringify({id:target})});\r\n    toast('Published to the live jobs list ✓');\r\n    jiCloseDetail();\r\n    await jiLoad(jiActive);\r\n    await jcLoadBatches();\r\n  }catch(err){\r\n    if(err.status===409&&/duplicate/i.test(err.message||'')){\r\n      if(confirm(err.message+'\\n\\nPublish anyway?')){\r\n        try{\r\n          await api('/api/job-collector?action=approve',{method:'POST',key:adminKey,body:JSON.stringify({id:target,confirm_duplicate:true})});\r\n          toast('Published with the duplicate confirmed.');\r\n          jiCloseDetail();\r\n          await jiLoad(jiActive);\r\n          await jcLoadBatches();\r\n        }catch(e2){toast(e2.message||'Could not publish.');}\r\n      }\r\n      return;\r\n    }\r\n    toast(err.message||'Could not publish.');\r\n  }\r\n}\r\n\r\nasync function jiReject(id){\r\n  const target=id||(jiCurrent&&jiCurrent.id);\r\n  if(!target)return;\r\n  const answer=prompt('Why is this job rejected?\\n\\n'+JC_REJECT_REASONS.map(function(r,i){return (i+1)+') '+r;}).join('\\n'),'1');\r\n  if(answer===null)return;\r\n  const idx=Number(answer)-1;\r\n  const reason=(idx>=0&&idx<JC_REJECT_REASONS.length)?JC_REJECT_REASONS[idx]:(answer.trim()||'Other');\r\n  try{\r\n    await api('/api/job-collector?action=reject',{method:'POST',key:adminKey,body:JSON.stringify({id:target,reason:reason})});\r\n    toast('Rejected — kept for the audit log.');\r\n    jiCloseDetail();\r\n    await jiLoad(jiActive);\r\n    await jcLoadBatches();\r\n  }catch(err){toast(err.message||'Could not reject.');}\r\n}\r\n\r\n/* TABS */\r\n\r\ndocument\r\n  .querySelectorAll('#tabs button')\r\n  .forEach(b=>{\r\n\r\n    b.onclick=()=>{\r\n\r\n      document\r\n        .querySelectorAll('#tabs button')\r\n        .forEach(x=>\r\n          x.classList.remove('active')\r\n        );\r\n\r\n      document\r\n        .querySelectorAll('.panel')\r\n        .forEach(x=>\r\n          x.classList.remove('active')\r\n        );\r\n\r\n      b.classList.add('active');\r\n\r\n      $('panel-'+b.dataset.tab)\r\n        .classList.add('active');\r\n\r\n      if(b.dataset.tab==='collector'){\r\n        jcLoadBatches();\r\n        if(!jcSetupDone){jcSetupDone=true;jcCheckSetup();}\r\n      }\r\n\r\n      if(b.dataset.tab==='inbox')jiLoad(jiActive);\r\n    };\r\n  });\r\n\r\n/* Phase 2 security: admin keys are kept only in page memory. Reloading requires a fresh login. */\r\n\r\n/* ── Free civil-job scan from Agent Reach ───────────────────────────── */\r\nasync function arRunJobScan(){\r\n  const btn=$('arJobScanBtn');\r\n  const status=$('arJobScanStatus');\r\n  if(!btn||!status)return;\r\n  btn.disabled=true;\r\n  btn.textContent='⏳ Scanning…';\r\n  status.style.display='block';\r\n  status.textContent='Checking free public feeds and company career pages…';\r\n  try{\r\n    const data=await api('/api/jobs?discovery=1',{\r\n      method:'POST',\r\n      body:JSON.stringify({q:'civil engineering jobs India',location:'India',type:'all',limit:40})\r\n    });\r\n    const count=Number(data.count||0);\r\n    const sourceCount=Object.values(data.sourceStats||{}).reduce((n,v)=>n+(v&&v.ok?Number(v.items||0):0),0);\r\n    status.textContent=count\r\n      ?`✅ ${count} new draft${count===1?'':'s'} added to the review queue. ${sourceCount} raw listing${sourceCount===1?'':'s'} scanned.`\r\n      :`✓ Scan completed. ${sourceCount} raw listing${sourceCount===1?'':'s'} were checked; no new CivilCareer drafts were created. Open Discovery → Source Status for the exact reason by source.`;\r\n    await loadAgentReach();\r\n    toast(`Civil job scan complete — ${count} new draft${count===1?'':'s'}.`);\r\n  }catch(err){\r\n    status.textContent='❌ '+(err.message||'Civil job scan failed');\r\n  }finally{\r\n    btn.disabled=false;\r\n    btn.textContent='▶ Scan Civil Jobs';\r\n  }\r\n}\r\n\r\n/* ── Exam Alerts Scanner ─────────────────────────────────────────── */\r\n\r\nasync function arRunExamScan() {\r\n  const btn = $('arExamScanBtn');\r\n  const status = $('arExamScanStatus');\r\n  const results = $('arExamScanResults');\r\n\r\n  btn.disabled = true;\r\n  btn.textContent = '⏳ Scanning…';\r\n  status.style.display = 'block';\r\n  status.textContent = 'Connecting to government portals…';\r\n  results.style.display = 'none';\r\n  results.innerHTML = '';\r\n\r\n  try {\r\n    const data = await api('/api/exam-alerts', {});\r\n\r\n    status.textContent = `✅ Done in ${data.durationMs ? (data.durationMs / 1000).toFixed(1) + 's' : '—'} · ${data.totalNew} new exam${data.totalNew !== 1 ? 's' : ''} added`;\r\n\r\n    if (data.sources && data.sources.length) {\r\n      results.style.display = 'block';\r\n      results.innerHTML = data.sources.map(s =>\r\n        `<div style=\"display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.06);font-size:.8rem\">\r\n          <span style=\"color:#94a3b8\">${esc(s.name)}</span>\r\n          <span style=\"color:${s.error ? '#fca5a5' : '#6ee7b7'}\">\r\n            ${s.error ? '⚠ ' + esc(s.error) : `${s.found} found · ${s.saved} saved`}\r\n          </span>\r\n        </div>`\r\n      ).join('');\r\n    }\r\n\r\n    if (data.totalNew > 0) {\r\n      // Refresh exams array so Exams tab shows new drafts\r\n      try {\r\n        exams = (await authedApi('/api/exams?auth=1', {})).exams || [];\r\n        loadAdminExams();\r\n      } catch (_) { /* non-fatal */ }\r\n    }\r\n\r\n    toast(`Exam scan complete — ${data.totalNew} new draft${data.totalNew !== 1 ? 's' : ''} added.`);\r\n  } catch (err) {\r\n    status.textContent = '❌ ' + (err.message || 'Scan failed');\r\n  } finally {\r\n    btn.disabled = false;\r\n    btn.textContent = '▶ Scan Now';\r\n  }\r\n}\r\n\r\n/* ── YouTube Transcriber ─────────────────────────────────────────── */\r\n\r\nasync function arRunYtTranscribe() {\r\n  const urlInput  = $('arYtUrl');\r\n  const titleInput = $('arYtTitle');\r\n  const catSelect  = $('arYtCategory');\r\n  const btn        = $('arYtBtn');\r\n  const status     = $('arYtStatus');\r\n  const preview    = $('arYtPreview');\r\n\r\n  const url = (urlInput.value || '').trim();\r\n  if (!url) {\r\n    status.style.display = 'block';\r\n    status.textContent = '⚠ Please enter a YouTube URL first.';\r\n    return;\r\n  }\r\n\r\n  btn.disabled = true;\r\n  btn.textContent = '⏳ Transcribing…';\r\n  status.style.display = 'block';\r\n  status.textContent = 'Fetching captions from YouTube…';\r\n  preview.style.display = 'none';\r\n  preview.innerHTML = '';\r\n\r\n  try {\r\n    const body = { url };\r\n    if (titleInput.value.trim()) body.title = titleInput.value.trim();\r\n    if (catSelect.value) body.category = catSelect.value;\r\n\r\n    const data = await api('/api/youtube-materials', {\r\n      method: 'POST',\r\n      key: adminKey,\r\n      body: JSON.stringify(body),\r\n    });\r\n\r\n    const s = data.stats || {};\r\n    status.textContent = '✅ Transcript saved as draft';\r\n    preview.style.display = 'block';\r\n    preview.innerHTML =\r\n      `<strong style=\"color:#e2e8f0\">${esc(s.title)}</strong><br>` +\r\n      `<span style=\"color:#64748b\">Channel: </span><span>${esc(s.channel)}</span>&ensp;` +\r\n      `<span style=\"color:#64748b\">Duration: </span><span>${esc(s.duration)}</span>&ensp;` +\r\n      `<span style=\"color:#64748b\">Words: </span><span>${(s.transcriptWords || 0).toLocaleString()}</span>`;\r\n\r\n    // Clear inputs\r\n    urlInput.value = '';\r\n    titleInput.value = '';\r\n    catSelect.value = '';\r\n\r\n    // Refresh materials tab\r\n    try {\r\n      materials = (await authedApi('/api/materials?auth=1', {})).materials || [];\r\n      loadAdminMaterials();\r\n    } catch (_) { /* non-fatal */ }\r\n\r\n    toast('Transcript saved — check Materials tab for draft.');\r\n  } catch (err) {\r\n    status.textContent = '❌ ' + (err.message || 'Transcription failed');\r\n  } finally {\r\n    btn.disabled = false;\r\n    btn.textContent = '▶ Transcribe';\r\n  }\r\n}\r\n</script>\r\n\r\n\r\n<script id=\"admin-jobs-bulk-script\">\r\nconst selectedAdminJobIds = new Set();\r\nfunction syncAdminJobSelection(){\r\n  document.querySelectorAll('.admin-job-select').forEach(cb=>cb.checked=selectedAdminJobIds.has(cb.value));\r\n  const countEl=document.getElementById('admin-jobs-selected-count');\r\n  const deleteBtn=document.getElementById('admin-jobs-delete-selected');\r\n  const selectAll=document.getElementById('admin-jobs-select-all');\r\n  const boxes=[...document.querySelectorAll('.admin-job-select')];\r\n  const checked=boxes.filter(x=>x.checked).length;\r\n  if(countEl) countEl.textContent=`${selectedAdminJobIds.size} selected`;\r\n  if(deleteBtn) deleteBtn.disabled=selectedAdminJobIds.size===0;\r\n  if(selectAll){selectAll.checked=boxes.length>0&&checked===boxes.length;selectAll.indeterminate=checked>0&&checked<boxes.length;}\r\n}\r\nfunction toggleSelectedJob(cb){\r\n  if(cb.checked) selectedAdminJobIds.add(cb.value); else selectedAdminJobIds.delete(cb.value);\r\n  syncAdminJobSelection();\r\n}\r\nfunction toggleSelectAllAdminJobs(cb){\r\n  document.querySelectorAll('.admin-job-select').forEach(box=>{box.checked=cb.checked;if(cb.checked)selectedAdminJobIds.add(box.value);else selectedAdminJobIds.delete(box.value);});\r\n  syncAdminJobSelection();\r\n}\r\nasync function deleteSelectedAdminJobs(){\r\n  const ids=[...selectedAdminJobIds];\r\n  if(!ids.length)return;\r\n  if(!confirm(`Delete ${ids.length} selected job${ids.length===1?'':'s'}? They will move to Deleted.`))return;\r\n  try{\r\n    await api('/api/jobs',{method:'DELETE',key:adminKey,body:JSON.stringify({ids})});\r\n    selectedAdminJobIds.clear();\r\n    toast(`${ids.length} job${ids.length===1?'':'s'} moved to Deleted.`);\r\n    await loadAll(ccJobsPage||1);\r\n  }catch(err){toast(err.message||'Selected jobs could not be deleted');}\r\n}\r\ndocument.addEventListener('DOMContentLoaded',()=>{\r\n  document.getElementById('admin-jobs-select-all')?.addEventListener('change',e=>toggleSelectAllAdminJobs(e.target));\r\n  document.getElementById('admin-jobs-delete-selected')?.addEventListener('click',deleteSelectedAdminJobs);\r\n  syncAdminJobSelection();\r\n});\r\n</script>\r\n\r\n<script>\r\n/* ═══════════════════════════════════════\r\n   REVIEW JOBS SYSTEM\r\n   ═══════════════════════════════════════ */\r\nlet rjActiveTab='review', rjPage=1;\r\nconst rjLimit=50;\r\n\r\nasync function rjLoadTab(tab){\r\n  rjActiveTab=tab; rjPage=1;\r\n  document.querySelectorAll('.rj-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.rjtab===tab));\r\n  $('rjList').innerHTML='<p style=\"color:#6a8aaa;font-size:.85rem;padding:1rem 0\">Loading…</p>';\r\n  $('rjSelAll').checked=false; $('rjSelCount').textContent='0 selected';\r\n  await rjFetch(tab,1);\r\n}\r\n\r\nasync function rjFetch(tab,page){\r\n  try{\r\n    const s=($('rjSearch').value||'').trim();\r\n    const url='/api/admin-jobs?tab='+tab+'&page='+page+'&limit='+rjLimit+(s?'&search='+encodeURIComponent(s):'')+'&key='+encodeURIComponent(adminKey);\r\n    const res=await fetch(url);\r\n    const data=await res.json();\r\n    const jobs=data.jobs||[];\r\n    const total=data.total||0;\r\n    if(tab==='review') $('rjReviewCount').textContent='('+total+')';\r\n    if(tab==='published') $('rjPubCount').textContent='('+total+')';\r\n    if(tab==='deleted') $('rjDelCount').textContent='('+total+')';\r\n    rjRender(jobs,total,page);\r\n  }catch(e){\r\n    $('rjList').innerHTML='<p style=\"color:#fca5a5;font-size:.85rem\">Error: '+e.message+'</p>';\r\n  }\r\n}\r\n\r\nfunction rjRender(jobs,total,page){\r\n  if(!jobs.length){\r\n    $('rjList').innerHTML='<p style=\"color:#6a8aaa;padding:1rem 0\">No jobs found.</p>';\r\n    $('rjPager').innerHTML=''; return;\r\n  }\r\n  $('rjList').innerHTML=jobs.map(j=>{\r\n    const tg=j.telegram_posted\r\n      ?'<span class=\"rj-tg-badge\">📢 TG</span>'\r\n      :'<span class=\"rj-tg-badge rj-tg-no\">Not sent</span>';\r\n    const dl=j.deadline?'· ⏰ '+j.deadline:'';\r\n    const src=j.source_name?'· 📡 '+j.source_name:'';\r\n    const vac=j.vacancy_count?'· 👥 '+j.vacancy_count+' posts':'';\r\n    return '<div class=\"rj-item\" id=\"rji-'+j.id+'\">'\r\n      +'<input type=\"checkbox\" class=\"rj-cb\" value=\"'+j.id+'\" onchange=\"rjUpdSel()\">'\r\n      +'<div class=\"rj-item-body\">'\r\n      +'<h4>'+(j.role||'Untitled').replace(/</g,'&lt;')+' '+tg+'</h4>'\r\n      +'<p>'+(j.company||'').replace(/</g,'&lt;')+' · '+(j.sector||'')+' · '+(j.location||'India').replace(/</g,'&lt;')+' '+dl+' '+vac+' '+src+'</p>'\r\n      +'<div class=\"rj-item-actions\">'\r\n      +(rjActiveTab!=='published'?'<button class=\"btn-publish\" onclick=\"rjOne(\\'publish\\',\\''+j.id+'\\')\">✅ Publish</button>':'')\r\n      +(rjActiveTab==='published'?'<button class=\"btn-ghost\" style=\"font-size:.73rem\" onclick=\"rjOne(\\'reject\\',\\''+j.id+'\\')\">Unpublish</button>':'')\r\n      +(rjActiveTab!=='deleted'?'<button class=\"btn-reject\" onclick=\"rjOne(\\'delete\\',\\''+j.id+'\\')\">🗑 Delete</button>':'')\r\n      +(rjActiveTab==='deleted'?'<button class=\"btn-ghost\" style=\"font-size:.73rem\" onclick=\"rjOne(\\'restore\\',\\''+j.id+'\\')\">↩ Restore</button>':'')\r\n      +(j.source_url?'<a class=\"btn-open-src\" href=\"'+j.source_url+'\" target=\"_blank\" rel=\"noopener noreferrer\">View Source ↗</a>':'')\r\n      +'</div></div></div>';\r\n  }).join('');\r\n\r\n  const pages=Math.ceil(total/rjLimit);\r\n  $('rjPager').innerHTML=pages>1\r\n    ?'<button class=\"btn-ghost\" '+(page<=1?'disabled':'')+' onclick=\"rjGoPage('+(page-1)+')\">← Prev</button>'\r\n    +'<span style=\"color:#6a8aaa;font-size:.82rem\">Page '+page+' of '+pages+' · '+total+' jobs</span>'\r\n    +'<button class=\"btn-ghost\" '+(page>=pages?'disabled':'')+' onclick=\"rjGoPage('+(page+1)+')\">Next →</button>'\r\n    :'<span style=\"color:#6a8aaa;font-size:.78rem\">'+total+' job'+(total!==1?'s':'')+'</span>';\r\n}\r\n\r\nfunction rjGoPage(p){rjPage=p;rjFetch(rjActiveTab,p);}\r\nfunction rjFilterList(){clearTimeout(rjFilterList._t);rjFilterList._t=setTimeout(()=>rjFetch(rjActiveTab,1),400);}\r\nfunction rjToggleAll(c){document.querySelectorAll('.rj-cb').forEach(cb=>cb.checked=c);rjUpdSel();}\r\nfunction rjUpdSel(){const n=document.querySelectorAll('.rj-cb:checked').length;$('rjSelCount').textContent=n+' selected';}\r\nfunction rjGetSel(){return[...document.querySelectorAll('.rj-cb:checked')].map(cb=>cb.value);}\r\nasync function rjOne(action,id){await rjDoAction(action,[id]);}\r\nasync function rjBulk(action){\r\n  const ids=rjGetSel();\r\n  if(!ids.length){toast('Select at least one job first.');return;}\r\n  await rjDoAction(action,ids);\r\n}\r\nasync function rjDoAction(action,ids){\r\n  try{\r\n    const res=await fetch('/api/admin-jobs',{\r\n      method:'POST',\r\n      headers:{'Content-Type':'application/json'},\r\n      body:JSON.stringify({key:adminKey,action,ids})\r\n    });\r\n    const data=await res.json();\r\n    const label={publish:'Published',reject:'Rejected',delete:'Deleted',restore:'Restored'}[action]||action;\r\n    toast(label+' '+data.affected+' job'+(data.affected!==1?'s':'')+' ✓');\r\n    if(action==='publish') toast('📢 Posting to Telegram…');\r\n    await rjFetch(rjActiveTab,rjPage);\r\n    $('rjSelAll').checked=false; $('rjSelCount').textContent='0 selected';\r\n  }catch(e){toast('Error: '+e.message);}\r\n}\r\nasync function rjRunScraper(){\r\n  const btn=$('rjScraperBtn');\r\n  btn.disabled=true; btn.textContent='⏳ Scraping…';\r\n  try{\r\n    const res=await fetch('/api/civil-scraper',{\r\n      method:'POST',\r\n      headers:{'Content-Type':'application/json'},\r\n      body:JSON.stringify({key:adminKey})\r\n    });\r\n    const data=await res.json();\r\n    toast('Scraper done — '+(data.new_jobs_saved||0)+' new jobs saved for review ✓');\r\n    if(rjActiveTab==='review') await rjFetch('review',1);\r\n  }catch(e){toast('Scraper error: '+e.message);}\r\n  finally{btn.disabled=false;btn.textContent='🔍 Run Scraper Now';}\r\n}\r\n\r\n/* ════════════════════════════════════════════════════════════════════\r\n   GOVERNMENT JOBS → CIVIL ENGINEERING (admin section)\r\n   Every mutation goes through /api/govt-review, which enforces the\r\n   mandatory human-review publication gate server-side. The UI can only\r\n   request actions — it can never mark anything reviewed by itself.\r\n   ════════════════════════════════════════════════════════════════════ */\r\n\r\nlet govtActiveTab='inbox';\r\nlet govtCache={inbox:[],drafts:[],published:[],archived:[],review:[],orgs:[],cats:[],sources:[],conflicts:[],providers:[]};\r\nlet govtLoadedOnce=false;\r\n\r\nfunction govtEsc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;')}\r\nfunction govtAdminApi(url,opt={}){\r\n  const headers={'Content-Type':'application/json',...(adminKey?{Authorization:'Bearer '+adminKey}:{}) ,...(opt.headers||{})};\r\n  return fetch(url,{...opt,headers}).then(async r=>{\r\n    const t=await r.text(); let d={}; try{d=t?JSON.parse(t):{}}catch{}\r\n    if(!r.ok){const e=Error(d.error||('Request failed ('+r.status+')'));e.status=r.status;throw e;}\r\n    return d;\r\n  });\r\n}\r\nasync function govtPost(action,body){\r\n  return govtAdminApi('/api/govt-review?action='+action,{method:'POST',body:JSON.stringify(body||{})});\r\n}\r\n\r\nfunction govtSwitchTab(tab){\r\n  govtActiveTab=tab;\r\n  document.querySelectorAll('#govtTabs button').forEach(b=>b.classList.toggle('active',b.dataset.gtab===tab));\r\n  document.querySelectorAll('#panel-govt .govt-sub').forEach(s=>s.classList.toggle('active',s.dataset.gsub===tab));\r\n}\r\n\r\nasync function govtLoad(tab){\r\n  govtSwitchTab(tab);\r\n  try{\r\n    if(tab==='inbox'){\r\n      const kind=$('govtInboxKind').value;\r\n      const status='pending,needs_info';\r\n      const d=await govtAdminApi('/api/govt-review?status='+encodeURIComponent(status)+(kind?'&kind='+encodeURIComponent(kind):''));\r\n      govtCache.inbox=d.items||[];\r\n      $('govtCountInbox').textContent='('+govtCache.inbox.length+')';\r\n      govtRenderInbox();\r\n    } else if(tab==='drafts'||tab==='published'||tab==='archived'){\r\n      const statusMap={drafts:'draft',published:'active',archived:'archived'};\r\n      const d=await govtAdminApi('/api/govt-review?action=saved_jobs&status='+statusMap[tab]+'&limit=200');\r\n      govtCache[tab]=d.jobs||[];\r\n      $('govtCount'+tab.charAt(0).toUpperCase()+tab.slice(1)).textContent='('+govtCache[tab].length+')';\r\n      govtRenderSaved(tab);\r\n    } else if(tab==='review'){\r\n      const st=$('govtReviewStatus').value;\r\n      const d=await govtAdminApi('/api/govt-review?status='+encodeURIComponent(st));\r\n      govtCache.review=d.items||[];\r\n      govtRenderReview();\r\n    } else if(tab==='organizations'){\r\n      const d=await govtAdminApi('/api/govt-review?action=organizations');\r\n      govtCache.orgs=d.organizations||[];\r\n      govtRenderOrgs();\r\n    } else if(tab==='categories'){\r\n      const d=await govtAdminApi('/api/govt-review?action=categories');\r\n      govtCache.cats=d.categories||[];\r\n      govtRenderCats();\r\n    } else if(tab==='sources'){\r\n      const d=await govtAdminApi('/api/govt-review?action=health');\r\n      govtCache.sources=d.sources||[];\r\n      govtCache.pipeline=d.pipeline||null;\r\n      govtRenderSources();\r\n    } else if(tab==='conflicts'){\r\n      const d=await govtAdminApi('/api/govt-review?action=conflicts');\r\n      govtCache.conflicts=d.conflicts||[];\r\n      $('govtCountConflicts').textContent='('+govtCache.conflicts.length+')';\r\n      govtRenderConflicts();\r\n    } else if(tab==='providers'){\r\n      const d=await govtAdminApi('/api/govt-review?action=ai-providers');\r\n      govtCache.providers=d.providers||[];\r\n      govtRenderProviders();\r\n    }\r\n    govtLoadedOnce=true;\r\n    govtFilter();\r\n  }catch(e){\r\n    const map={inbox:'govtListInbox',drafts:'govtListDrafts',published:'govtListPublished',archived:'govtListArchived',review:'govtListReview',organizations:'govtListOrgs',categories:'govtListCats',sources:'govtListSources',conflicts:'govtListConflicts',providers:'govtListProviders'};\r\n    const el=$(map[tab]); if(el)el.innerHTML='<p style=\"color:#fca5a5;font-size:.85rem\">'+govtEsc(e.message)+'</p>';\r\n  }\r\n}\r\n\r\nfunction govtRefreshAll(){govtLoad(govtActiveTab);}\r\n\r\n/* Saved govt_jobs rows (drafts / published / archived) come from the\r\n   same govt-review API so every read is admin-gated. */\r\nasync function govtFetchSaved(status){\r\n  const d=await govtAdminApi('/api/govt-review?action=saved_jobs&status='+encodeURIComponent(status)+'&limit=200');\r\n  return d.jobs||[];\r\n}\r\n\r\nfunction govtKindBadge(kind){\r\n  const labels={new:'NEW',updated:'UPDATED',closing_date_changed:'DATE CHANGED',result:'RESULT',admit_card:'ADMIT CARD',other_update:'UPDATE'};\r\n  return '<span class=\"govt-badge kind-'+govtEsc(kind||'other_update')+'\">'+govtEsc(labels[kind]||'UPDATE')+'</span>';\r\n}\r\nfunction govtVerifBadge(st){\r\n  const official=st==='official';\r\n  return '<span class=\"govt-badge st-'+govtEsc(official?'official':'unverified')+'\">'+(official?'🛡 Official source':'⚠ Unofficial source')+'</span>';\r\n}\r\n\r\nfunction govtRenderInbox(){\r\n  const el=$('govtListInbox');\r\n  if(!govtCache.inbox.length){el.innerHTML='<p class=\"govt-empty\">Inbox zero — no AI-found updates waiting. New discoveries appear here after each crawl.</p>';return;}\r\n  el.innerHTML=govtCache.inbox.map(it=>{\r\n    const p=it.payload||{};\r\n    const official=(p.source_type||'')==='official';\r\n    const aiCount=(it.ai_extractions||[]).length;\r\n    return '<div class=\"govt-item\" data-search=\"'+govtEsc((p.title||'')+' '+(p.organization||'')).toLowerCase()+'\">'\r\n      +'<h4>'+govtKindBadge(it.inbox_kind)+' '+govtEsc(p.title||'(untitled)')+'</h4>'\r\n      +'<p>'+govtEsc(p.organization||'')+(p.state?' · '+govtEsc(p.state):'')+(p.deadline&&p.deadline.date?' · closes '+govtEsc(p.deadline.date):'')+' · '+(official?'official source':'discovery lead')+(aiCount?' · '+aiCount+' AI extraction(s)':'')+'</p>'\r\n      +'<div class=\"govt-actions\">'\r\n      +'<button class=\"btn-review\" onclick=\"govtOpenInbox(\\''+it.id+'\\')\">🔍 Review</button>'\r\n      +'<button class=\"btn-publish\" onclick=\"govtApprove(\\''+it.id+'\\')\">✅ Review &amp; Publish</button>'\r\n      +'<button class=\"btn-ghost\" onclick=\"govtAiStructure(\\''+it.id+'\\',this)\">🧠 AI Structure</button>'\r\n      +'<button class=\"btn-ghost\" onclick=\"govtNeedsInfo(\\''+it.id+'\\')\">❓ Needs Info</button>'\r\n      +'<button class=\"btn-reject\" onclick=\"govtReject(\\''+it.id+'\\')\">✕ Reject</button>'\r\n      +(p.source_url?'<a class=\"btn-open-src\" href=\"'+govtEsc(p.source_url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Source ↗</a>':'')\r\n      +'</div></div>';\r\n  }).join('');\r\n}\r\n\r\nfunction govtRenderSaved(tab){\r\n  const map={drafts:'govtListDrafts',published:'govtListPublished',archived:'govtListArchived'};\r\n  const el=$(map[tab]); const list=govtCache[tab]||[];\r\n  if(!list.length){el.innerHTML='<p class=\"govt-empty\">No '+tab+' government jobs.</p>';return;}\r\n  el.innerHTML=list.map(j=>{\r\n    const actions=[];\r\n    actions.push('<button class=\"btn-review\" onclick=\"govtOpenSaved(\\''+j.id+'\\')\">🔍 Details &amp; Edit</button>');\r\n    if(tab==='drafts'){\r\n      actions.push('<button class=\"btn-publish\" onclick=\"govtPublishDraft(\\''+j.id+'\\')\">✅ Publish</button>');\r\n    }\r\n    if(tab==='published'){\r\n      actions.push('<button class=\"btn-ghost\" onclick=\"govtAction(\\''+j.id+'\\',\\'unpublish\\')\">Unpublish</button>');\r\n      actions.push('<button class=\"btn-ghost\" onclick=\"govtAction(\\''+j.id+'\\',\\'mark_verified\\')\">🛡 Mark Verified</button>');\r\n      actions.push('<button class=\"btn-ghost\" onclick=\"govtAction(\\''+j.id+'\\',\\'mark_expired\\')\">⏰ Mark Expired</button>');\r\n    }\r\n    if(tab!=='archived'){\r\n      actions.push('<button class=\"btn-ghost\" onclick=\"govtAction(\\''+j.id+'\\',\\'archive\\')\">🗄 Archive</button>');\r\n    } else {\r\n      actions.push('<button class=\"btn-ghost\" onclick=\"govtAction(\\''+j.id+'\\',\\'restore\\')\">↩ Restore</button>');\r\n      actions.push('<button class=\"btn-reject\" onclick=\"govtAction(\\''+j.id+'\\',\\'delete_permanent\\')\">🗑 Delete Forever</button>');\r\n    }\r\n    actions.push('<button class=\"btn-ghost\" onclick=\"govtDuplicate(\\''+j.id+'\\')\">⧉ Duplicate</button>');\r\n    if(j.official_notification_url)actions.push('<a class=\"btn-open-src\" href=\"'+govtEsc(j.official_notification_url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Notification ↗</a>');\r\n    const verif=govtVerifBadge(j.verification_status)+(j.human_reviewed?'':' <span class=\"govt-badge\">⏳ NOT human-reviewed</span>');\r\n    /* Same columns the queue and the six feeds use, so a published row is readable\r\n       without opening it: post, qualification, last date, and the feed that found it. */\r\n    const feed=govtFeedName(j.official_site_url||j.official_notification_url||j.official_notice_url);\r\n    const facts=[j.post_name?'Post: '+govtEsc(String(j.post_name).slice(0,90)):'',j.qualification?'Qualification: '+govtEsc(String(j.qualification).slice(0,110)):'',j.notification_no?'Advt no. '+govtEsc(String(j.notification_no).slice(0,40)):''].filter(Boolean).join(' · ');\r\n    return '<div class=\"govt-item\" data-search=\"'+govtEsc((j.title||'')+' '+(j.organization||'')).toLowerCase()+'\">'\r\n      +'<h4>'+govtEsc(j.title||'(untitled)')+' '+verif+(feed?' <span class=\"govt-badge\">via '+govtEsc(feed)+'</span>':'')+'</h4>'\r\n      +'<p>'+govtEsc(j.organization||'')+(j.state?' · '+govtEsc(j.state):'')+(j.gov_level?' · '+govtEsc(j.gov_level):'')+(j.apply_end?' · closes '+govtEsc(j.apply_end):'')+'</p>'\r\n      +(facts?'<p style=\"color:#cbd5e1\">'+facts+'</p>':'')\r\n      +'<div class=\"govt-actions\">'+actions.join('')+'</div></div>';\r\n  }).join('');\r\n}\r\n\r\n/* The six feeds the pipeline is built on, in the order config/govt-sources.json lists\r\n   them. Used to label which feed first surfaced a published notification. */\r\nconst GOVT_FEED_HOSTS=[['govtjobguru.in','govtjobguru'],['karnatakacareers.org','Karnataka Careers'],['linkingsky.com','Linking Sky'],['allgovernmentjobs.in','All Government Jobs'],['freejobalert.com','FreeJobAlert'],['ka.indgovtjobs.net','KA IndGovtJobs']];\r\nfunction govtFeedName(url){\r\n  let h='';\r\n  try{h=new URL(String(url||'')).hostname.toLowerCase().replace(/^www\\./,'')}catch(e){return ''}\r\n  const f=GOVT_FEED_HOSTS.find(x=>h===x[0]||h.endsWith('.'+x[0]));\r\n  return f?f[1]:'';\r\n}\r\n\r\n/* Same host rule the publish gate applies (_api/govt-review.js isOfficialHost):\r\n   .gov.in / .nic.in / .edu.in plus the known PSU hosts. One function, so the queue and\r\n   the backend can never disagree about what counts as an official notice. */\r\nfunction govtIsOfficialUrl(u){\r\n  try{\r\n    const url=new URL(String(u||''));\r\n    if(url.protocol!=='https:')return false;\r\n    const h=url.hostname.toLowerCase().replace(/^www\\./,'');\r\n    return /(^|\\.)(gov|nic|edu)\\.in$/.test(h)||/(^|\\.)(bhel\\.com|ntpc\\.co\\.in|rites\\.com|ircon\\.org|aai\\.aero|nhpcindia\\.com|nbccindia\\.com|coalindia\\.in|indianrailways\\.gov\\.in|irc\\.org\\.in)$/.test(h);\r\n  }catch(e){return false;}\r\n}\r\n\r\n/* The six feeds publish the same columns (Organization, Post, Qualification, Advt no,\r\n   Last date, Posted), so the queue shows those columns rather than a sentence — the\r\n   reviewer can hold the row up against the feed it came from. */\r\nfunction govtFeedColumns(p){\r\n  p=p||{};\r\n  const post=p.post_name||(Array.isArray(p.post_candidates)&&p.post_candidates[0]&&p.post_candidates[0].post_name)||'';\r\n  const deadline=(p.deadline&&(p.deadline.date||p.deadline.text))||'';\r\n  return [\r\n    ['Feed',p.source_name||''],\r\n    ['Organization',p.organization||''],\r\n    ['Post',post],\r\n    ['Qualification',p.qualification||''],\r\n    ['Advt no.',p.notification_no||''],\r\n    ['Posts',p.vacancies||''],\r\n    ['Last date',deadline],\r\n    ['Posted',p.posted_on||''],\r\n    ['Feed section',p.source_section||''],\r\n  ].filter(r=>r[1]);\r\n}\r\nfunction govtFeedTable(p){\r\n  const rows=govtFeedColumns(p);\r\n  if(!rows.length)return '';\r\n  return '<div class=\"govt-feed-grid\">'+rows.map(r=>'<div class=\"rm-field\"><span class=\"rm-label\">'+govtEsc(r[0])+'</span><span class=\"rm-value\">'+govtEsc(String(r[1]).slice(0,180))+'</span></div>').join('')+'</div>';\r\n}\r\n\r\n/* Three of the six feeds (karnatakacareers, allgovernmentjobs, linkingsky) publish no\r\n   official notice link at all, so those leads can never be published until a human\r\n   supplies the URL from the department's own site. That is this control — and the\r\n   backend validates the pasted URL against the same host rule before it is stored. */\r\nfunction govtNoticeAttachHtml(id,p,inputId){\r\n  p=p||{};\r\n  if(govtIsOfficialUrl(p.official_notice_url)){\r\n    return '<a class=\"btn-open-src\" href=\"'+govtEsc(p.official_notice_url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">🛡 Official notice ↗</a>';\r\n  }\r\n  return '<span class=\"govt-notice-paste\"><input id=\"'+govtEsc(inputId)+'\" type=\"url\" placeholder=\"Paste the official notice URL (govt / PSU)\">'\r\n    +'<button class=\"btn-ghost\" onclick=\"govtAttachNotice(\\''+govtEsc(id)+'\\',\\''+govtEsc(inputId)+'\\')\">🔗 Attach</button></span>'\r\n    +(p.official_notice_url?'<a class=\"btn-open-src\" href=\"'+govtEsc(p.official_notice_url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Notice (unverified) ↗</a>':'');\r\n}\r\nasync function govtAttachNotice(id,inputId){\r\n  const el=$(inputId||('govtNoticeInput-'+id));\r\n  const v=el?String(el.value||'').trim():'';\r\n  if(!v){toast('Paste the official notice URL first.');return;}\r\n  if(!govtIsOfficialUrl(v)){toast('That is not an official government/PSU URL — an aggregator page can never be the notice.');return;}\r\n  try{\r\n    await govtPost('attach_notice',{id,official_notice_url:v});\r\n    toast('Official notice attached ✓ — review the row, then Approve.');\r\n    govtLoad(govtActiveTab);\r\n  }catch(e){toast('Could not attach: '+e.message);}\r\n}\r\n\r\nfunction govtRenderReview(){\r\n  const el=$('govtListReview'); const list=govtCache.review||[];\r\n  if(!list.length){el.innerHTML='<p class=\"govt-empty\">Nothing here for this status.</p>';return;}\r\n  /* Bulk review. Six aggregator feeds can add dozens of civil leads in one\r\n     crawl, and clearing them one confirm() at a time is the slowest part of\r\n     publishing. Every row carries a checkbox; the bar applies one action to the\r\n     whole selection sequentially and reports how many went through. */\r\n  el.innerHTML='<div class=\"admin-jobs-bulkbar\">'\r\n    +'<label><input type=\"checkbox\" id=\"govtBulkAll\" onchange=\"govtBulkSelectAll(this.checked)\"> Select all</label>'\r\n    +'<span class=\"admin-jobs-selected-count\" id=\"govtBulkCount\">0 selected</span>'\r\n    +'<button class=\"btn-publish\" onclick=\"govtBulk(\\'approve\\')\">✅ Publish selected</button>'\r\n    +'<button class=\"btn-ghost\" onclick=\"govtBulk(\\'needs_info\\')\">❓ Needs Info</button>'\r\n    +'<button class=\"btn-reject\" onclick=\"govtBulk(\\'reject\\')\">✕ Reject</button>'\r\n    +'</div>'\r\n    +list.map(it=>{\r\n    const p=it.payload||{};\r\n    /* The aggregator's OWN evidence, in the aggregator's own columns: the qualification\r\n       it published, the section it filed the posting under, the advt number and last\r\n       date it printed. Publishing is refused without a real official notice (spec §7),\r\n       so the row shows which records can go straight out and which need a pasted URL. */\r\n    const evid=p.civil_evidence?govtEsc(p.civil_evidence):'';\r\n    const meta=[p.inbox_kind?govtEsc(it.inbox_kind):'',p.excerpt?'':'',(p.deadline&&(p.deadline.date||p.deadline.text))?'closes '+(p.deadline.date||p.deadline.text):''].filter(Boolean).join(' · ');\r\n    return '<div class=\"govt-item admin-job-row\" data-search=\"'+govtEsc((p.title||'')+' '+(p.organization||'')).toLowerCase()+'\">'\r\n      +'<input type=\"checkbox\" class=\"admin-job-select govt-bulk-select\" value=\"'+govtEsc(it.id)+'\" onchange=\"govtBulkUpdate()\">'\r\n      +'<div class=\"list-item-info\">'\r\n      +'<h4>'+govtEsc(p.title||'(untitled)')+' <span class=\"govt-badge\">'+govtEsc(it.civil_status||'')+(it.tier?' · tier '+govtEsc(it.tier):'')+'</span>'+(evid?' <span class=\"govt-badge\">matched: '+evid+'</span>':'')+'</h4>'\r\n      +govtFeedTable(p)\r\n      +(meta?'<p>'+govtEsc(meta.slice(0,120))+'</p>':'')\r\n      +'<p>'+govtEsc((it.reject_reason||it.review_notes||'').slice(0,180)||('discovered '+govtEsc(String(it.created_at||'').slice(0,10))))+'</p>'\r\n      +'</div>'\r\n      +'<div class=\"govt-actions\">'\r\n      +(it.status==='pending'||it.status==='needs_info'?'<button class=\"btn-publish\" onclick=\"govtApprove(\\''+it.id+'\\')\">✅ Approve &amp; Publish</button>':'')\r\n      +(it.status!=='approved'?'<button class=\"btn-ghost\" onclick=\"govtNeedsInfo(\\''+it.id+'\\')\">❓ Needs Info</button>':'')\r\n      +(it.status!=='rejected'&&it.status!=='approved'?'<button class=\"btn-reject\" onclick=\"govtReject(\\''+it.id+'\\')\">✕ Reject</button>':'')\r\n      +(p.source_url?'<a class=\"btn-open-src\" href=\"'+govtEsc(p.source_url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Aggregator ↗</a>':'')\r\n      +govtNoticeAttachHtml(it.id,p,'govtNoticeInput-'+it.id)\r\n      +'</div></div>';\r\n  }).join('');\r\n}\r\n\r\nfunction govtBulkSelected(){\r\n  return [...document.querySelectorAll('.govt-bulk-select:checked')].map(c=>c.value);\r\n}\r\nfunction govtBulkUpdate(){\r\n  const n=govtBulkSelected().length;\r\n  const c=$('govtBulkCount'); if(c)c.textContent=n+' selected';\r\n  const all=$('govtBulkAll'); const boxes=document.querySelectorAll('.govt-bulk-select');\r\n  if(all)all.checked=boxes.length>0&&n===boxes.length;\r\n}\r\nfunction govtBulkSelectAll(on){\r\n  document.querySelectorAll('.govt-bulk-select').forEach(c=>{c.checked=!!on;});\r\n  govtBulkUpdate();\r\n}\r\nasync function govtBulk(action){\r\n  const ids=govtBulkSelected();\r\n  if(!ids.length){toast('Select at least one item first.');return;}\r\n  const verb={approve:'publish',needs_info:'mark Needs Info',reject:'reject'}[action]||action;\r\n  const warn=action==='approve'?' They become publicly visible immediately.':'';\r\n  if(!confirm(verb+' '+ids.length+' selected item(s)?'+warn))return;\r\n  let ok=0; let firstError='';\r\n  for(const id of ids){\r\n    try{\r\n      if(action==='approve')await govtPost('approve',{id});\r\n      else if(action==='reject')await govtPost('reject',{id,reason:'Bulk rejected from the review queue'});\r\n      else await govtPost('needs_info',{id,notes:'Bulk marked needs-info from the review queue'});\r\n      ok++;\r\n    }catch(e){ if(!firstError)firstError=(e.message||'failed').slice(0,90); }\r\n  }\r\n  const failed=ids.length-ok;\r\n  toast(ok+' of '+ids.length+' '+(action==='approve'?'published':'updated')+(failed?' · '+failed+' failed: '+firstError:''));\r\n  govtLoad(govtActiveTab);\r\n}\r\n\r\nfunction govtRenderOrgs(){\r\n  const el=$('govtListOrgs'); const q=($('govtOrgSearch').value||'').toLowerCase();\r\n  const list=(govtCache.orgs||[]).filter(o=>!q||String(o.name||'').toLowerCase().includes(q));\r\n  if(!list.length){el.innerHTML='<p class=\"govt-empty\">No organizations yet. Add the departments and PSUs you track.</p>';return;}\r\n  el.innerHTML=list.map(o=>'<div class=\"govt-item\"><h4>'+govtEsc(o.name)+' <span class=\"govt-badge\">'+govtEsc(o.kind||'other')+'</span></h4>'\r\n    +'<p>'+(o.website?'<a href=\"'+govtEsc(o.website)+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+govtEsc(o.website)+'</a> · ':'')+' organizations are freeform registry entries used to keep master data clean.</p>'\r\n    +'<div class=\"govt-actions\"><button class=\"btn-reject\" onclick=\"govtDeleteOrg(\\''+o.id+'\\')\">🗑 Remove</button></div></div>').join('');\r\n}\r\n\r\nfunction govtRenderCats(){\r\n  const el=$('govtListCats'); const list=govtCache.cats||[];\r\n  if(!list.length){el.innerHTML='<p class=\"govt-empty\">No categories registered (run the v28 migration seed).</p>';return;}\r\n  const groups={};\r\n  list.forEach(c=>{(groups[c.kind||'specialization']=groups[c.kind||'specialization']||[]).push(c)});\r\n  el.innerHTML=Object.entries(groups).map(([kind,items])=>\r\n    '<div class=\"govt-item\"><h4><span class=\"govt-badge\">'+govtEsc(kind)+'</span></h4><p>'\r\n    +items.map(c=>govtEsc(c.label)).join(' · ')\r\n    +'</p></div>').join('');\r\n}\r\n\r\nfunction govtSourceState(s){\r\n  const st=String(s.last_status||''), err=String(s.last_error||'');\r\n  if(!st)return {label:'not run yet',cls:'sh-nc'};\r\n  if(st.startsWith('dead:'))return {label:'⛔ retired source',cls:'sh-nc'};\r\n  if(st.startsWith('blocked:'))return {label:'⛔ blocked by the site',cls:'sh-nc'};\r\n  if(st==='ok'||st.startsWith('ok;'))return {label:'✓ healthy',cls:'sh-ok'};\r\n  if(st==='not_modified')return {label:'○ unchanged (304)',cls:'sh-nc'};\r\n  /* A 403 after the bot's own pause-and-retry is a throttle, not a broken source:\r\n     ka.indgovtjobs.net sits behind Cloudflare and refuses the declared bot agent\r\n     intermittently while serving the same page to anyone else. Showing that in red\r\n     alongside a dead source trains the owner to ignore the panel. */\r\n  const t=st.match(/^transient:http-(\\d+)/);\r\n  if(t)return {label:'⏳ throttled ('+t[1]+') — retried, will try again',cls:'sh-warn'};\r\n  const m=st.match(/^source:http-(\\d+)/);\r\n  if(m){\r\n    if(m[1]==='404'||m[1]==='410')return {label:'✗ page gone ('+m[1]+')',cls:'sh-error'};\r\n    if(m[1]==='403'||m[1]==='429')return {label:'⛔ blocked ('+m[1]+')',cls:'sh-error'};\r\n    return {label:'✗ source HTTP '+m[1],cls:'sh-error'};\r\n  }\r\n  if(st.startsWith('robots:disallowed')||st==='robots_blocked')return {label:'⛔ robots.txt disallows',cls:'sh-error'};\r\n  if(st.startsWith('robots:invalid-source-url'))return {label:'✗ bad source URL',cls:'sh-error'};\r\n  if(st.startsWith('robots:unreachable'))return {label:'⚠ robots.txt unreachable',cls:'sh-warn'};\r\n  if(st.startsWith('robots:unavailable'))return {label:'⚠ no robots.txt (allowed)',cls:'sh-warn'};\r\n  if(st.startsWith('robots:unverified'))return {label:'⚠ robots.txt unverified',cls:'sh-warn'};\r\n  if(st==='error'||/fetch failed/i.test(err)){\r\n    const c=(err.match(/\\b(403|404|410|429)\\b/)||[])[1];\r\n    if(c==='403'||c==='429')return {label:'⛔ blocked ('+c+')',cls:'sh-error'};\r\n    if(c==='404'||c==='410')return {label:'✗ page gone ('+c+')',cls:'sh-error'};\r\n    return {label:'✗ fetch failed',cls:'sh-error'};\r\n  }\r\n  return {label:st,cls:'sh-nc'};\r\n}\r\n\r\n/* Every per-source row can read \"ok\" while the pipeline has stopped producing — that is\r\n   exactly what a \"sources: 0\" sweep looks like from the panel: a tidy, empty list. This\r\n   is the one line that goes red when nothing is arriving, so a silent freeze cannot be\r\n   mistaken for a quiet day. */\r\nfunction govtPipelineBanner(){\r\n  const p=govtCache.pipeline;\r\n  if(!p)return '';\r\n  const ago=v=>v==null?'—':v+' h ago';\r\n  if(p.stalled){\r\n    return '<p class=\"govt-notice-missing\" style=\"display:block;margin:0 0 12px;font-size:.85rem\">⚠ <b>Silent freeze:</b> '+govtEsc(p.reason||'the pipeline has stopped producing')+' <span style=\"color:#6a8aaa\">(last sweep '+govtEsc(ago(p.hours_since_run))+' · last new lead '+govtEsc(ago(p.hours_since_staging))+')</span></p>';\r\n  }\r\n  return '<p class=\"discovery-summary show\" style=\"margin:0 0 12px\">✓ pipeline live · last sweep '+govtEsc(ago(p.hours_since_run))+' · last new lead '+govtEsc(ago(p.hours_since_staging))+'</p>';\r\n}\r\n\r\nfunction govtRenderSources(){\r\n  const el=$('govtListSources'); const list=govtCache.sources||[];\r\n  if(!list.length){el.innerHTML=govtPipelineBanner()+'<p class=\"govt-empty\">No discovery sources configured (config/govt-sources.json).</p>';return;}\r\n  const on=list.filter(s=>s.enabled);\r\n  const healthy=on.filter(s=>govtSourceState(s).cls==='sh-ok').length;\r\n  const failing=on.filter(s=>govtSourceState(s).cls==='sh-error').length;\r\n  const warns=on.filter(s=>govtSourceState(s).cls==='sh-warn').length;\r\n  const summary='<p class=\"discovery-summary show\" style=\"margin:0 0 12px\">'+on.length+' enabled · <span style=\"color:#6ee7b7\">'+healthy+'</span> healthy · <span style=\"color:#fca5a5\">'+failing+'</span> failing · <span style=\"color:#fbbf24\">'+warns+'</span> warning'+(warns===1?'':'s')+' · '+list.length+' total</p>';\r\n  el.innerHTML=govtPipelineBanner()+summary+list.map(s=>{\r\n    const st=govtSourceState(s);\r\n    return '<div class=\"govt-item\"><h4>'+govtEsc(s.name)+' '\r\n      +'<span class=\"govt-badge '+(s.type==='official'?'st-official':'st-unverified')+'\">'+govtEsc(s.type)+'</span> '\r\n      +'<span class=\"govt-badge '+st.cls+'\" title=\"'+govtEsc(String(s.last_status||'never run'))+'\">'+govtEsc(st.label)+'</span></h4>'\r\n      +'<p>'+(s.last_run_at?'last run '+govtEsc(String(s.last_run_at).slice(0,16).replace('T',' '))+' UTC · ':'')+govtEsc(String(s.items_found||0))+' found · '+govtEsc(String(s.items_staged||0))+' staged'\r\n      +(s.last_error?' · <span style=\"color:#fca5a5\">'+govtEsc(String(s.last_error).slice(0,120))+'</span>':'')+'</p>'\r\n      +'<div class=\"govt-actions\">'\r\n      +'<button class=\"btn-ghost\" onclick=\"govtToggleSource(\\''+s.id+'\\','+(!s.enabled)+')\">'+(s.enabled?'⏸ Disable':'▶ Enable')+'</button>'\r\n      +'<a class=\"btn-open-src\" href=\"'+govtEsc(s.url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Open ↗</a>'\r\n      +'</div></div>';\r\n  }).join('');\r\n}\r\n\r\nfunction govtRenderConflicts(){\r\n  const el=$('govtListConflicts'); const list=govtCache.conflicts||[];\r\n  if(!list.length){el.innerHTML='<p class=\"govt-empty\">No open conflicts. Diverging source values will be stored here instead of being silently resolved.</p>';return;}\r\n  el.innerHTML=list.map(c=>{\r\n    const vals=(c.values||[]).map(v=>'• <b>'+govtEsc(v.value)+'</b> ('+govtEsc(v.source_type||'source')+(v.official?' · official':'')+')').join('<br>');\r\n    return '<div class=\"govt-item\"><h4>⚔ '+govtEsc(c.field_name)+' '+(c.recruitment_id?'<span class=\"govt-badge\">published record</span>':'')+'</h4>'\r\n      +'<p>'+vals+'</p>'\r\n      +'<div class=\"govt-actions\">'\r\n      +'<button class=\"btn-publish\" onclick=\"govtResolveConflict(\\''+c.id+'\\',\\'official\\')\">🛡 Use Official</button>'\r\n      +'<button class=\"btn-ghost\" onclick=\"govtResolveConflict(\\''+c.id+'\\',\\'highest\\')\">Use Highest Confidence</button>'\r\n      +'<button class=\"btn-ghost\" onclick=\"govtResolveManual(\\''+c.id+'\\')\">Enter Manually</button>'\r\n      +'<button class=\"btn-reject\" onclick=\"govtDismissConflict(\\''+c.id+'\\')\">Dismiss</button>'\r\n      +'</div></div>';\r\n  }).join('');\r\n}\r\n\r\nfunction govtRenderProviders(){\r\n  const el=$('govtListProviders'); const list=govtCache.providers||[];\r\n  if(!list.length){el.innerHTML='<p class=\"govt-empty\">No AI providers configured. The pipeline still works with rule-based extraction; AI structuring is optional.</p>';return;}\r\n  el.innerHTML=list.map(p=>'<div class=\"govt-item\"><h4>'+govtEsc(p.label||p.id)+' '\r\n    +'<span class=\"govt-badge '+(p.configured?'st-official':'st-unverified')+'\">'+(p.configured?(p.keys+' key'+(p.keys!==1?'s':'')):'not configured')+'</span> '\r\n    +(p.onCooldown?'<span class=\"govt-badge st-unverified\">cooling down</span>':'<span class=\"govt-badge kind-new\">available</span>')+'</h4>'\r\n    +'<p>Model: '+govtEsc(p.model||'default')+'</p></div>').join('');\r\n}\r\n\r\nfunction govtFilter(){\r\n  const q=($('govtSearch').value||'').trim().toLowerCase();\r\n  document.querySelectorAll('#panel-govt .govt-sub.active .govt-item').forEach(el=>{\r\n    el.style.display=(!q||(el.dataset.search||'').includes(q))?'':'none';\r\n  });\r\n}\r\n\r\n/* ── Actions ─────────────────────────────────────────────────────────── */\r\n\r\n/* ── Review / edit modal ───────────────────────────────────────────────\r\n   The inbox button opens the staged payload read-only so a human can really\r\n   review before publishing; saved rows open an editor for the fields the\r\n   server accepts (?action=update). */\r\nconst GOVT_EDIT_FIELDS = [\r\n  ['title','Title'],\r\n  ['organization','Organization'],\r\n  ['gov_level','Level','select',['central','state','psu','railways','authority','other']],\r\n  ['state','State'],\r\n  ['department','Department'],\r\n  ['post_name','Post name'],\r\n  ['notification_no','Notification no.'],\r\n  ['qualification','Qualification'],\r\n  ['total_vacancies','Total vacancies','number'],\r\n  ['civil_vacancies','Civil vacancies','number'],\r\n  ['age_limit','Age limit'],\r\n  ['pay_level','Pay level'],\r\n  ['application_start','Applications open','date'],\r\n  ['apply_end','Last date','date'],\r\n  ['deadline_text','Deadline as published'],\r\n  ['official_notice_url','Official notice URL','url'],\r\n  ['official_apply_url','Official apply URL','url'],\r\n  ['summary','Summary','textarea'],\r\n];\r\n\r\nfunction govtModalClose(){\r\n  const o=$('govtModalOverlay');\r\n  if(o)o.classList.remove('show');\r\n  document.body.style.overflow='';\r\n}\r\nfunction govtModalOpen(title,sub){\r\n  $('govtModalTitle').textContent=title||'Government job';\r\n  $('govtModalSub').innerHTML=sub||'';\r\n  $('govtModalFields').innerHTML='<p class=\"rm-value\">Loading…</p>';\r\n  $('govtModalActions').innerHTML='';\r\n  $('govtModalOverlay').classList.add('show');\r\n  document.body.style.overflow='hidden';\r\n}\r\nfunction govtModalReadonly(rows){\r\n  $('govtModalFields').innerHTML=rows.map(r=>'<div class=\"rm-field\"><span class=\"rm-label\">'+govtEsc(r[0])\r\n    +'</span><span class=\"rm-value\" style=\"white-space:pre-wrap\">'+(r[1]==null||r[1]===''?'—':govtEsc(String(r[1])))+\r\n    '</span></div>').join('');\r\n}\r\nfunction govtOpenInbox(id){\r\n  const it=(govtCache.inbox||[]).find(x=>x.id===id);\r\n  if(!it){toast('Item not in the loaded inbox — refresh it first.');return;}\r\n  const p=it.payload||{};\r\n  const notice=p.official_notice_url||'';\r\n  const official=govtIsOfficialUrl(notice);\r\n  govtModalOpen(p.title||'(untitled)', govtEsc(p.organization||'')+' · '+govtEsc(p.source_name||p.source_type||'source'));\r\n  govtModalReadonly([\r\n    ['Official notice',official?notice:(notice?'⚠ '+notice+' (not an official host)':'⚠ none found — paste one to publish')],\r\n    ['Lead page',p.source_url],\r\n    ['Inbox kind',it.inbox_kind],\r\n    ['Civil status',(it.civil_status||'')+(p.civil_evidence?' · matched: '+p.civil_evidence:'')],\r\n    ['Summary',(p.summary||p.excerpt||'').slice(0,700)],\r\n  ]);\r\n  /* Same columns the feed itself printed, above the detail — one layout for the queue,\r\n     this dialog and the posting's page on the six sites. */\r\n  $('govtModalFields').innerHTML=govtFeedTable(p)+$('govtModalFields').innerHTML;\r\n  $('govtModalActions').innerHTML=\r\n    '<button class=\"btn-gold\" onclick=\"govtModalClose();govtApprove(\\''+it.id+'\\')\">✅ Publish this</button>'\r\n    +'<button class=\"btn-review\" onclick=\"govtModalClose();govtAiStructure(\\''+it.id+'\\',null)\">🧠 AI Structure</button>'\r\n    +'<button class=\"btn-ghost\" onclick=\"govtModalClose();govtNeedsInfo(\\''+it.id+'\\')\">❓ Needs Info</button>'\r\n    +'<button class=\"btn-reject\" onclick=\"govtModalClose();govtReject(\\''+it.id+'\\')\">✕ Reject</button>'\r\n    +govtNoticeAttachHtml(it.id,p,'govtModalNotice-'+it.id)\r\n    +(p.source_url?'<a class=\"btn-open-src\" href=\"'+govtEsc(p.source_url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Source ↗</a>':'');\r\n}\r\nasync function govtOpenSaved(id){\r\n  govtModalOpen('Government job','Loading the saved record…');\r\n  try{\r\n    const d=await govtAdminApi('/api/govt-review?action=job&id='+encodeURIComponent(id));\r\n    const j=d.job||{};\r\n    govtModalOpen(j.title||'(untitled)', govtEsc(j.organization||'')+(j.status?' · '+govtEsc(j.status):''));\r\n    $('govtModalFields').innerHTML='<div class=\"field-grid\">'+GOVT_EDIT_FIELDS.map(f=>{\r\n      const key=f[0],label=f[1],type=f[2]||'text',opts=f[3];\r\n      const val=j[key]==null?'':String(j[key]);\r\n      const input=type==='select'\r\n        ? '<select data-gk=\"'+key+'\">'+opts.map(o=>'<option value=\"'+o+'\"'+(String(j[key]||'')===o?' selected':'')+'>'+o+'</option>').join('')+'</select>'\r\n        : type==='textarea'\r\n          ? '<textarea data-gk=\"'+key+'\" rows=\"3\">'+govtEsc(val)+'</textarea>'\r\n          : '<input data-gk=\"'+key+'\" type=\"'+type+'\" value=\"'+govtEsc(val)+'\">';\r\n      return '<label'+(type==='textarea'?' class=\"wide\"':'')+'>'+govtEsc(label)+input+'</label>';\r\n    }).join('')+'</div>'\r\n      +'<p class=\"rm-value\" style=\"margin-top:10px;color:#6a8aaa\">Fields left as they are stay unchanged. Every save is audited.</p>';\r\n    $('govtModalActions').innerHTML=\r\n      '<button class=\"btn-gold\" id=\"govtModalSave\">💾 Save changes</button>'\r\n      +(j.slug?'<a class=\"btn-open-src\" href=\"/government-jobs?job='+encodeURIComponent(j.slug)+'\" target=\"_blank\" rel=\"noopener noreferrer\">View public page ↗</a>':'')\r\n      +(j.official_notice_url?'<a class=\"btn-open-src\" href=\"'+govtEsc(j.official_notice_url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Notification ↗</a>':'');\r\n    $('govtModalSave').onclick=async()=>{\r\n      const payload={};\r\n      $('govtModalFields').querySelectorAll('[data-gk]').forEach(el=>{\r\n        const k=el.dataset.gk;\r\n        const v=String(el.value||'').trim();\r\n        const before=j[k]==null?'':String(j[k]);\r\n        if(v!==before)payload[k]=v===''?null:v;\r\n      });\r\n      if(!Object.keys(payload).length){toast('Nothing changed.');return;}\r\n      try{\r\n        await govtPost('update',{id,payload});\r\n        toast('Saved ✓');\r\n        govtModalClose();\r\n        govtLoad(govtActiveTab);\r\n      }catch(e){toast('Save failed: '+e.message);}\r\n    };\r\n  }catch(e){\r\n    $('govtModalFields').innerHTML='<p class=\"rm-value\" style=\"color:#fca5a5\">'+govtEsc(e.message||'Could not load this job.')+'</p>';\r\n  }\r\n}\r\ndocument.addEventListener('DOMContentLoaded',function(){\r\n  const c=$('govtModalClose'); if(c)c.onclick=govtModalClose;\r\n  const o=$('govtModalOverlay');\r\n  if(o)o.addEventListener('click',e=>{if(e.target===o)govtModalClose();});\r\n});\r\n\r\nasync function govtApprove(id){\r\n  if(!confirm('Publish this government job? It becomes publicly visible immediately.'))return;\r\n  try{ await govtPost('approve',{id}); toast('Published ✓ (human-reviewed gate satisfied)'); govtLoad('inbox'); }\r\n  catch(e){toast('Publish failed: '+e.message);}\r\n}\r\nasync function govtReject(id){\r\n  const reason=prompt('Rejection reason (optional):')||'';\r\n  try{ await govtPost('reject',{id,reason}); toast('Rejected'); govtLoad('inbox'); }\r\n  catch(e){toast('Reject failed: '+e.message);}\r\n}\r\nasync function govtNeedsInfo(id){\r\n  try{ await govtPost('needs_info',{id,notes:'Marked needs-info from admin inbox'}); toast('Marked Needs Info'); govtLoad('inbox'); }\r\n  catch(e){toast('Failed: '+e.message);}\r\n}\r\nasync function govtAiStructure(id,btn){\r\n  const old=btn?btn.textContent:null;\r\n  if(btn){btn.disabled=true;btn.textContent='⏳ Thinking…';}\r\n  try{\r\n    const r=await govtPost('ai_structure',{id});\r\n    toast(r.ok?'AI structured the record — review the fields before publishing ✓':('AI structuring unavailable: '+(r.error||'no provider configured')));\r\n    govtLoad('inbox');\r\n  }catch(e){toast('AI structuring failed: '+e.message);}\r\n  finally{if(btn){btn.disabled=false;btn.textContent=old;}}\r\n}\r\nasync function govtPublishDraft(id){\r\n  if(!confirm('Publish this draft? It becomes publicly visible immediately.'))return;\r\n  try{ await govtPost('publish_draft',{id}); toast('Draft published ✓'); govtLoad('drafts'); }\r\n  catch(e){toast('Publish failed: '+e.message);}\r\n}\r\nasync function govtAction(id,action){\r\n  const labels={unpublish:'Unpublish',archive:'Archive',restore:'Restore',mark_verified:'Mark verified',mark_expired:'Mark expired',delete_permanent:'PERMANENTLY delete'};\r\n  if(!confirm(labels[action]+' this government job?'))return;\r\n  try{ await govtPost(action,{id}); toast('Done ✓'); govtLoad(govtActiveTab); }\r\n  catch(e){toast('Failed: '+e.message);}\r\n}\r\nasync function govtDuplicate(id){\r\n  try{ const r=await govtPost('duplicate',{id}); toast('Duplicated as draft ✓'); govtLoad('drafts'); }\r\n  catch(e){toast('Duplicate failed: '+e.message);}\r\n}\r\nasync function govtResolveConflict(id,resolution){\r\n  try{ await govtPost('resolve_conflict',{id,resolution}); toast('Conflict resolved ✓'); govtLoad('conflicts'); }\r\n  catch(e){toast('Resolve failed: '+e.message);}\r\n}\r\nasync function govtResolveManual(id){\r\n  const value=prompt('Authoritative value for this field:');\r\n  if(value===null)return;\r\n  try{ await govtPost('resolve_conflict',{id,resolution:'manual',value}); toast('Conflict resolved manually ✓'); govtLoad('conflicts'); }\r\n  catch(e){toast('Resolve failed: '+e.message);}\r\n}\r\nasync function govtDismissConflict(id){\r\n  try{ await govtPost('dismiss_conflict',{id}); toast('Conflict dismissed'); govtLoad('conflicts'); }\r\n  catch(e){toast('Failed: '+e.message);}\r\n}\r\nasync function govtToggleSource(id,enabled){\r\n  try{ await govtPost('source_toggle',{source_id:id,enabled}); toast(enabled?'Source enabled':'Source disabled'); govtLoad('sources'); }\r\n  catch(e){toast('Failed: '+e.message);}\r\n}\r\nasync function govtDeleteOrg(id){\r\n  if(!confirm('Remove this organization?'))return;\r\n  try{ await govtPost('org_delete',{org_id:id}); toast('Removed'); govtLoad('organizations'); }\r\n  catch(e){toast('Failed: '+e.message);}\r\n}\r\nfunction govtShowOrgForm(){\r\n  const name=prompt('Organization name:'); if(!name)return;\r\n  const kind=prompt('Kind (central/state/psu/railways/authority/other):','other')||'other';\r\n  const website=prompt('Official website (optional):')||null;\r\n  govtPost('org_save',{name,kind,website}).then(()=>{toast('Organization added ✓');govtLoad('organizations');}).catch(e=>toast('Failed: '+e.message));\r\n}\r\nfunction govtShowCreate(){\r\n  const title=prompt('Recruitment title:'); if(!title)return;\r\n  const organization=prompt('Organization:'); if(!organization)return;\r\n  govtPost('create_draft',{payload:{title,organization}}).then(()=>{toast('Draft created ✓');govtLoad('drafts');}).catch(e=>toast('Failed: '+e.message));\r\n}\r\n\r\n/* Load the Government Jobs section when its tab is opened. */\r\ndocument.addEventListener('DOMContentLoaded',function(){\r\n  document.querySelectorAll('#tabs button[data-tab=\"govt\"]').forEach(b=>{\r\n    b.addEventListener('click',function(){ if(!govtLoadedOnce)govtLoad('inbox'); });\r\n  });\r\n});\r\n</script>\r\n</body>\r\n</html>\r\n" };
